import React, { useState, useRef, useEffect } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { baseurImage } from "../../../Baseurl";
import { logout } from "../../../store/userSlice";
import { fetchBusinessSettings } from "../../../store/businessSlice";

export default function Sidebar({ isOpen, onToggle }) {
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.user);
  const businessSettings = useSelector((state) => state.business.businessSettings);
  const businessLoading = useSelector((state) => state.business.loading);
  const [profileOpen, setProfileOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const [avatarVersion, setAvatarVersion] = useState(Date.now());
  const navigate = useNavigate();
  
  console.log('Sidebar - businessSettings:', businessSettings);
  console.log('Sidebar - businessLoading:', businessLoading);

  const dropdownRef = useRef(null);
  const notifRef = useRef(null);


  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setProfileOpen(false);
      }
      if (notifRef.current && !notifRef.current.contains(event.target)) {
        setNotifOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Fetch business settings on component mount
  useEffect(() => {
    const getUserId = () => {
      try {
        const userMedical = localStorage.getItem("userMedical");
        if (userMedical) {
          const userData = JSON.parse(userMedical);
          return userData?.id || userData?.data?.id || null;
        }
        return null;
      } catch (error) {
        console.error("Error parsing userMedical from localStorage:", error);
        return null;
      }
    };

    const doctorId = getUserId();
    console.log('Sidebar - doctorId:', doctorId);
    
    if (doctorId) {
      // Always fetch if we don't have business settings or if they're empty
      if (!businessSettings || !businessSettings.official_name) {
        console.log('Fetching business settings...');
        dispatch(fetchBusinessSettings(doctorId));
      }
    }
  }, [dispatch, businessSettings]);


  useEffect(() => {
    if (user) {
      setAvatarVersion(Date.now());
    }
  }, [user]);


  useEffect(() => {
    const onProfileUpdated = () => setAvatarVersion(Date.now());
    window.addEventListener("profile-updated", onProfileUpdated);
    return () => window.removeEventListener("profile-updated", onProfileUpdated);
  }, []);

  const handleLogout = () => {
    dispatch(logout());
    navigate("");
  };

  const getProfileImg = () => {
    // Fallbacks for first render after login
    let photo = user?.personalPhoto;
    if (!photo) {
      const lsPhoto = localStorage.getItem("userPersonalPhoto");
      if (lsPhoto) photo = lsPhoto;
      if (!photo) {
        try {
          const stored = JSON.parse(localStorage.getItem("userMedical") || "null");
          photo = stored?.data?.personalPhoto || null;
        } catch { }
      }
    }

    if (!photo) return "/assets/images/user/avatar-2.jpg";

    const bustKey = localStorage.getItem("profilePhotoBust") || avatarVersion;
    const bust = `?v=${bustKey}`;

    // Support Blob for immediate preview after upload
    if (typeof photo === "object" && photo instanceof Blob) {
      const url = URL.createObjectURL(photo);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      return url;
    }

    if (typeof photo === "string" && (photo.startsWith("http://") || photo.startsWith("https://"))) {
      return `${photo}${bust}`;
    }

    return `${baseurImage}${String(photo).replace(/^\/+/, "")}${bust}`;
  };

  return (
    <header className="pc-header">
      <div className="header-wrapper">
        <div className="me-auto d-flex align-items-center">
          <span
            className="fw-bold text-primary fs-5"
            style={{
              display: "flex",
              alignItems: "center",
              height: "100%",
              lineHeight: "1",
            }}
          >
            {businessSettings?.official_name || (businessLoading ? "Loading..." : "No Name")}
          </span>
        </div>

        <div className="ms-auto d-flex align-items-center">
          <ul className="list-unstyled d-flex align-items-center mb-0 navList">
            {/* 🔹 Profile dropdown */}
            <li
              className="dropdown pc-h-item header-user-profile d-flex align-items-center"
              ref={dropdownRef}
            >
              <NavLink
                to="/Admin/myprofile"
                className="d-flex align-items-center gap-2"
              >
                <img
                  src={getProfileImg()}
                  alt="user"
                  className="user-avtar profileImg"
                />
                <span>{user?.fullName || user?.name || "User"}</span>
              </NavLink>

              <div
                className={`dropdown-menu dropdown-menu-end p-3 shadow rounded-3 ${profileOpen ? "show" : ""
                  }`}
                style={{
                  width: "280px",
                  maxHeight: "400px",
                  overflowY: "auto",
                  top: "58px",
                  right: "0",
                  position: "absolute",
                  zIndex: "1050",
                }}
              >
                <div className="d-flex align-items-center mb-3">
                  <img
                    src={getProfileImg()}
                    alt="user"
                    className="rounded-circle me-3"
                    style={{ width: "50px", height: "50px" }}
                  />
                  <div>
                    <small className="text-muted">{user?.email}</small>
                  </div>
                  <span
                    className="ms-auto text-danger"
                    style={{ fontSize: "18px", cursor: "pointer" }}
                    onClick={handleLogout}
                  >
                    <i className="ti ti-logout"></i>
                  </span>
                </div>

                <NavLink
                  to="/Admin/myprofile"
                  className="dropdown-item d-flex align-items-center"
                >
                  <i className="ti ti-user me-2 text-muted"></i>
                  <span>View Profile</span>
                </NavLink>

                <NavLink
                  to="/Admin/EditProfile"
                  className="dropdown-item d-flex align-items-center"
                >
                  <i className="ti ti-edit me-2 text-muted"></i>
                  <span>Edit Profile</span>
                </NavLink>

                <NavLink
                  to="/Admin/Changepassword"
                  className="dropdown-item d-flex align-items-center"
                >
                  <i className="ti ti-lock me-2 text-muted"></i>
                  <span>Change Password</span>
                </NavLink>
              </div>
            </li>
          </ul>

          <div>
            <button onClick={handleLogout} className="cancelBtn">
              <i className="ti ti-logout"></i>
              <span>Logout</span>
            </button>
          </div>
        </div>
      </div>
    </header>
  );
}

