import axios from "axios";
import { baseurl } from "../../Baseurl";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import Chip from '@mui/material/Chip';
import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';
import Select from "react-select";

export default function NewRequest() {
  const navigate = useNavigate();
  const [submitted, setSubmitted] = useState(false);
  const [errors, setErrors] = useState({});
  const [patients, setPatients] = useState([]);
  const [labs, setLabs] = useState([]);
  const [doctors, setDoctors] = useState([]);
  const [labServices, setLabServices] = useState([]);
  const [selectedServices, setSelectedServices] = useState([]);
  const [loading, setLoading] = useState({ patients: true, labs: true, doctors: true, services: true });
  const [apiError, setApiError] = useState({ patients: false, labs: false, doctors: false, services: false });
  const [formData, setFormData] = useState({
    patient_id: "",
    lab_id: "",
    doctor_id: "",
    title: "",
    description: "",
    sent_by: "",
    serviceIds: [],
    file: null,
  });


  useEffect(() => {
    const userName = localStorage.getItem('fullName') || 'Unknown User';

    setFormData(prev => ({
      ...prev,
      sent_by: userName
    }));
  }, []);


  const [selectedPatientId, setSelectedPatientId] = useState("");


  const patientOptions = patients.map((patient) => ({
    value: patient.id,
    label: `${patient.firstName} ${patient.lastName}`,
    mobileNumber: patient.mobileNumber || "",
    civilIdNumber: patient.civilIdNumber || "",
    email: patient.email || "",
    age: patient.age || "",
  }));


  const customFilterOption = (option, inputValue) => {
    const searchValue = inputValue.toLowerCase();
    return (
      option.data.label.toLowerCase().includes(searchValue) ||
      option.data.mobileNumber.toLowerCase().includes(searchValue) ||
      option.data.civilIdNumber.toLowerCase().includes(searchValue) ||
      option.data.email.toLowerCase().includes(searchValue) ||
      option.data.age.toString().includes(searchValue)
    );
  };

  useEffect(() => {
    console.log("Fetching patients from:", `${baseurl}getActivePatients`);
    setLoading(prev => ({ ...prev, patients: true }));
    setApiError(prev => ({ ...prev, patients: false }));

    axios.get(`${baseurl}getActivePatients`)
      .then(res => {
        console.log("Patients API response:", res.data);
        if (res.data.success && Array.isArray(res.data.data)) {
          console.log("Setting patients:", res.data.data);
          setPatients(res.data.data);
        } else {
          console.log("Patients API failed or no data:", res.data);
          setApiError(prev => ({ ...prev, patients: true }));
        }
        setLoading(prev => ({ ...prev, patients: false }));
      })
      .catch(err => {
        console.error("Failed to fetch patients", err);
        console.error("Error details:", err.response?.data);
        setApiError(prev => ({ ...prev, patients: true }));
        setLoading(prev => ({ ...prev, patients: false }));
      });
  }, []);
  useEffect(() => {
    console.log("Fetching labs from:", `${baseurl}getAllActiveLabs`);
    setLoading(prev => ({ ...prev, labs: true }));
    setApiError(prev => ({ ...prev, labs: false }));

    axios.get(`${baseurl}getAllActiveLabs`)
      .then(res => {
        console.log("Labs API response:", res.data);
        if (res.data.success && Array.isArray(res.data.data)) {
          console.log("Setting labs:", res.data.data);
          setLabs(res.data.data);
        } else {
          console.log("Labs API failed or no data:", res.data);
          setApiError(prev => ({ ...prev, labs: true }));
        }
        setLoading(prev => ({ ...prev, labs: false }));
      })
      .catch(err => {
        console.error("Failed to fetch labs", err);
        console.error("Error details:", err.response?.data);
        setApiError(prev => ({ ...prev, labs: true }));
        setLoading(prev => ({ ...prev, labs: false }));
      });
  }, []);


  // Fetch lab services when lab is selected
  useEffect(() => {
    if (formData.lab_id) {
      console.log("Fetching lab services for lab ID:", formData.lab_id);
      setLoading(prev => ({ ...prev, services: true }));
      setApiError(prev => ({ ...prev, services: false }));
      setLabServices([]);
      setSelectedServices([]);

      axios.get(`${baseurl}getLabById/${formData.lab_id}`)
        .then(res => {
          console.log("Lab Services API response:", res.data);
          if (res.data.success && res.data.data && Array.isArray(res.data.data.services)) {
            console.log("Setting lab services:", res.data.data.services);
            setLabServices(res.data.data.services);
          } else {
            console.log("Lab Services API failed or no services:", res.data);
            setLabServices([]);
          }
          setLoading(prev => ({ ...prev, services: false }));
        })
        .catch(err => {
          console.error("Failed to fetch lab services", err);
          console.error("Error details:", err.response?.data);
          setApiError(prev => ({ ...prev, services: true }));
          setLoading(prev => ({ ...prev, services: false }));
          setLabServices([]);
        });
    } else {
      // Clear services when no lab is selected
      setLabServices([]);
      setSelectedServices([]);
      setLoading(prev => ({ ...prev, services: false }));
    }
  }, [formData.lab_id]);

  useEffect(() => {

    console.log("Testing API server connection...");
    axios.get(`${baseurl}`)
      .then(res => {
        console.log("API server is reachable:", res.data);
      })
      .catch(err => {
        console.error("API server not reachable:", err);
      });

    console.log("Fetching doctors from:", `${baseurl}getActiveDoctors`);
    setLoading(prev => ({ ...prev, doctors: true }));
    setApiError(prev => ({ ...prev, doctors: false }));

    axios.get(`${baseurl}getActiveDoctors`)
      .then(res => {
        console.log("Doctors API response:", res.data);
        if (res.data.success && Array.isArray(res.data.data)) {
          console.log("Setting doctors:", res.data.data);
          setDoctors(res.data.data);
        } else {
          console.log("Doctors API failed or no data:", res.data);
          setApiError(prev => ({ ...prev, doctors: true }));
        }
        setLoading(prev => ({ ...prev, doctors: false }));
      })
      .catch(err => {
        console.error("Failed to fetch doctors", err);
        console.error("Error details:", err.response?.data);
        setApiError(prev => ({ ...prev, doctors: true }));
        setLoading(prev => ({ ...prev, doctors: false }));
      });
  }, []);

  const handleChange = (e) => {
    const { name, value, files, type } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "file" ? files[0] : value,
    }));
    
    // Clear selected services when lab changes
    if (name === 'lab_id') {
      setSelectedServices([]);
      setFormData(prev => ({
        ...prev,
        serviceIds: []
      }));
    }
  };

  const handlePatientChange = (selectedOption) => {
    if (selectedOption) {
      const selectedId = selectedOption.value;
      const selectedPatient = patients.find(p => String(p.id) === selectedId);
      setSelectedPatientId(selectedId);
      setFormData((prev) => ({
        ...prev,
        patient: selectedPatient ? `${selectedPatient.firstName} ${selectedPatient.lastName}` : "",
        patient_id: selectedId,
        patient_civil_id: selectedPatient ? selectedPatient.civilIdNumber : "",
      }));
    } else {
      setSelectedPatientId("");
      setFormData((prev) => ({
        ...prev,
        patient: "",
        patient_id: "",
        patient_civil_id: "",
      }));
    }
  };


  const handleServicesChange = (event, newValue) => {
    const hasSelectAll = newValue.some((option) => option && option.isSelectAll);

    if (hasSelectAll) {
      const isAllSelected =
        selectedServices &&
        labServices.length > 0 &&
        selectedServices.length === labServices.length;

      const nextServices = isAllSelected ? [] : labServices;
      setSelectedServices(nextServices);
      setFormData((prev) => ({
        ...prev,
        serviceIds: nextServices.map((service) => service.id),
      }));
    } else {
      const filtered = newValue.filter((option) => !option.isSelectAll);
      setSelectedServices(filtered);
      setFormData((prev) => ({
        ...prev,
        serviceIds: filtered.map((service) => service.id),
      }));
    }
  };

  const validate = () => {
    const err = {};
    if (!formData.patient_id) err.patient_id = "Patient ID is required";
    if (!formData.lab_id) err.lab_id = "Lab is required";
    if (!formData.doctor_id) err.doctor_id = "Doctor is required";
    if (!formData.title) err.title = "Title is required";
    if (!formData.description) err.description = "Description is required";
    if (!selectedServices || selectedServices.length === 0) err.serviceIds = "Please select at least one service";
    // sent_by is auto-populated, so no validation needed
    return err;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const foundErrors = validate();
    if (Object.keys(foundErrors).length > 0) {
      setErrors(foundErrors);
      setSubmitted(false);
      return;
    }

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("patient_id", formData.patient_id);
      formDataToSend.append("lab_id", formData.lab_id);
      formDataToSend.append("doctor_id", formData.doctor_id);
      formDataToSend.append("title", formData.title);
      formDataToSend.append("description", formData.description);
      formDataToSend.append("sent_by", formData.sent_by);
      formDataToSend.append("serviceIds", JSON.stringify(selectedServices.map(s => s.id)));
      // Remove file from main request - we'll handle it separately
      // if (formData.file) {
      //   formDataToSend.append("file", formData.file);
      // }

      const response = await axios.post(`${baseurl}addLabRequest`, formDataToSend, {
        headers: { "Content-Type": "multipart/form-data" }
      });

      if (response.data.success) {
        // If a file was uploaded, create an attachment record
        if (formData.file) {
          try {
            const attachmentFormData = new FormData();
            attachmentFormData.append("file", formData.file);
            attachmentFormData.append("name", formData.file.name || "Lab Request Attachment");
            attachmentFormData.append("report_status", "Pending");

            const attachmentResponse = await axios.post(
              `${baseurl}addLabRequestAttachment/${response.data.data.request_id || response.data.data.id}`,
              attachmentFormData,
              {
                headers: { "Content-Type": "multipart/form-data" }
              }
            );

            if (attachmentResponse.data.success) {
              console.log("Attachment added successfully:", attachmentResponse.data);
            } else {
              console.warn("Lab request created but attachment failed:", attachmentResponse.data);
            }
          } catch (attachmentError) {
            console.error("Error adding attachment:", attachmentError);
            // Don't fail the whole request if attachment fails
          }
        }

        Swal.fire({
          icon: "success",
          title: "Success!",
          text: "Lab request added successfully!",
          timer: 1500,
          showConfirmButton: false
        });
        setTimeout(() => navigate("/Admin/ManageLabs"), 1500);

        const userName = localStorage.getItem('userName') || 'Unknown User';
        setFormData({
          patient_id: "",
          lab_id: "",
          doctor_id: "",
          title: "",
          description: "",
          sent_by: userName,
          serviceIds: [],
          file: null,
        });
        setSelectedPatientId("");
        setSelectedServices([]);
        setErrors({});
      } else {
        Swal.fire("Error", response.data.message || "Failed to add request", "error");
      }
    } catch (error) {
      console.error("API Error:", error.response?.data || error);
      Swal.fire("Error", "Server error while adding request", "error");
    }
  };


  // Get selected services names for display
  const getSelectedServicesNames = () => {
    if (!selectedServices || selectedServices.length === 0) {
      return "No services selected";
    }
    return selectedServices.map(service => {
      const serviceName = service.serviceName || service.service || service.service_name || service.name || 'Unknown Service';
      const category = service.category || '';
      return category ? `${serviceName} (${category})` : serviceName;
    }).join(', ');
  };


  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="col-12">
          <div className="card table-card">
            <div className="tableHeader">
              <h5 style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span
                  style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                  onClick={() => navigate(-1)}
                  title="Back"
                >
                  &larr;
                </span>
                Add New Request
              </h5>
            </div>
            <form
              onSubmit={handleSubmit}
              className="row g-3 px-3 py-2 mb-3"
            >
              <div className="col-md-6">
                <label className="form-label">Patient</label>
                <Select
                  classNamePrefix="react-select"
                  className={` ${errors.patient_id ? "is-invalid" : ""}`}
                  name="patient_id"
                  options={patientOptions}
                  value={
                    patientOptions.find(
                      (option) => option.value === selectedPatientId
                    ) || null
                  }
                  getOptionLabel={(e) => e.label}
                  getOptionValue={(e) => e.value}
                  onChange={handlePatientChange}
                  placeholder="Search by Name, Email, Mobile, Civil ID or Age"
                  isSearchable={true}
                  filterOption={customFilterOption}
                  isLoading={loading.patients}
                  isDisabled={loading.patients}
                  menuPortalTarget={document.body}
                  styles={{
                    menuPortal: (base) => ({ ...base, zIndex: 2000 }),
                    menu: (base) => ({ ...base, zIndex: 2000 })
                  }}
                  noOptionsMessage={() => loading.patients ? "Loading patients..." : "No patients found"}
                />
                {apiError.patients && (
                  <p className="text-danger">Failed to load patients. Please try again.</p>
                )}
                {errors && errors.patient_id && (
                  <p className="text-danger">{errors.patient_id}</p>
                )}
              </div>
              {/* <div className="col-md-6">
                <label className="form-label">Patient ID</label>
                <input
                  type="text"
                  name="patient_civil_id"
                  value={formData.patient_civil_id || ""}
                  className="form-control"
                  placeholder="Patient ID"
                  readOnly
                />
                {errors && errors.patient_id && (
                  <p className="text-danger">{errors.patient_id}</p>
                )}
              </div> */}
              <div className="col-md-6">
                <label className="form-label">Lab</label>
                <select
                  className="form-control"
                  name="lab_id"
                  value={formData.lab_id}
                  onChange={handleChange}
                  disabled={loading.labs}
                >
                  <option value="">{loading.labs ? "Loading labs..." : "Select Lab"}</option>
                  {!loading.labs && !apiError.labs && labs.map((lab) => (
                    <option key={lab.id} value={lab.id}>
                      {lab.lab_name}
                    </option>
                  ))}
                </select>
                {apiError.labs && (
                  <p className="text-danger">Failed to load labs. Please try again.</p>
                )}
                {errors && errors.lab_id && (
                  <p className="text-danger">{errors.lab_id}</p>
                )}
              </div>



              {/* Lab Services Selection */}
              <div className="col-md-12">
                <label className="form-label">Lab Services</label>
                <Autocomplete
                  multiple
                  id="lab-services-autocomplete"
                  options={labServices}
                  disablePortal
                  ListboxProps={{ style: { zIndex: 1200 } }}
                  getOptionLabel={(option) => {
                    const serviceName = option.serviceName || option.service || option.service_name || option.name || 'Unknown Service';
                    const category = option.category || '';
                    const price = option.price ? `${option.price} BHD` : '';
                    let label = serviceName;
                    if (category) label += ` (${category})`;
                    if (price) label += ` - ${price}`;
                    return label;
                  }}
                  value={selectedServices}
                  onChange={handleServicesChange}
                  loading={loading.services}
                  disabled={loading.services || !formData.lab_id}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      label="Select Lab Services"
                      placeholder={formData.lab_id ? "Search and select services..." : "Please select a lab first"}
                      error={!!errors.serviceIds}
                      helperText={errors.serviceIds}
                    />
                  )}
                  renderTags={(value, getTagProps) =>
                    value.map((option, index) => {
                      const serviceName = option.serviceName || option.service || option.service_name || option.name || 'Unknown Service';
                      const category = option.category || '';
                      return (
                        <Chip
                          key={option.id}
                          label={(() => {
                            let label = serviceName;
                            if (category) label += ` (${category})`;
                            if (option.price) label += ` - ${option.price} BHD`;
                            return label;
                          })()}
                          {...getTagProps({ index })}
                          color="primary"
                          variant="outlined"
                        />
                      );
                    })
                  }
                  renderOption={(props, option) => {
                    if (option.isSelectAll) {
                      return (
                        <li {...props}>
                          <strong>Select / Deselect All </strong>
                        </li>
                      );
                    }
                    const serviceName = option.serviceName || option.service || option.service_name || option.name || 'Unknown Service';
                    const category = option.category || '';
                    const price = option.price || 0;
                    return (
                      <li {...props}>
                        <div>
                          <strong>{serviceName}</strong>
                          {category && (
                            <small className="text-muted d-block">
                              Category: {category}
                            </small>
                          )}
                          {price > 0 && (
                            <small className="text-success d-block">
                              Price: {price} BHD
                            </small>
                          )}
                        </div>
                      </li>
                    );
                  }}
                  filterOptions={(options, { inputValue }) => {
                    const searchLower = inputValue.toLowerCase();
                    const filtered = options.filter((option) => {
                      const serviceName = option.serviceName || option.service || option.service_name || option.name || '';
                      const category = option.category || '';
                      return (
                        serviceName.toLowerCase().includes(searchLower) ||
                        category.toLowerCase().includes(searchLower)
                      );
                    });

                    if (!inputValue) {
                      return [
                        {
                          id: "__all__",
                          serviceName: "Select All Services",
                          isSelectAll: true,
                        },
                        ...filtered,
                      ];
                    }

                    return filtered;
                  }}
                  noOptionsText="No services found"
                  loadingText="Loading services..."
                />
                {apiError.services && (
                  <p className="text-danger">Failed to load lab services. Please try again.</p>
                )}
              </div>

              {/* Doctor dropdown */}
              <div className="col-md-6">
                <label className="form-label">Doctor</label>
                <select
                  className="form-control"
                  name="doctor_id"
                  value={formData.doctor_id}
                  onChange={handleChange}
                  disabled={loading.doctors}
                >
                  <option value="">{loading.doctors ? "Loading doctors..." : "Select Doctor"}</option>
                  {console.log("Rendering doctors dropdown with:", doctors.length, "doctors")}
                  {!loading.doctors && !apiError.doctors && doctors.map((doc) => (
                    <option key={doc.id} value={doc.id}>
                      {doc.fullName}
                    </option>
                  ))}
                </select>
                {apiError.doctors && (
                  <p className="text-danger">Failed to load doctors. Please try again.</p>
                )}
                {errors && errors.doctor_id && (
                  <p className="text-danger">{errors.doctor_id}</p>
                )}
              </div>

              {/* Title and Description fields */}
              {["title", "description"].map((field) => (
                <div className="col-md-6" key={field}>
                  <label className="form-label">
                    {field.replace(/_/g, " ").replace(/\b\w/g, l => l.toUpperCase())}
                  </label>
                  <input
                    type={field === "days" ? "number" : "text"}
                    name={field}
                    value={formData[field]}
                    onChange={handleChange}
                    className="form-control"
                    placeholder={field.replace(/_/g, " ")}
                  />
                  {errors && errors[field] && (
                    <p className="text-danger">{errors[field]}</p>
                  )}
                </div>
              ))}

              {/* Sent By field - Auto-populated and read-only */}
              {/* <div className="col-md-6">
                <label className="form-label">Sent By</label>
                <input
                  type="text"
                  name="sent_by"
                  value={formData.fullName}
                  className="form-control"
                  placeholder="Sent By"
                  readOnly
                />
                {errors && errors.sent_by && (
                  <p className="text-danger">{errors.sent_by}</p>
                )}
              </div> */}

              {/* Attachment field */}
              <div className="col-md-6">
                <label className="form-label">Attachment</label>
                <input
                  type="file"
                  name="file"
                  onChange={handleChange}
                  className="form-control"
                  accept="image/*,application/pdf,.doc,.docx"
                />
                {formData.file && (
                  <small className="text-muted">
                    Selected file: {formData.file.name}
                  </small>
                )}
                {errors && errors.file && (
                  <p className="text-danger">{errors.file}</p>
                )}
              </div>

              <div className="col-12 mb-3 text-center">
                <button type="submit" className="bgBtn">
                  Add Request
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>


    </div>
  );
}