import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import { baseurl, baseurImage } from "../../Baseurl";
import AddInsuranceCard from "./AddInsuranceCard";
import { usePDF } from "react-to-pdf";
import EventBus from "../../Context/EventBus";

export default function PatientInsurance({ patientId }) {
  // State for modals and data
  const [showAddCardModal, setShowAddCardModal] = useState(false);
  const [loading, setLoading] = useState(false);
  const [insuranceCards, setInsuranceCards] = useState([]);
  const [insuranceCompanies, setInsuranceCompanies] = useState([]);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingCardId, setEditingCardId] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [editForm, setEditForm] = useState({
    issue_date: "",
    expiry_date: "",
    co_insurance_percent: "",
    deductible_amount: "",
    policy_number: "",
    company_id: "",
    scanned_copy: null,
  });

  // New Claims modal state
  const [showNewClaimModal, setShowNewClaimModal] = useState(false);
  const [claimForm, setClaimForm] = useState({
    card_id: "",
    invoice_id: "",
    is_deductible_applied: false,
    status: "Pending"
  });
  const [invoices, setInvoices] = useState([]);
  const [selectedInvoice, setSelectedInvoice] = useState(null);
  const [claimCalculations, setClaimCalculations] = useState({
    invoiceAmount: 0,
    deductibleAmount: 0,
    afterDeductible: 0,
    coInsurancePercent: 0,
    claimAmount: 0,
    patientAmount: 0
  });


  const [overrideCoInsPercent, setOverrideCoInsPercent] = useState("");


  const [claims, setClaims] = useState([]);
  const [claimsLoading, setClaimsLoading] = useState(false);
  
  // Pagination state
  const [currentClaimPage, setCurrentClaimPage] = useState(1);
  const claimsPerPage = 10;

  // Active insurance cards just for New Claim modal
  const [activeClaimCards, setActiveClaimCards] = useState([]);
  const [activeCardsLoading, setActiveCardsLoading] = useState(false);

  // PDF generation
  const { toPDF, targetRef } = usePDF({ filename: 'insurance-claim.pdf' });
  const [printData, setPrintData] = useState(null);
  const [printLoading, setPrintLoading] = useState(false);

  
  // const [services] = useState([
  //   {
  //     sn: 221,
  //     doctor: "Dr Ali",
  //     category: "Dental",
  //     service: "Root Canal Treatment",
  //     price: "100.000BHD",
  //     discount: "0",
  //     total: "100.000BHD",
  //     deductible: "30 BHD",
  //     copat: "30 BHD",
  //     coins: "30 BHD",
  //     status: "Pending"
  //   },
  //   {
  //     sn: 221,
  //     doctor: "Dr Ali",
  //     category: "Dental",
  //     service: "Root Canal Treatment",
  //     price: "100.000BHD",
  //     discount: "0",
  //     total: "100.000BHD",
  //     deductible: "30 BHD",
  //     copat: "30 BHD",
  //     coins: "30 BHD",
  //     status: "Approved"
  //   }
  // ]);

 
  useEffect(() => {
    loadInsuranceCards();
    loadInsuranceCompanies();
    loadInvoices();
    loadClaims();
  }, [patientId]);

  // Listen for new invoices so New Claim invoice dropdown updates without refresh
  useEffect(() => {
    const off = EventBus.on("invoice:created", (e) => {
      try {
        const evtPatientId = e?.detail?.patientId;
        if (!evtPatientId) { loadInvoices(); return; }
        if (Number(evtPatientId) === Number(patientId)) {
          loadInvoices();
        }
      } catch (_) {
        loadInvoices();
      }
    });
    return () => { off && off(); };
  }, [patientId]);

  
  const formatDateOnly = (value) => {
    if (!value) return "";
    try {
      const date = new Date(value);
      if (!isNaN(date.getTime())) {
        return date.toLocaleDateString("en-GB");
      }
      return String(value).toString().split("T")[0];
    } catch (e) {
      return String(value).toString().split("T")[0] || String(value);
    }
  };

  
  const toInputDate = (value) => {
    if (!value) return "";
    try {
      const date = new Date(value);
      if (!isNaN(date.getTime())) {
        const y = date.getFullYear();
        const m = String(date.getMonth() + 1).padStart(2, "0");
        const d = String(date.getDate()).padStart(2, "0");
        return `${y}-${m}-${d}`;
      }
      return String(value).split("T")[0];
    } catch (e) {
      return String(value).split("T")[0];
    }
  };

  const openEditModal = (card) => {
    setEditingCardId(card.card_id || card.id);
    setEditForm({
      issue_date: toInputDate(card.issue_date),
      expiry_date: toInputDate(card.expiry_date),
      co_insurance_percent: card.co_insurance_percent ?? "",
      deductible_amount: card.deductible_amount ?? "",
      policy_number: card.policy_number ?? "",
      company_id: card.company_id ?? "",
      scanned_copy: null,
    });
    setShowEditModal(true);
  };

  const handleEditChange = (e) => {
    const { name, value, type, files } = e.target;
    if (type === 'file') {
      setEditForm((prev) => ({ ...prev, [name]: files[0] || null }));
    } else {
      setEditForm((prev) => ({ ...prev, [name]: value }));
    }
  };

  const submitEdit = async (e) => {
    e?.preventDefault?.();
    if (!editingCardId) return;
    try {
      setLoading(true);
      const url = `${baseurl}editInsuranceCard/${editingCardId}`;
      
      // Create FormData for file upload
      const formData = new FormData();
      formData.append('issue_date', editForm.issue_date);
      formData.append('expiry_date', editForm.expiry_date);
      formData.append('co_insurance_percent', editForm.co_insurance_percent);
      formData.append('deductible_amount', editForm.deductible_amount);
      formData.append('policy_number', editForm.policy_number);
      formData.append('company_id', editForm.company_id);
      
      // Only append file if a new one is selected
      if (editForm.scanned_copy) {
        formData.append('scanned_copy', editForm.scanned_copy);
      }
      
      const res = await axios.put(url, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      
      if (res.data?.success) {
        Swal.fire('Success', 'Insurance card updated successfully', 'success');
        setShowEditModal(false);
        setEditingCardId(null);
        await loadInsuranceCards();
      } else {
        Swal.fire('Error', res.data?.message || 'Failed to update insurance card', 'error');
      }
    } catch (error) {
      console.error('Edit insurance card error:', error);
      Swal.fire('Error', 'Failed to update insurance card', 'error');
    } finally {
      setLoading(false);
    }
  };

 
  const loadInsuranceCards = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${baseurl}getAllInsuranceCards`);
      if (response.data.success) {
       
        const patientCards = response.data.data.filter(card => card.patient_id == patientId);
        setInsuranceCards(patientCards);
      }
    } catch (error) {
      console.error("Error loading insurance cards:", error);
    
      // setInsuranceCards([
      //   {
      //     status: "Active",
      //     company: "Next Care Will",
      //     policy: "345683246",
      //     patient: "John Ward",
      //     issue: "31-09-25",
      //     expiry: "31-09-25",
      //     deductible: "3000",
      //     copatient: "20%",
      //     coins: "50%",
      //   },
      //   {
      //     status: "Expired",
      //     company: "Next Care Will",
      //     policy: "345683246",
      //     patient: "John Ward",
      //     issue: "31-09-25",
      //     expiry: "31-09-25",
      //     deductible: "3000",
      //     copatient: "20%",
      //     coins: "50%",
      //   },
      // ]);
    } finally {
      setLoading(false);
    }
  };

  
  const loadInsuranceCompanies = async () => {
    try {
      const response = await axios.get(`${baseurl}getActiveInsuranceCompanies`);
      if (response.data.success) {
        setInsuranceCompanies(response.data.data || []);
      }
    } catch (error) {
      console.error("Error loading insurance companies:", error);
    }
  };

  
  const handleDeleteCard = async (cardId) => {
    console.log(cardId);
    try {
      const result = await Swal.fire({
        title: 'Are you sure?',
        text: "You won't be able to revert this!",
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#3085d6',
        cancelButtonColor: '#d33',
        confirmButtonText: 'Yes, delete it!'
      });

      if (result.isConfirmed) {
        const response = await axios.delete(`${baseurl}deleteInsuranceCard/${cardId?.card_id}`);
        if (response.data.success) {
          Swal.fire('Deleted!', 'Insurance card has been deleted.', 'success');
          loadInsuranceCards(); 
        } else {
          Swal.fire('Error', 'Failed to delete insurance card', 'error');
        }
      }
    } catch (error) {
      console.error("Error deleting insurance card:", error);
      Swal.fire('Error', 'Failed to delete insurance card', 'error');
    }
  };

  // Handle successful card addition
  const handleCardAdded = () => {
    loadInsuranceCards();
  };

  // Load invoices for claims
  const loadInvoices = async () => {
    try {
      const response = await axios.get(`${baseurl}getUnusedInvoicesByPatient/${patientId}`);
      const list = Array.isArray(response.data?.invoices)
        ? response.data.invoices
        : Array.isArray(response.data?.data)
        ? response.data.data
        : Array.isArray(response.data)
        ? response.data
        : [];

      // Normalize keys for consistent downstream usage
      const normalized = (list || []).map((inv) => {
        const id = inv.invoiceId ?? inv.invoice_id ?? inv.id ?? inv.invoiceid;
        const dateStr = inv.invoice_date ?? inv.updated_at ?? inv.updatedAt ?? inv.date;
        return {
          ...inv,
          id,
          invoice_no: inv.invoice_no ?? inv.invoiceNo ?? id,
          invoice_date: dateStr,
          total_amount: inv.total_amount ?? inv.totalAmount ?? inv.amount ?? 0,
          remaining_amount: inv.remaining_amount ?? inv.remaining ?? inv.remainingAmount ?? 0,
          status_text: (inv.invoice_status || inv.status || "").toString().toLowerCase(),
        };
      });

      // Show only invoices that have some remaining, or are textually unpaid/partial
      const filtered = normalized.filter((inv) => {
        const remaining = Number(inv.remaining_amount);
        if (!isNaN(remaining) && remaining > 0) return true;
        return inv.status_text === "not paid" || inv.status_text === "unpaid" || inv.status_text === "partial paid" || inv.status_text === "partially paid";
      });

      setInvoices(filtered);
    } catch (error) {
      console.error("Error loading invoices:", error);
      setInvoices([]);
    }
  };
  

  // Open New Claims modal
  const openNewClaimModal = () => {
    setShowNewClaimModal(true);
    setClaimForm({
      card_id: "",
      invoice_id: "",
      is_deductible_applied: false,
      status: "Pending"
    });
    setSelectedInvoice(null);
    setOverrideCoInsPercent("");
    setClaimCalculations({
      invoiceAmount: 0,
      deductibleAmount: 0,
      afterDeductible: 0,
      coInsurancePercent: 0,
      claimAmount: 0,
      patientAmount: 0
    });
    // Load only active cards for this patient for the dropdown
    loadActiveCardsForClaims();
  };

  // Fetch only ACTIVE insurance cards for patient (API gives active only)
  const loadActiveCardsForClaims = async () => {
    try {
      setActiveCardsLoading(true);
      const response = await axios.get(`${baseurl}getInsuranceCardsByPatientId/${patientId}`);
      const list = Array.isArray(response.data?.data)
        ? response.data.data
        : Array.isArray(response.data)
          ? response.data
          : [];
      setActiveClaimCards(list);
    } catch (error) {
      console.error("Error loading active insurance cards:", error);
      setActiveClaimCards([]);
    } finally {
      setActiveCardsLoading(false);
    }
  };

  // Load insurance claims for the patient
  const loadClaims = async () => {
    try {
      setClaimsLoading(true);
      
      const response = await axios.get(`${baseurl}getInsuranceClaimsByPatientId/${patientId}`);
      const list = Array.isArray(response.data?.data)
        ? response.data.data
        : Array.isArray(response.data)
          ? response.data
          : [];
      setClaims(list);
    } catch (error) {
      console.error("Error loading insurance claims:", error);
      setClaims([]);
    } finally {
      setClaimsLoading(false);
    }
  };

  // Handle claim form changes
  const handleClaimFormChange = (e) => {
    const { name, value, type, checked } = e.target;
    setClaimForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const filteredClaims = claims.filter(
    (claim) =>
      claim.claim_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      claim.invoice_no?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      claim.invoiceNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      claim.invoice_total?.toString().includes(searchTerm) ||
      claim.insurance_amount?.toString().includes(searchTerm) ||
      claim.patient_amount?.toString().includes(searchTerm) ||
      claim.status?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Pagination calculations
  const totalClaimPages = Math.ceil(filteredClaims.length / claimsPerPage) || 1;
  const currentClaims = filteredClaims.slice(
    (currentClaimPage - 1) * claimsPerPage,
    currentClaimPage * claimsPerPage
  );

 
  useEffect(() => {
    if (claimForm.card_id && claimForm.invoice_id) {
    
      const selectedCard = (activeClaimCards.find(card => (card.card_id || card.id) == claimForm.card_id)
        || insuranceCards.find(card => (card.card_id || card.id) == claimForm.card_id));
      const selectedInv = invoices.find(inv => inv.id == claimForm.invoice_id);
      
      if (selectedCard && selectedInv) {
        setSelectedInvoice(selectedInv);
        
        const invoiceAmount = Number(selectedInv.total_amount || selectedInv.amount || 0);
        const deductibleAmount = Number(selectedCard.deductible_amount || 0);
        const coInsurancePercent = Number(
          (overrideCoInsPercent !== "" && overrideCoInsPercent !== null && overrideCoInsPercent !== undefined)
            ? overrideCoInsPercent
            : (selectedCard.co_insurance_percent || 0)
        );
        
        const afterDeductible = claimForm.is_deductible_applied 
          ? Math.max(0, invoiceAmount - deductibleAmount)
          : invoiceAmount;
        
        const claimAmount = (afterDeductible * coInsurancePercent) / 100;
        const patientAmount = afterDeductible - claimAmount;
        
        setClaimCalculations({
          invoiceAmount,
          deductibleAmount,
          afterDeductible,
          coInsurancePercent,
          claimAmount,
          patientAmount
        });
      }
    }
  }, [claimForm, insuranceCards, activeClaimCards, invoices, overrideCoInsPercent]);

  // Submit new claim
  const submitNewClaim = async (e) => {
    e.preventDefault();
    if (!claimForm.card_id || !claimForm.invoice_id) {
      Swal.fire("Error", "Please select both insurance card and invoice", "error");
      return;
    }

    try {
      setLoading(true);
      // Determine co-insurance percent to send (edited or from card)
      const selectedCard = (activeClaimCards.find(card => (card.card_id || card.id) == claimForm.card_id)
        || insuranceCards.find(card => (card.card_id || card.id) == claimForm.card_id));
      const finalCoInsPercent = Number(
        (overrideCoInsPercent !== "" && overrideCoInsPercent !== null && overrideCoInsPercent !== undefined)
          ? overrideCoInsPercent
          : (selectedCard?.co_insurance_percent || 0)
      );
      const payload = {
        patient_id: Number(patientId),
        card_id: Number(claimForm.card_id),
        invoice_id: Number(claimForm.invoice_id),
        is_deductible_applied: claimForm.is_deductible_applied ? 1 : 0,
        co_insurance_percent: finalCoInsPercent
      };

      const response = await axios.post(`${baseurl}addInsuranceClaim`, payload);
      
      if (response.data?.success) {
        Swal.fire("Success", "Insurance claim created successfully", "success");
        setShowNewClaimModal(false);
        // Reset form
        setClaimForm({
          card_id: "",
          invoice_id: "",
          is_deductible_applied: false,
          status: "Pending"
        });
        setOverrideCoInsPercent("");
        // Refresh claims list
        loadClaims();
      } else {
        Swal.fire("Error", response.data?.message || "Failed to create claim", "error");
      }
    } catch (error) {
      console.error("Error creating claim:", error);
      Swal.fire("Error", "Failed to create insurance claim", "error");
    } finally {
      setLoading(false);
    }
  };

  
  const handlePrint = async () => {
    try {
      setPrintLoading(true);
      // Fetch printable claims via API, then render and print
      const response = await axios.get(`${baseurl}getClaimsByPatientIdPdf/${patientId}`);
      const list = Array.isArray(response.data?.data)
        ? response.data.data
        : Array.isArray(response.data)
          ? response.data
          : [];

      if (!Array.isArray(list) || list.length === 0) {
        // Fallback to currently loaded claims if API returns empty
        if (!claims || claims.length === 0) {
          Swal.fire("No Data", "No claims available to print", "warning");
          return;
        }
      }

      const rows = (list.length ? list : claims).map((c, idx) => `
        <tr>
          <td>${idx + 1}</td>
          <td>${c.claim_number || ''}</td>
          <td>${c.invoice_no || c.invoiceNumber || c.invoice_id || ''}</td>
          <td style="text-align:right">${Number(c.invoice_total || 0).toFixed(2)} BHD</td>
          <td>${(String(c.is_deductible_applied || c.is_deductible) === '1' || c.is_deductible_applied === true) ? 'Yes' : 'No'}</td>
          <td style="text-align:right">${Number(c.co_insurance_percent || 0)}%</td>
          <td style="text-align:right">${Number(c.insurance_amount || 0).toFixed(2)} BHD</td>
          <td style="text-align:right">${Number(c.patient_amount || 0).toFixed(2)} BHD</td>
          <td>${String(c.patient_name || c.patient || '')}</td>
          <td>${String(c.policy_number || '')}</td>
          <td>${String(c.mobileNumber || c.mobile || c.phone || '')}</td>
          <td>${String(c.gender || '')}</td>
          <td>${String(c.age || '')}</td>
          <td>${(() => { try { const d = new Date(c.invoice_date || c.invoiceDate); return isNaN(d.getTime()) ? '-' : d.toLocaleDateString('en-GB'); } catch { return '-'; } })()}</td>
          <td>${c.status || ''}</td>
          <td>${(() => { try { const d = new Date(c.created_at || c.createdAt || c.date); return isNaN(d.getTime()) ? '-' : d.toLocaleDateString('en-GB'); } catch { return '-'; } })()}</td>
        </tr>
      `).join('');

      const html = `
        <html>
          <head>
            <title>Insurance Claims</title>
            <style>
              body { font-family: Arial, sans-serif; padding: 24px; }
              h2 { margin: 0 0 8px; }
              .muted { color: #7f8c8d; font-size: 12px; }
              table { width: 100%; border-collapse: collapse; margin-top: 16px; font-size: 12px; }
              th, td { border: 1px solid #ddd; padding: 8px; }
              th { background: #f5f5f5; text-align: left; }
              .right { text-align: right; }
            </style>
          </head>
          <body>
            <h2>Insurance Claims (Patient wise)</h2>
            <div class="muted">Generated on: ${new Date().toLocaleDateString('en-GB')}</div>
            <table>
              <thead>
                <tr>
                  <th>#</th>
                  <th>Claim No</th>
                  <th>Invoice No</th>
                  <th class="right">Invoice Total</th>
                  <th>Deductible</th>
                  <th class="right">Co-Ins %</th>
                  <th class="right">Insurance Amt</th>
                  <th class="right">Patient Amt</th>
                  <th>Patient Name</th>
                  <th>Policy #</th>
                  <th>Mobile</th>
                  <th>Gender</th>
                  <th>Age</th>
                  <th>Invoice Date</th>
                  <th>Status</th>
                  <th>Created</th>
                </tr>
              </thead>
              <tbody>${rows}</tbody>
              <tfoot>
                <tr>
                  <td colspan="16" class="right"><strong>Total Claims: ${(list.length ? list : claims).length}</strong></td>
                </tr>
              </tfoot>
            </table>
            <script>window.print();</script>
          </body>
        </html>`;

      const w = window.open('', '_blank');
      if (!w) return;
      w.document.open();
      w.document.write(html);
      w.document.close();
    } catch (error) {
     
      try {
        await toPDF();
      } catch (e) {
        console.error('Error printing claims:', error, e);
        Swal.fire('Error', 'Failed to print claims', 'error');
      }
    } finally {
      setPrintLoading(false);
    }
  };

  return (
    <div className="col-12">
      <div className="table-card patientCardHeader">
        <div
          className="tableHeader"
          style={{ borderBottom: "1px solid #e8ebee" }}
        >
          <div className="d-flex align-items-center justify-content-between">
            <h5>Insurance</h5>
            <div>
              <div className="d-flex">
                <button className="borderBtn me-2" onClick={openNewClaimModal}>
                  New Claims
                </button>
                <button 
                  className="bgBtn me-2"
                  onClick={() => setShowAddCardModal(true)}
                >
                  Add Card
                </button>
                {/* <button className="bgBtn">
                  Add Insurance
                </button> */}
              </div>
            </div>
          </div>
        </div>
        <div>
          <div className="row p-4">
            <div className="col-lg-8">
              <div className="borderInsure">
                <div className="serviceHis">
                  <div className="d-flex justify-content-between tableHeader  secClaim">
                    <div className="d-flex align-items-center">
                      {/* <div>
                        <span>
                          {" "}
                          <strong>Claims</strong>
                        </span>
                        <span className="text-muted">(Patient wise)</span>
                      </div> */}
                      <div className="ps-3">
                        <span>
                          {/* <strong>Total:</strong> {filteredClaims?.length || 0} */}
                        </span>
                      </div>
                      <div className="ps-3">
                        <div className="tableSearch" style={{ position: 'relative', width: '250px' }}>
                          <input
                            type="text"
                            placeholder="Search claims..."
                            className="form-control"
                            value={searchTerm}
                            onChange={handleSearchChange}
                            style={{ paddingLeft: '35px' }}
                          />
                          <span className="searchIcon">
                            <svg
                              xmlns="http://www.w3.org/2000/svg"
                              width="18"
                              height="18"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="gray"
                              style={{
                                position: "absolute",
                                top: "50%",
                                left: "10px",
                                transform: "translateY(-50%)",
                                pointerEvents: "none",
                              }}
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M21 21l-4.35-4.35M17 10a7 7 0 11-14 0 7 7 0 0114 0z"
                              />
                            </svg>
                          </span>
                        </div>
                      </div>
                    </div>

                    <div className="d-flex gap- align-items-center iconTab">
                      {printLoading ? (
                        <div className="spinner-border spinner-border-sm" role="status" title="Generating PDF...">
                          <span className="visually-hidden">Loading...</span>
                        </div>
                      ) : (
                        <i 
                          className="ti ti-printer" 
                          style={{ cursor: 'pointer' }}
                          onClick={handlePrint}
                          title="Print Claims"
                        ></i>
                      )}
                      {/* <i className="ti ti-edit "></i> */}
                      {/* <button className="borderBtn me-2">
                        Send
                      </button>
                      <button className="bgBtn">Pay</button> */}
                    </div>
                  </div>
                </div>
                <div className="card-body p-0 mt-0">
                  <div className="table-responsive mt-0">
                    {claimsLoading ? (
                      <div className="text-center p-3">Loading claims...</div>
                    ) : currentClaims.length === 0 ? (
                      <div className="text-center p-3 text-muted">No claims found</div>
                    ) : (
                      <table>
                        <thead>
                          <tr>
                            <th>#</th>
                            <th>Claim No</th>
                            <th>Invoice No</th>
                            <th>Invoice Total</th>
                            <th>Deductible</th>
                            <th>Co-Ins %</th>
                            
                            <th>Remaining Insurance Amt</th>
                            <th>Total Insurance Amt</th>
                            <th>Patient Amt</th>
                            <th>Status</th>
                            <th>Created</th>
                          </tr>
                        </thead>
                        <tbody>
                          {currentClaims.map((c, idx) => {
                            const serial = (currentClaimPage - 1) * claimsPerPage + idx + 1;
                            return (
                            <tr key={c.claim_id || idx}>
                              <td>{serial}</td>
                              <td>{c.claim_number}</td>
                              <td>{c.invoice_no || c.invoiceNumber || c.invoice_id}</td>
                              <td>{Number(c.invoice_total || 0).toFixed(2)} BHD</td>
                              <td>{c.deductible_amount} BHD</td>
                              <td>{Number(c.co_insurance_percent || 0)}%</td>
                              <td className="text-success">{Number(c.remaining_ins_amount || 0).toFixed(2)} BHD</td>
                              <td className="text-success">{Number(c.insurance_amount || 0).toFixed(2)} BHD</td>
                              <td className="text-warning">{Number(c.patient_amount || 0).toFixed(2)} BHD</td>
                              <td>{c.status}</td>
                              <td>{formatDateOnly(c.created_at)}</td>
                            </tr>
                          )})}
                        </tbody>
                      </table>
                    )}
                  </div>
                  
                  {/* Pagination */}
                  {totalClaimPages > 1 && (
                    <nav className="tablepagination d-flex justify-content-end mt-3 mb-2">
                      <ul className="pagination mb-0">
                        <li
                          className={`page-item ${
                            currentClaimPage === 1 ? "disabled" : ""
                          }`}
                        >
                          <button
                            className="page-link"
                            onClick={() =>
                              currentClaimPage > 1 &&
                              setCurrentClaimPage(currentClaimPage - 1)
                            }
                          >
                            &laquo;
                          </button>
                        </li>

                        <li className="pageNmbr">{`${currentClaimPage} of ${totalClaimPages}`}</li>

                        <li
                          className={`page-item ${
                            currentClaimPage === totalClaimPages
                              ? "disabled"
                              : ""
                          }`}
                        >
                          <button
                            className="page-link"
                            onClick={() =>
                              currentClaimPage < totalClaimPages &&
                              setCurrentClaimPage(currentClaimPage + 1)
                            }
                          >
                            &raquo;
                          </button>
                        </li>
                      </ul>
                    </nav>
                  )}
                  
                  <div className="d-flex justify-content-end align-items-center px-3 py-2">
                    <div>
                      <span>
                        {/* <strong className="pe-2">Total Claims:</strong> {filteredClaims?.length || 0} */}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div className="col-lg-4">
              {loading ? (
                <div className="text-center p-4">
                  <div className="spinner-border" role="status">
                    <span className="visually-hidden">Loading...</span>
                  </div>
                </div>
              ) : insuranceCards.length === 0 ? (
                <div className="text-center p-4">
                  <p className="text-muted">No insurance cards found</p>
                </div>
              ) : (
                insuranceCards.map((card, idx) => {
                  // Get company name from companies list
                  const company = insuranceCompanies.find(comp => comp.company_id == card.company_id);
                  const companyName = company ? company.company_name : 'Unknown Company';
                  
                  // Determine card status based on expiry date
                  const currentDate = new Date();
                  currentDate.setHours(0, 0, 0, 0);
                  const expiryDate = new Date(card.expiry_date);
                  expiryDate.setHours(0, 0, 0, 0);
                  const isExpired = expiryDate < currentDate;
                  const status = isExpired ? "Expired" : "Active";
                  
                  // Calculate co-patient percentage
                  const coInsurance = parseFloat(card.co_insurance_percent) || 0;
                  const coPatient = 100 - coInsurance;
                  
                  return (
                    <div
                      className={`insureCard mb-3`}
                      key={card.card_id || card.id || idx}
                      style={{
                        backgroundColor:
                          status === "Active"
                            ? "#fef5e6"
                            : "#fff7f5",
                      }}
                    >
                      <div className="d-flex justify-content-between align-items-center tableHeader cardInsureAlign">
                        <div>
                          <h5>Insurance Card {idx + 1}</h5>
                        </div>
                        <div className="d-flex align-items-center gap-2">
                         
                          <p
                            className={`ms-2 badge bg-${
                              status === "Active"
                                ? "success"
                                : "danger"
                            }`}
                          >
                            {status === "Active" ? "Status Active" : "Status Expired"}
                          </p>
                           <button
                            className="btn btn-sm btn-outline-primary"
                            onClick={() => openEditModal(card)}
                            title="Edit Card"
                          >
                            <i className="ti ti-edit"></i>
                          </button>
                          <button
                            className="btn btn-sm btn-outline-danger"
                            onClick={() => handleDeleteCard(card)}
                            title="Delete Card"
                          >
                            <i className="ti ti-trash"></i>
                          </button>
                        </div>
                      </div>
                      <div className="p20">
                        <p className="mb-1">
                          <strong>Company Name:</strong> {companyName}
                        </p>
                        <p className="mb-1">
                          <strong>Policy Number:</strong> {card.policy_number}
                        </p>
                        <p className="mb-1">
                          <strong>Issue Date:</strong> {formatDateOnly(card.issue_date)}
                        </p>
                        <p className="mb-1">
                          <strong>Expiry Date:</strong> {formatDateOnly(card.expiry_date)}
                        </p>
                        <p className="mb-1">
                          <strong>Deductible:</strong> {card.deductible_amount} BHD
                        </p>
                        <p className="mb-1">
                          <strong>Co-Patient:</strong> {coPatient}%
                        </p>
                        <p className="mb-1">
                          <strong>Co-Insurance:</strong> {coInsurance}%
                        </p>
                        <p className="mb-0">
                          <strong>Scan Copy:</strong>{" "}
                          {card.scanned_copy ? (
                            <a href={`${baseurImage}${card.scanned_copy}`} target="_blank" rel="noopener noreferrer">
                              <i className="bi bi-paperclip"></i> View
                            </a>
                          ) : (
                            <i className="bi bi-paperclip text-muted"></i>
                          )}
                        </p>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      </div>
      
      {/* Add Insurance Card Modal */}
      <AddInsuranceCard
        isOpen={showAddCardModal}
        onClose={() => setShowAddCardModal(false)}
        patientId={patientId}
        onSuccess={handleCardAdded}
      />

      {/* New Claims Modal */}
      {showNewClaimModal && (
        <div className="modal fade show" style={{ display: "block", backgroundColor: "rgba(0,0,0,0.5)", zIndex: 1055 }}>
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Create New Insurance Claim</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowNewClaimModal(false)}
                  aria-label="Close"
                ></button>
              </div>
              <form onSubmit={submitNewClaim}>
                <div className="modal-body">
                  <div className="row g-3">
                    <div className="col-12">
                      <label className="form-label">Insurance Card</label>
                      {activeCardsLoading ? (
                        <div className="form-text">Loading cards...</div>
                      ) : (
                        <select
                          name="card_id"
                          className="form-select"
                          value={claimForm.card_id}
                          onChange={handleClaimFormChange}
                          required
                        >
                          <option value="">Select Insurance Card</option>
                          {activeClaimCards.map((card) => {
                            const company = insuranceCompanies.find(comp => comp.company_id == card.company_id);
                            const companyName = company ? company.company_name : (card.company_name || 'Unknown Company');
                            return (
                              <option key={card.card_id || card.id} value={card.card_id || card.id}>
                                {companyName} - {card.policy_number}
                              </option>
                            );
                          })}
                        </select>
                      )}
                     
                      {claimForm.card_id && (() => {
                        const c = (activeClaimCards.find(x => (x.card_id || x.id) == claimForm.card_id)
                          || insuranceCards.find(x => (x.card_id || x.id) == claimForm.card_id));
                        if (!c) return null;
                        const company = insuranceCompanies.find(comp => comp.company_id == c.company_id);
                        const companyName = company ? company.company_name : (c.company_name || 'Unknown Company');
                        const currentDate = new Date();
                        currentDate.setHours(0, 0, 0, 0);
                        const expiryDate = new Date(c.expiry_date);
                        expiryDate.setHours(0, 0, 0, 0);
                        const isExpired = expiryDate < currentDate;
                        const coInsurance = (overrideCoInsPercent !== "" && overrideCoInsPercent !== null && overrideCoInsPercent !== undefined)
                          ? Math.max(0, Math.min(100, parseFloat(overrideCoInsPercent) || 0))
                          : (parseFloat(c.co_insurance_percent) || 0);
                        const coPatient = Math.max(0, 100 - coInsurance);
                        return (
                          <div className="card bg-light mt-2">
                            <div className="card-body py-2">
                              <div className="row g-2 align-items-center">
                                <div className="col-md-4">
                                  <div className="small text-muted">Company</div>
                                  <div className="fw-semibold">{companyName}</div>
                                </div>
                                <div className="col-md-4">
                                  <div className="small text-muted">Policy #</div>
                                  <div className="fw-semibold">{c.policy_number}</div>
                                </div>
                                <div className="col-md-4 text-md-end">
                                  <span className={`badge ${isExpired ? 'bg-danger' : 'bg-success'}`}>{isExpired ? 'Expired' : 'Active'}</span>
                                </div>
                                <div className="col-md-3">
                                  <div className="small text-muted">Issue</div>
                                  <div>{formatDateOnly(c.issue_date)}</div>
                                </div>
                                <div className="col-md-3">
                                  <div className="small text-muted">Expiry</div>
                                  <div>{formatDateOnly(c.expiry_date)}</div>
                                </div>
                                <div className="col-md-3">
                                  <div className="small text-muted">Deductible</div>
                                  <div>{Number(c.deductible_amount || 0).toFixed(2)} BHD</div>
                                </div>
                                <div className="col-md-3">
                                  <div className="small text-muted">Co-Ins / Co-Pat</div>
                                  <div className="d-flex align-items-center gap-2">
                                    <input
                                      type="number"
                                      className="form-control form-control-sm"
                                      value={overrideCoInsPercent === "" ? (c.co_insurance_percent ?? 0) : overrideCoInsPercent}
                                      onChange={(e) => {
                                        const val = e.target.value;
                                        if (val === "") { setOverrideCoInsPercent(""); return; }
                                        const num = Math.max(0, Math.min(100, Number(val)));
                                        setOverrideCoInsPercent(num);
                                      }}
                                      min="0"
                                      max="100"
                                      step="0.01"
                                      style={{ width: '90px' }}
                                    />
                                    <span>% / {coPatient}%</span>
                                  </div>
                                </div>
                              </div>
                            </div>
                          </div>
                        );
                      })()}
                    </div>
                    
                    <div className="col-12">
                      <label className="form-label">Invoice</label>
                      <select
                        name="invoice_id"
                        className="form-select"
                        value={claimForm.invoice_id}
                        onChange={handleClaimFormChange}
                        required
                      >
                        <option value="">Select Invoice</option>
                        {invoices.map((invoice) => (
                          <option key={invoice.id} value={invoice.id}>
                            {invoice.invoice_no || invoice.invoiceNo || invoice.id} - {Number(invoice.total_amount || invoice.amount || 0).toFixed(2)} BHD
                          </option>
                        ))}
                      </select>
                    </div>

                    <div className="col-12">
                      <div className="form-check">
                        <input
                          type="checkbox"
                          name="is_deductible_applied"
                          className="form-check-input"
                          checked={claimForm.is_deductible_applied}
                          onChange={handleClaimFormChange}
                        />
                        <label className="form-check-label">
                          Apply Deductible
                        </label>
                      </div>
                    </div>

                    
                    {claimForm.card_id && claimForm.invoice_id && (
                      <div className="col-12">
                        <div className="card bg-light p-3">
                          <h6>Claim Calculation</h6>
                          <div className="row">
                            <div className="col-md-6">
                              <p className="mb-1"><strong>Invoice Amount:</strong> {claimCalculations.invoiceAmount.toFixed(2)} BHD</p>
                              <p className="mb-1"><strong>Deductible Amount:</strong> {claimCalculations.deductibleAmount.toFixed(2)} BHD</p>
                              <p className="mb-1"><strong>After Deductible:</strong> {claimCalculations.afterDeductible.toFixed(2)} BHD</p>
                            </div>
                            <div className="col-md-6">
                              <p className="mb-1"><strong>Co-Insurance:</strong> {claimCalculations.coInsurancePercent}%</p>
                              <p className="mb-1 text-success"><strong>Claim Amount:</strong> {claimCalculations.claimAmount.toFixed(2)} BHD</p>
                              <p className="mb-1 text-warning"><strong>Patient Amount:</strong> {claimCalculations.patientAmount.toFixed(2)} BHD</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}

                    {/* <div className="col-12">
                      <label className="form-label">Status</label>
                      <select
                        name="status"
                        className="form-select"
                        value={claimForm.status}
                        onChange={handleClaimFormChange}
                        required
                      >
                        <option value="Pending">Pending</option>
                        <option value="Accepted">Accepted</option>
                      </select>
                    </div> */}
                  </div>
                </div>
                <div className="modal-footer">
                  <button
                    type="button"
                    className="borderBtn"
                    onClick={() => setShowNewClaimModal(false)}
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit" 
                    className="bgBtn"
                    disabled={loading}
                  >
                    {loading ? "Creating..." : "Create Claim"}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {showEditModal && (
        <div className="modal fade show" style={{ display: "block", backgroundColor: "rgba(0,0,0,0.5)", zIndex: 1055 }}>
          <div className="modal-dialog modal-dialog-centered">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Edit Insurance Card</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowEditModal(false)}
                  aria-label="Close"
                ></button>
              </div>
              <form onSubmit={submitEdit}>
                <div className="modal-body">
                  <div className="row g-3">
                    <div className="col-12 col-md-6">
                      <label className="form-label">Policy Number</label>
                      <input
                        type="text"
                        name="policy_number"
                        className="form-control"
                        value={editForm.policy_number}
                        onChange={handleEditChange}
                        placeholder="Enter policy number"
                        required
                      />
                    </div>
                    <div className="col-12 col-md-6">
                      <label className="form-label">Insurance Company</label>
                      <select
                        name="company_id"
                        className="form-select"
                        value={editForm.company_id}
                        onChange={handleEditChange}
                        required
                      >
                        <option value="">Select Insurance Company</option>
                        {insuranceCompanies.map((company) => (
                          <option key={company.company_id} value={company.company_id}>
                            {company.company_name}
                          </option>
                        ))}
                      </select>
                    </div>
                    <div className="col-12 col-md-6">
                      <label className="form-label">Issue Date</label>
                      <input
                        type="date"
                        name="issue_date"
                        className="form-control"
                        value={editForm.issue_date}
                        onChange={handleEditChange}
                        required
                      />
                    </div>
                    <div className="col-12 col-md-6">
                      <label className="form-label">Expiry Date</label>
                      <input
                        type="date"
                        name="expiry_date"
                        className="form-control"
                        value={editForm.expiry_date}
                        onChange={handleEditChange}
                        required
                      />
                    </div>
                    <div className="col-12 col-md-6">
                      <label className="form-label">Co-Insurance (%)</label>
                      <input
                        type="number"
                        name="co_insurance_percent"
                        className="form-control"
                        value={editForm.co_insurance_percent}
                        onChange={handleEditChange}
                        min="0"
                        max="100"
                        step="0.01"
                        placeholder="e.g., 30"
                        required
                      />
                    </div>
                    <div className="col-12 col-md-6">
                      <label className="form-label">Deductible Amount (BHD)</label>
                      <input
                        type="number"
                        name="deductible_amount"
                        className="form-control"
                        value={editForm.deductible_amount}
                        onChange={handleEditChange}
                        min="0"
                        step="0.01"
                        placeholder="e.g., 300"
                        required
                      />
                    </div>
                    <div className="col-12">
                      <label className="form-label">Scanned Copy</label>
                      <input
                        type="file"
                        name="scanned_copy"
                        className="form-control"
                        onChange={handleEditChange}
                        accept="image/*,.pdf"
                      />
                      <div className="form-text">
                        Upload a new scanned copy (optional). Leave empty to keep current file.
                      </div>
                    </div>
                  </div>
                </div>
                <div className="modal-footer">
                  <button
                    type="button"
                    className="borderBtn"
                    onClick={() => setShowEditModal(false)}
                  >
                    Cancel
                  </button>
                  <button type="submit" className="bgBtn">
                    Save Changes
                  </button>
                </div>
              </form>
            </div>
          </div>
          {/* Backdrop click disabled to avoid accidental modal close while editing */}
        </div>
      )}

      {/* Hidden (off-screen) PDF Target: must be rendered (not display:none) */}
      <div ref={targetRef} style={{ position: 'absolute', left: '-9999px', top: 0, width: '1000px', background: '#fff' }}>
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
          <div style={{ textAlign: 'center', marginBottom: '20px' }}>
            <h2 style={{ margin: 0 }}>Insurance Claims (Patient wise)</h2>
            <div style={{ color: '#7f8c8d', fontSize: '12px' }}>Generated on: {new Date().toLocaleDateString('en-GB')}</div>
          </div>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px' }}>
            <thead>
              <tr>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>#</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Claim No</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Invoice No</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Invoice Total</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Deductible</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Co-Ins %</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Insurance Amt</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Patient Amt</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Status</th>
                <th style={{ border: '1px solid #ddd', padding: '8px', background: '#f4f6f8' }}>Created</th>
              </tr>
            </thead>
            <tbody>
              {claims.map((c, idx) => (
                <tr key={c.claim_id || idx}>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{idx + 1}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{c.claim_number}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{c.invoice_no || c.invoiceNumber || c.invoice_id}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{Number(c.invoice_total || 0).toFixed(2)} BHD</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{c.is_deductible_applied ? 'Yes' : 'No'}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{Number(c.co_insurance_percent || 0)}%</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{Number(c.insurance_amount || 0).toFixed(2)} BHD</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{Number(c.patient_amount || 0).toFixed(2)} BHD</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{c.status}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{formatDateOnly(c.created_at)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div style={{ marginTop: '10px', textAlign: 'right', fontSize: '12px' }}>
            <strong>Total Claims: {claims?.length || 0}</strong>
          </div>
        </div>
      </div>
    </div>
  );
}









