import React, { useEffect, useState } from "react";
import axios from "axios";
import { baseurl } from "../../Baseurl";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";
import { Autocomplete, TextField } from "@mui/material";

export default function AddRxList() {
  const navigate = useNavigate();

  const [submitted, setSubmitted] = useState(false);
  const [errors, setErrors] = useState({});

  const [allergies,setAllergies] = useState([]);
  const [loading,setLoading] = useState(true);
  const [apiError, setApiError] = useState(false);
  const [selectedWarnings, setSelectedWarnings] = useState([]);

  const [formData, setFormData] = useState({
    medicine_name: "",
    strength: "",
    unit: "",
    pharmaceutical_form: "",
    frequency: "",
    duration: "",
    notes: "",
    route: "",
    product_type: "",
    active_substances: "",
    packet_size: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const validate = () => {
    const requiredFields = [
      "medicine_name",
      "strength",
      "unit",
      "pharmaceutical_form",
      "frequency",
      "duration",
      "notes",
      "route",
      "product_type",
      "active_substances",
      "packet_size",
    ];

    const newErrors = {};
    requiredFields.forEach((field) => {
      if (!formData[field] || formData[field].trim() === "") {
        newErrors[field] = `${field.replace(/_/g, " ")} is required`;
      }
    });

    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validate();

    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      setSubmitted(false);
      return;
    }

    try {
      const payload = {
        ...formData,
        // Send only IDs for selected allergies as per API contract
        allergies: selectedWarnings
          .map((opt) => opt?.id ?? opt?.allergyId ?? opt?.value)
          .filter((v) => v !== undefined && v !== null),
      };

      console.log("Submitting Rx data:", payload);
      const response = await axios.post(`${baseurl}addRxMedicine`, payload);
      if (response.data.success) {
        setSubmitted(true);
        Swal.fire("Success", "RX Item added successfully!", "success");
        navigate("/Admin/Pharmacy"); 
      } else {
        Swal.fire("Error", response.data.message || "Something went wrong", "error");
      }
    } catch (error) {
      console.error(error);
      if (error.response) {
        console.log(error.response.data);
      }
      Swal.fire("Error", "Server error while adding RX item", "error");
    }
  };


 useEffect(()=>{
  console.log("Fetching allergies from", `${baseurl}getAllAllergies`);

  setLoading(true);
  setApiError(false);

  axios.get(`${baseurl}getAllAllergies`)
  .then(res =>{
    console.log("Allergies api response:",res.data);
    if(res.data.success && Array.isArray(res.data.data)){
       setAllergies(res.data.data);
    }else{
      setApiError(true);
    }
    setLoading(false);

   
  })


 },[]);

  
  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="col-12">
          <div className="card table-card">
            <div className="tableHeader">
              <h5 style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span
                  style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                  onClick={() => navigate(-1)}
                  title="Back"
                >
                  &larr;
                </span>
                Add Rx Medicine
              </h5>
            </div>

            {submitted && (
              <div className="alert alert-success">
                RX item added successfully!
              </div>
            )}

            <form
              onSubmit={handleSubmit}
              encType="multipart/form-data"
              className="row g-3 px-3 py-2 mb-3"
            >
              {[
                { label: "Medicine Name", name: "medicine_name" },
                { label: "Strength", name: "strength" },
                { label: "Unit", name: "unit" },
                { label: "Pharmaceutical Form", name: "pharmaceutical_form" },
                { label: "Frequency", name: "frequency" },
                { label: "Duration", name: "duration" },
                { label: "Notes", name: "notes" },
                { label: "Route", name: "route" },
                { label: "Product Type", name: "product_type" },
                { label: "Active Substances", name: "active_substances" },
                { label: "Pack Size", name: "packet_size" },
              ].map((field) => (
                <div className="col-md-6" key={field.name}>
                  <label className="form-label">{field.label}</label>
                  <input
                    type="text"
                    name={field.name}
                    value={formData[field.name]}
                    onChange={handleChange}
                    className="form-control"
                  />
                  {errors && errors[field.name] && (
                    <p className="text-danger">{errors[field.name]}</p>
                  )}
                </div>
              ))}

              <div className="col-md-12">
                <label className="form-label">Warnings</label>
                <Autocomplete
                  multiple
                  id="warnings-autocomplete"
                  options={allergies}
                  disablePortal
                  getOptionLabel={(option) => {
                    // Support multiple possible field names from API
                    return (
                      option?.warningName ||
                      option?.allergyName ||
                      option?.name ||
                      option?.label ||
                      ""
                    );
                  }}
                  isOptionEqualToValue={(option, value) => {
                    const optionId = option?.id ?? option?.allergyId ?? option?.value;
                    const valueId = value?.id ?? value?.allergyId ?? value?.value;
                    return optionId === valueId;
                  }}
                  value={selectedWarnings}
                  onChange={(_, newValue) => setSelectedWarnings(newValue || [])}
                  loading={loading}
                  disabled={loading || apiError}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      label="Select Allergies"
                      placeholder="Search and select Allergies..."
                      error={!!errors?.allergies}
                      helperText={errors?.allergies}
                    />
                  )}
                />
                {apiError && (
                  <p className="text-danger">Failed to load allergies list.</p>
                )}
              </div>

              <div className="col-12 mb-3 text-center">
                <button type="submit" className="bgBtn">
                  Add RX Item
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}
