import React, { useCallback, useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { baseurl } from "../../Baseurl";
import Swal from "sweetalert2";

const FinanceSetting = () => {
  const navigate = useNavigate();

  // Discount Limit modal state
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [discountValue, setDiscountValue] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const saveTimerRef = useRef(null);

  // VAT state
  const [vatValue, setVatValue] = useState(0);
  const vatSaveTimerRef = useRef(null);

  // Currency state
  const [currency, setCurrency] = useState("");
  const currencySaveTimerRef = useRef(null);

  // Handle payment method button click - navigate to new page
  const handlePaymentMethodClick = () => {
    navigate("/Admin/PaymentMethod");
  };

  // Open Discount Limit modal and fetch current value
  const handleOpenDiscountModal = () => {
    setIsDiscountModalOpen(true);
  };

  // Fetch current discount value when modal opens
  useEffect(() => {
    if (!isDiscountModalOpen) return;

    const controller = new AbortController();
    const fetchDiscount = async () => {
      try {
        const res = await fetch(`${baseurl}getAllDiscount`, {
          signal: controller.signal,
        });
        if (!res.ok) throw new Error("Failed to load discount");
        const data = await res.json();
        const value = Array.isArray(data?.data) && data.data.length > 0
          ? Number(data.data[0].discount_value)
          : 0;
        setDiscountValue(Number.isFinite(value) ? value : 0);
      } catch (err) {
        // Fallback to 0 on error
        setDiscountValue(0);
        // Optionally log
        // console.error(err);
      }
    };
    fetchDiscount();
    return () => controller.abort();
  }, [isDiscountModalOpen]);

  // Debounced save when slider changes
  const persistDiscountValue = useCallback(async (value) => {
    setIsSaving(true);
    const numericValue = Number(value);
    const endpoint = `${baseurl}updateDiscount/1`;

    const tryPostJson = async () => {
      const res = await fetch(endpoint, {
        method: "POST",
        mode: "cors",
        headers: {
          "Accept": "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ discount_value: numericValue }),
      });
      if (!res.ok) throw new Error("POST JSON failed");
      return res;
    };

    const tryPostForm = async () => {
      const params = new URLSearchParams();
      params.append("discount_value", String(numericValue));
      const res = await fetch(endpoint, {
        method: "POST",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/x-www-form-urlencoded" },
        body: params.toString(),
      });
      if (!res.ok) throw new Error("POST form failed");
      return res;
    };

    const tryPutJson = async () => {
      const res = await fetch(endpoint, {
        method: "PUT",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ discount_value: numericValue }),
      });
      if (!res.ok) throw new Error("PUT JSON failed");
      return res;
    };

    try {
      await tryPostJson().catch(async () => await tryPostForm()).catch(async () => await tryPutJson());
    } catch (e) {
      // Optionally surface an error UI here
    } finally {
      setIsSaving(false);
    }
  }, []);

  const handleSliderChange = (e) => {
    const value = Number(e.target.value);
    setDiscountValue(value);
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(() => {
      persistDiscountValue(value);
    }, 400);
  };

  const closeDiscountModal = () => {
    setIsDiscountModalOpen(false);
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
  };

  // Fetch VAT value on mount from provided endpoint
  useEffect(() => {
    const controller = new AbortController();
    const fetchVat = async () => {
      try {
        const res = await fetch(`${baseurl}getAllVat`, { signal: controller.signal });
        if (!res.ok) throw new Error("Failed to fetch VAT");
        const data = await res.json();
        const value = Array.isArray(data?.data) && data.data.length > 0
          ? Number(data.data[0].vat_value)
          : Number(data?.vat_value ?? 0);
        setVatValue(Number.isFinite(value) ? value : 0);
      } catch (e) {
        setVatValue(0);
      }
    };
    fetchVat();
    return () => controller.abort();
  }, []);

  // Fetch Currency on mount
  useEffect(() => {
    const controller = new AbortController();
    const fetchCurrency = async () => {
      try {
        const res = await fetch(`${baseurl}getCurrency`, { signal: controller.signal });
        if (!res.ok) throw new Error("Failed to fetch currency");
        const data = await res.json();
        const val = Array.isArray(data?.data) && data.data.length > 0
          ? String(data.data[0].currency || "")
          : String(data?.currency || "");
        setCurrency(val);
      } catch (e) {
        setCurrency("");
      }
    };
    fetchCurrency();
    return () => controller.abort();
  }, []);

  // Persist VAT value to provided endpoint
  const persistVatValue = useCallback(async (value) => {
    const numericValue = Number(value);
    const endpoint = `${baseurl}updateVat/1`;

    const tryPostJson = async () => {
      const res = await fetch(endpoint, {
        method: "POST",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ vat_value: numericValue }),
      });
      if (!res.ok) throw new Error("VAT POST JSON failed");
      return res;
    };

    const tryPostForm = async () => {
      const params = new URLSearchParams();
      params.append("vat_value", String(numericValue));
      const res = await fetch(endpoint, {
        method: "POST",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/x-www-form-urlencoded" },
        body: params.toString(),
      });
      if (!res.ok) throw new Error("VAT POST form failed");
      return res;
    };

    const tryPutJson = async () => {
      const res = await fetch(endpoint, {
        method: "PUT",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ vat_value: numericValue }),
      });
      if (!res.ok) throw new Error("VAT PUT JSON failed");
      return res;
    };

    try {
      await tryPostJson().catch(async () => await tryPostForm()).catch(async () => await tryPutJson());
      return true;
    } catch (e) {
      throw e;
    }
  }, []);

  const handleVatSaveClick = async () => {
    try {
      await persistVatValue(vatValue);
      Swal.fire("Success", "VAT updated successfully", "success");
    } catch (_) {
      Swal.fire("Error", "Failed to update VAT", "error");
    }
  };

  // Persist Currency to provided endpoint
  const persistCurrencyValue = useCallback(async (value) => {
    const endpoint = `${baseurl}updateCurrency/1`;
    const body = { currency: String(value) };

    const tryPutJson = async () => {
      const res = await fetch(endpoint, {
        method: "PUT",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!res.ok) throw new Error("Currency PUT JSON failed");
      return res;
    };

    const tryPostForm = async () => {
      const params = new URLSearchParams();
      params.append("currency", String(value));
      const res = await fetch(endpoint, {
        method: "PUT",
        mode: "cors",
        headers: { "Accept": "application/json", "Content-Type": "application/x-www-form-urlencoded" },
        body: params.toString(),
      });
      if (!res.ok) throw new Error("Currency PUT form failed");
      return res;
    };

    try {
      await tryPutJson().catch(async () => await tryPostForm());
    } catch (_) {
      // swallow errors, UI keeps last typed value
    }
  }, []);



  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="row">
          <div className="col-md-12 financePage">
            <div className="card mb-3" style={{ position: "relative" }}>
              <div className="personaimg text-center" />
              <div className="col-12 searchParent">
                <h5 className="card-title" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span
                    style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                    onClick={() => navigate(-1)}
                    title="Back"
                  >
                    &larr;
                  </span>
                  Finance
                </h5>
                <form className="row g-3 p20">
                  {/* VAT Status */}
                  {/* <div className="col-12">
                    <label className="form-label">VAT</label>
                    <br />
                    <div className="form-check form-check-inline">
                      <input
                        className="form-check-input"
                        type="radio"
                        name="vatStatus"
                         
                        id="vatActive"
                      />
                      <label className="form-check-label" htmlFor="vatActive">
                        Active
                      </label>
                    </div>
                    <div className="form-check form-check-inline">
                      <input
                        className="form-check-input"
                        type="radio"
                        name="vatStatus"
                        value="disabled"
                        id="vatDisabled"
                      />
                      <label className="form-check-label" htmlFor="vatDisabled">
                        Disabled
                      </label>
                    </div>
                  </div> */}

                  {/* VAT Value */}
                  <div className="col-12">
                    <label className="form-label">VAT Value %</label>
                    <div className="d-flex" style={{ gap: 8 }}>
                      <input
                        type="number"
                        className="form-control"
                        name="vatValue"
                        placeholder="Enter VAT %"
                        value={vatValue}
                        onChange={(e) => {
                          const next = Math.max(0, Math.min(100, Number(e.target.value)));
                          setVatValue(next);
                          if (vatSaveTimerRef.current) clearTimeout(vatSaveTimerRef.current);
                          vatSaveTimerRef.current = setTimeout(() => {
                            persistVatValue(next);
                          }, 400);
                        }}
                        style={{ flex: 1 }}
                      />
                      <button
                        type="button"
                        className="btn btn-primary"
                        onClick={handleVatSaveClick}
                        style={{ height: 38, padding: "0 16px", lineHeight: 1.2 }}
                      >
                        Update
                      </button>
                    </div>
                  </div>

                  {/* Currency moved to dedicated page */}

                  {/* Functional Buttons */}
                  <div className="col-6">
                    <button
                      type="button"
                      className="borderBtn"
                      onClick={handlePaymentMethodClick}
                    >
                      Payment Method
                    </button>
                  </div>
                  <div className="col-6">
                    <button
                      type="button"
                      className="borderBtn"
                    >
                      Receipt Template
                    </button>
                  </div>
                  <div className="col-6">
                    <button
                      type="button"
                      className="borderBtn"
                    >
                      Discount Type
                    </button>
                  </div>
                  <div className="col-6">
                    <button
                      type="button"
                      className="borderBtn"
                      onClick={() => navigate("/Admin/Currency")}
                    >
                      Currency
                    </button>
                  </div>
                  <div className="col-6">
                    <button
                      type="button"
                      className="borderBtn"
                      onClick={handleOpenDiscountModal}
                    >
                      Discount Limit
                    </button>
                  </div>
                  <div className="col-6">
                    <button
                      type="button"
                      className="borderBtn"
                    >
                      Service List
                    </button>
                  </div>
                  <div className="col-12">
                    <button
                      type="button"
                      className="borderBtn"
                    >
                      Invoice Template
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
        {isDiscountModalOpen && (
          <div className="modal-backdrop-custom" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.35)", zIndex: 1050 }} onClick={closeDiscountModal}>
            <div
              className="modal-card-custom"
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                transform: "translate(-50%, -50%)",
                width: "min(520px, 92vw)",
                background: "#fff",
                borderRadius: 8,
                boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
              }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="p20" style={{ padding: 20 }}>
                <div className="d-flex justify-content-between align-items-center">
                  <h6 className="mb-0">Discount Limit</h6>
                  <button type="button" className="btn btn-sm btn-light" onClick={closeDiscountModal}>✕</button>
                </div>
                <div style={{ marginTop: 20 }}>
                  <div className="d-flex align-items-center justify-content-between">
                    <label className="form-label mb-0">Value</label>
                    <strong>{discountValue}%</strong>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    step="1"
                    value={discountValue}
                    onChange={handleSliderChange}
                    className="form-range"
                    style={{ width: "100%" }}
                  />
                  <div className="d-flex justify-content-between" style={{ fontSize: 12, color: "#6c757d" }}>
                    <span>0%</span>
                    <span>100%</span>
                  </div>
                  {isSaving && (
                    <div style={{ fontSize: 12, color: "#0d6efd", marginTop: 8 }}>
                      Saving...
                    </div>
                  )}
                </div>
                <div className="text-end" style={{ marginTop: 16 }}>
                  <button type="button" className="btn btn-primary" onClick={closeDiscountModal}>Done</button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FinanceSetting;
