import React, { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { baseurl } from '../../Baseurl'

const CategoryRow = ({ category, onEdit, onDelete, onViewTemplates }) => {
  return (
    <tr>
      <td>{category.id}</td>
      <td>{category.category_name}</td>
      <td className="text-end">
        <button
          className="btn btn-sm  me-2"
          title="View templates"
          onClick={() => onViewTemplates(category)}
          aria-label="View"
        >
          <i className="ti ti-eye f-20"></i>
        </button>
        <button
          className="btn btn-sm  me-2"
          title="Edit category"
          onClick={() => onEdit(category)}
          aria-label="Edit"
        >
          <i className="ti ti-edit f-20"></i>
        </button>
        <button
          className="btn btn-sm "
          title="Delete category"
          onClick={() => onDelete(category.id)}
          aria-label="Delete"
        >
          <i className="ti ti-trash f-20"></i>
        </button>
      </td>
    </tr>
  )
}


const getTemplatesForCategory = (category) => {
  const name = (category?.category_name || '').toLowerCase()
  const groups = {
    'lab': [
      // { key: 'create_lab', title: 'Create Lab' },
      { key: 'new_request', title: 'New Request' },
      // { key: 'result_ready', title: 'Result Ready' }
    ],
    'invoice': [
      { key: 'invoice_created', title: 'Invoice Created' },
      // { key: 'invoice_paid', title: 'Invoice Paid' },
      // { key: 'payment_due', title: 'Payment Due Reminder' }
    ],
    'receipt': [
      { key: 'receipt_issued', title: 'Receipt Issued' }
    ],
    'appointment booking': [
      { key: 'appointment_created', title: 'Appointment Created' },
      { key: 'appointment_reminder', title: 'Appointment Reminder' },
      { key: 'appointment_cancelled', title: 'Appointment Cancelled' }
    ]
  }
  return groups[name] || [{ key: 'generic', title: 'Generic Notification' }]
}

