const TemplateListView = ({ category, onBack }) => {
  const [templates, setTemplates] = useState([]) // [{ key, title, id?, subject?, content? }]
  const [loading, setLoading] = useState(false)

  const editorsRef = useRef({}) // key -> CKEditor instance
  const [subjects, setSubjects] = useState({}) // key -> subject
  const [templateIds, setTemplateIds] = useState({}) // key -> email_template_id

  // Fetch templates from server by category id
  useEffect(() => {
    const fetchTemplates = async () => {
      if (!category?.id) return
      setLoading(true)
      try {
        const res = await fetch(`${baseurl}getEmailTemplatesByCategory/${category.id}`)
        const data = await res.json().catch(() => null)
        const list = Array.isArray(data)
          ? data
          : Array.isArray(data?.data)
            ? data.data
            : Array.isArray(data?.templates)
              ? data.templates
              : []
        const normalized = list.map((it, idx) => ({
          key: String(it.key || it.id || idx),
          title: it.template_name || it.title || `Template ${idx + 1}`,
          id: it.id,
          subject: it.subject || '',
          content: it.content || it.body || ''
        }))
        setTemplates(normalized)
      } catch (e) {
        console.error(e)
        setTemplates([])
      } finally {
        setLoading(false)
      }
    }
    fetchTemplates()
  }, [category])

  const storageKeyFor = (key) => `template_${category?.id}_${key}`


  useEffect(() => {
    const nextSubjects = {}
    const nextIds = {}
    templates.forEach(t => {
      // Prefill from server first
      if (t.subject) nextSubjects[t.key] = t.subject
      if (t.id) nextIds[t.key] = t.id
      // Then load any local drafts
      const saved = window.localStorage.getItem(storageKeyFor(t.key))
      if (saved) {
        try {
          const parsed = JSON.parse(saved)
          nextSubjects[t.key] = parsed.subject ?? nextSubjects[t.key] ?? ''
          if (parsed.templateId) nextIds[t.key] = parsed.templateId
        } catch { }
      }
    })
    setSubjects(nextSubjects)
    setTemplateIds(nextIds)
  }, [category, templates])

  // Ensure CKEditor script is present, then create editors for each template
  useEffect(() => {
    const createEditors = () => {
      if (!window.ClassicEditor) return
      const createFor = async (t) => {
        const el = document.getElementById(`templateEditorInline_${t.key}`)
        if (!el || editorsRef.current[t.key]) return
        try {
          const editor = await window.ClassicEditor.create(el)
          editorsRef.current[t.key] = editor
          // Load body: prefer server content, then local storage draft
          if (t.content) {
            editor.setData(t.content)
          }
          const saved = window.localStorage.getItem(storageKeyFor(t.key))
          if (saved) {
            try {
              const parsed = JSON.parse(saved)
              if (parsed.body) editor.setData(parsed.body)
            } catch { }
          }
        } catch { }
      }
      templates.forEach(createFor)
    }
    const existingScript = document.getElementById('ckeditor5-cdn')
    if (!existingScript) {
      const script = document.createElement('script')
      script.id = 'ckeditor5-cdn'
      script.src = 'https://cdn.ckeditor.com/ckeditor5/41.4.2/classic/ckeditor.js'
      script.onload = createEditors
      document.body.appendChild(script)
    } else {
      createEditors()
    }

    return () => {
      Object.values(editorsRef.current).forEach(ed => {
        if (ed && ed.destroy) ed.destroy().catch(() => { })
      })
      editorsRef.current = {}
    }
  }, [templates])

  const handleSubjectChange = (key, value) => {
    setSubjects(prev => ({ ...prev, [key]: value }))
  }

  const handleSave = async (t) => {
    const editor = editorsRef.current[t.key]
    const body = editor ? editor.getData() : ''
    const subjectVal = subjects[t.key] || ''
    const templateId = templateIds[t.key]
    const payload = { subject: subjectVal, body }

    // Always persist locally as a draft
    window.localStorage.setItem(
      storageKeyFor(t.key),
      JSON.stringify({ ...payload, templateId })
    )

    // If we have a template id, call API
    if (templateId) {
      try {
        const res = await fetch(`${baseurl}updateEmailTemplate/${templateId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ subject: subjectVal, content: body })
        })
        const data = await res.json().catch(() => null)
        if (res.ok) {
          window.alert('Template saved successfully.')
        } else {
          window.alert(data?.message || 'Failed to save template on server.')
        }
      } catch (e) {
        console.error(e)
        window.alert('Network error while saving template.')
      }
    } else {
      window.alert('Saved locally. Set Template ID to save on server.')
    }
  }

  const handleIdChange = (key, value) => {
    setTemplateIds(prev => ({ ...prev, [key]: value }))
  }

  return (
    <div className="card">
      <div className="card-header d-flex justify-content-between align-items-center">
        <div className="d-flex align-items-center">
          <button className="btn btn-sm btn-outline-secondary me-2" onClick={onBack} title="Back">
            <i className="ti ti-arrow-left"></i>
          </button>
          <h5 className="mb-0">Templates: {category?.category_name}</h5>
        </div>
      </div>
      <div className="card-body">
        {loading && <div className="text-muted">Loading templates...</div>}
        {templates.map(t => (
          <div key={t.key} className="mb-4">
            <div className="card">
              <div className="card-header d-flex justify-content-between align-items-center">
                <h6 className="mb-0">{t.title}</h6>
                <div className="d-flex align-items-center">
                  {/* <input
                    className="form-control form-control-sm me-2"
                    style={{ width: 140 }}
                    placeholder="Template ID"
                    value={templateIds[t.key] || ''}
                    onChange={e => handleIdChange(t.key, e.target.value)}
                    disabled={!!t.id}
                  /> */}
                  <button className="btn btn-sm btn-primary" onClick={() => handleSave(t)}>Save</button>
                </div>
              </div>
              <div className="card-body">
                <div className="mb-3">
                  <label className="form-label">Subject</label>
                  <input
                    className="form-control"
                    value={subjects[t.key] || ''}
                    onChange={e => handleSubjectChange(t.key, e.target.value)}
                    placeholder="Subject"
                  />
                </div>
                <textarea id={`templateEditorInline_${t.key}`}></textarea>
                <div className="mt-2 small text-muted">
                  Use placeholders like {'{patientName}'}, {'{date}'}, {'{appointmentId}'}. Replace server-side when sending.
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

const NotificationCenter = () => {
  const navigate = useNavigate()
  const [mode, setMode] = useState('BOTH')
  const [categories, setCategories] = useState([])
  const [loading, setLoading] = useState(false)
  const [newName, setNewName] = useState('')
  const [editItem, setEditItem] = useState(null)
  const [viewCategory, setViewCategory] = useState(null)
  const [showAddModal, setShowAddModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)

  const fetchCategories = async () => {
    setLoading(true)
    try {
      const res = await fetch(`${baseurl}getAllSmsCategories`)
      const data = await res.json()
      setCategories(Array.isArray(data?.categories) ? data.categories : [])
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { fetchCategories() }, [])

  const addCategory = async () => {
    if (!newName.trim()) return
    try {
      await fetch(`${baseurl}addSmsCategory`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ category_name: newName.trim() })
      })
      setNewName('')
      fetchCategories()
    } catch (e) { console.error(e) }
  }

  const updateCategory = async () => {
    if (!editItem || !editItem.category_name.trim()) return
    try {
      await fetch(`${baseurl}updateSmsCategory/${editItem.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ category_name: editItem.category_name.trim() })
      })
      setEditItem(null)
      setShowEditModal(false)
      fetchCategories()
    } catch (e) { console.error(e) }
  }

  const deleteCategory = async (id) => {
    if (!window.confirm('Delete this category?')) return
    try {
      await fetch(`${baseurl}deleteSmsCategory/${id}`, { method: 'DELETE' })
      fetchCategories()
    } catch (e) { console.error(e) }
  }

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="card">
          <div className="card-header d-flex justify-content-between align-items-center col-12 searchParent">
            <h5 className="mb-0" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span
                style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                onClick={() => navigate(-1)}
                title="Back"
              >
                &larr;
              </span>
              Notification Center
            </h5>
            <div className="tableHeaderBtn">
              <button className="bgBtn btn btn-primary" onClick={() => setShowAddModal(true)}>
                <i className="fas fa-plus me-2"></i> Add Category
              </button>
            </div>
          </div>
          <div className="card-body">
            {!viewCategory ? (
              <div className="table-responsive mt-4">
                <table className="table table-striped align-middle">
                  <thead>
                    <tr>
                      <th style={{ width: 80 }}>ID</th>
                      <th>Category</th>
                      <th className="text-end" style={{ width: 260 }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {loading ? (
                      <tr><td colSpan="3">Loading...</td></tr>
                    ) : categories.length === 0 ? (
                      <tr><td colSpan="3">No categories</td></tr>
                    ) : (
                      categories.map(cat => (
                        <CategoryRow
                          key={cat.id}
                          category={cat}
                          onEdit={(c) => { setEditItem(c); setShowEditModal(true) }}
                          onDelete={deleteCategory}
                          onViewTemplates={(c) => setViewCategory(c)}
                        />
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="mt-3">
                <TemplateListView
                  category={viewCategory}
                  onBack={() => setViewCategory(null)}
                />
              </div>
            )}
          </div>
        </div>
      </div>
      {showAddModal && (
        <div className="modal fade show" style={{ backgroundColor: 'rgba(81, 81, 81, 0.5)', display: 'block' }}>
          <div className="modal-dialog modal-md">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add Category</h5>
                <button type="button" className="btn-close" onClick={() => { setShowAddModal(false); setNewName('') }}></button>
              </div>
              <div className="modal-body">
                <label className="form-label">Category Name</label>
                <input className="form-control" value={newName} onChange={e => setNewName(e.target.value)} placeholder="e.g. Appointment Booking" />
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={() => { setShowAddModal(false); setNewName('') }}>Cancel</button>
                <button className="btn btn-primary" onClick={async () => { await addCategory(); setShowAddModal(false) }}>Add</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editItem && (
        <div className="modal fade show" style={{ backgroundColor: 'rgba(81, 81, 81, 0.5)', display: 'block' }}>
          <div className="modal-dialog modal-md">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Edit Category</h5>
                <button type="button" className="btn-close" onClick={() => { setShowEditModal(false); setEditItem(null) }}></button>
              </div>
              <div className="modal-body">
                <label className="form-label">Category Name</label>
                <input className="form-control" value={editItem.category_name} onChange={e => setEditItem({ ...editItem, category_name: e.target.value })} />
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={() => { setShowEditModal(false); setEditItem(null) }}>Cancel</button>
                <button className="btn btn-success" onClick={updateCategory}>Update</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default NotificationCenter
