import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { baseurImage } from "../Baseurl";
import { useSelector } from "react-redux";

export default function MyProfile() {
  const navigate = useNavigate();
  const user = useSelector((state) => state.user.user);

  const [avatarVersion, setAvatarVersion] = useState(Date.now());
  const [userData, setUserData] = useState({
    fullName: "",
    shortName: "",
    email: "",
    phoneNumber: "",
    prefix: "",
    dateOfBirth: "",
    licenseId: "",
    civilId: "",
    passport: "",
    gender: "",
    role: "",
    personalPhoto: "",
    country: "",
    state: "",
  });

  //Load Redux user into local state
  const loadUserData = () => {
    if (!user) return;
    setUserData({
      fullName: user.fullName || "",
      shortName: user.shortName || "",
      email: user.email || "",
      phoneNumber: user.phoneNumber || "",
      prefix: user.prefix || "",
      dateOfBirth: user.dateOfBirth
        ? new Date(user.dateOfBirth).toLocaleDateString()
        : "",
      licenseId: user.licenseId || "",
      civilId: user.civilId || "",
      passport: user.passport || "",
      gender: user.gender || "",
      role: user.role || "",
      personalPhoto: user.personalPhoto || "",
      country: user.country || "",
      state: user.state || "",
    });
    setAvatarVersion(Date.now()); // bust cache for image refresh
  };


  useEffect(() => {
    loadUserData();
  }, [user]);

 
  useEffect(() => {
    const handleProfileUpdated = () => {
      loadUserData();
      setAvatarVersion(Date.now());
    };
    window.addEventListener("profile-updated", handleProfileUpdated);
    return () => window.removeEventListener("profile-updated", handleProfileUpdated);
  }, []);

  
  useEffect(() => {
    const handleFocus = () => {
      loadUserData();
      setAvatarVersion(Date.now());
    };
    window.addEventListener("focus", handleFocus);
    return () => window.removeEventListener("focus", handleFocus);
  }, []);

  
 const getProfileImg = () => {
  const photo = userData?.personalPhoto;
  const bustKey = localStorage.getItem("profilePhotoBust") || avatarVersion;
  const bust = `?v=${bustKey}`;

  if (!photo) return "/assets/images/user/avatar-2.jpg";

  if (photo instanceof Blob) {
    const url = URL.createObjectURL(photo);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return url;
  }

  if (typeof photo === "string" && (photo.startsWith("http://") || photo.startsWith("https://"))) {
    return `${photo}${bust}`;
  }

  return `${baseurImage}${photo.replace(/^\/+/, "")}${bust}`;
};

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="row">
          <div className="col-lg-12" style={{ position: "relative" }}>
            {/* Profile Photo */}
            <div className="myProfileImg">
              <img src={getProfileImg()} alt="avatar" />
            </div>

            {/* Profile Info */}
            <div className="cardBorder table-card" style={{ marginTop: "85px" }}>
              <div className="tableHeader d-flex align-items-center justify-content-between">
                <h5 className="mb-0">
                  Profile Details{" "}
                  <i
                    type="button"
                    onClick={() => navigate("/Admin/EditProfile")}
                    className="ti ti-edit f-20"
                    style={{ color: "rgb(70, 128, 255)", cursor: "pointer" }}
                  ></i>
                </h5>
                <div className="d-flex gap-2">
                  <button
                    type="button"
                    className="bgBtn"
                    onClick={() => navigate("/Admin/Changepassword")}
                  >
                    Change Password
                  </button>
                </div>
              </div>

              {/* User Info Section */}
              <div className="p20">
                <div className="row">
                  <div className="col-md-6">
                    <label className="form-label">Full Name</label>
                    <input type="text" className="form-control" value={userData.fullName} disabled />
                  </div>

                  <div className="col-md-6">
                    <label className="form-label">Email Address</label>
                    <input type="email" className="form-control" value={userData.email} disabled />
                  </div>

                  <div className="col-md-6">
                    <label className="form-label">Phone Number</label>
                    <input type="text" className="form-control" value={userData.phoneNumber} disabled />
                  </div>

                  <div className="col-md-6">
                    <label className="form-label">Date of Birth</label>
                    <input type="text" className="form-control" value={userData.dateOfBirth} disabled />
                  </div>

                  <div className="col-md-6">
                    <label className="form-label">Gender</label>
                    <input type="text" className="form-control" value={userData.gender} disabled />
                  </div>

                  <div className="col-md-6">
                    <label className="form-label">Role</label>
                    <input type="text" className="form-control" value={userData.role} disabled />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
