import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { baseurl, baseurImage } from "../../Baseurl";

export default function ViewLab() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [labRequest, setLabRequest] = useState(null);
  const [attachments, setAttachments] = useState([]);

  useEffect(() => {
    // Pehla API call (LabRequest details)
    axios
      .get(`${baseurl}getLabRequestById/${id}`)
      .then((res) => {
        if (res.data.success) {
          setLabRequest(res.data.data);
        }
      })
      .catch((err) => console.error("Fetch lab request error:", err));

    // Dusra API call (Attachments)
    axios
      .get(`${baseurl}getLabRequestAttachmentsByLabRequestId/${id}`)
      .then((res) => {
        console.log("Attachments API Response:", res.data);
        if (res.data.success && res.data.data && res.data.data.length > 0) {
          console.log("Setting attachments from API:", res.data.data);
          setAttachments(res.data.data);
        } else {
          console.log("Attachments API returned empty or failed:", res.data);
          setAttachments([]);
        }
      })
      .catch((err) => {
        console.error("Fetch attachments error:", err);
        console.error("Error details:", err.response?.data);
        setAttachments([]);
      });
  }, [id]);

  const formatDate = (dateString) => {
    if (!dateString) return "";
    const date = new Date(dateString);
    return date.toLocaleDateString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  };

  if (!labRequest) return <div>Loading...</div>;

  // Show report status only when the lab is received and API provided status
  const hasReportStatus =
    (labRequest?.status === "Received" || attachments?.some((a) => a?.report_status)) &&
    attachments?.length > 0;

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="col-12">
          <div className="card table-card">
            <div className="tableHeader">
              <h5 style={{ display: "flex", alignItems: "center" }}>
                <i
                  onClick={() => navigate(-1)}
                  className="fa fa-arrow-left"
                ></i>
                Lab Request Details
              </h5>
            </div>
            <div className="card-body">
              <div className="row">
                {/* Render static fields except date fields */}
                {[
                  ["Patient Name", labRequest.patient_name],
                  ["Patient Civil ID", labRequest.patient_civil_id],
                  ["Doctor Name", labRequest.doctor_name],
                  ["Lab Name", labRequest.lab_name],
                  ["Title", labRequest.title],
                  ["Description", labRequest.description],
                  ["Status", labRequest.status],
                  ["Request Time", labRequest.request_time],
                  ["Days Since Request", labRequest.days_since_request],
                  ["Sent By", labRequest.sent_by],
                ].map(([label, value], idx) => (
                  <div className="col-md-6" key={idx}>
                    <label className="form-label">{label}</label>
                    <input
                      type="text"
                      className="form-control"
                      value={value ?? ""}
                      disabled
                    />
                  </div>
                ))}

                {/* Conditionally render date fields based on status */}
                <div className="col-md-12">
                  <label className="form-label">Request Date</label>
                  <input
                    type="text"
                    className="form-control"
                    value={formatDate(labRequest.request_date) ?? ""}
                    disabled
                  />
                </div>
                {(labRequest.status === "Pending" ||
                  labRequest.status === "Received") && (
                  <div className="col-md-6">
                    <label className="form-label">Sent Date</label>
                    <input
                      type="text"
                      className="form-control"
                      value={formatDate(labRequest.pending_at) ?? ""}
                      disabled
                    />
                  </div>
                )}
                {labRequest.status === "Received" && (
                  <div className="col-md-6">
                    <label className="form-label">Received Date</label>
                    <input
                      type="text"
                      className="form-control"
                      value={formatDate(labRequest.received_at) ?? ""}
                      disabled
                    />
                  </div>
                )}
                {/* Service Name and Category as a table if services exist */}
                {labRequest.services && labRequest.services.length > 0 && (
                  <div className="col-lg-6">
                    <label className="form-label">Services</label>
                    <div className="table-responsive noBorder">
                      <table className="table">
                        <thead>
                          <tr>
                            <th>Service Name</th>
                            <th>Category</th>
                            <th>Price</th>
                          </tr>
                        </thead>
                        <tbody>
                          {labRequest.services.map((service, idx) => (
                            <tr key={service.serviceId || idx}>
                              <td>{service.serviceName}</td>
                              <td>{service.category}</td>
                              <td>{service.price ? `${service.price} BHD` : "-"}</td>
                            </tr>
                          ))}
                        </tbody>
                        {labRequest.total_price && (
                          <tfoot>
                            <tr>
                              <th colSpan="2" style={{ textAlign: 'right' }}>Total Price:</th>
                              <th style={{ color: '#007bff' }}>{labRequest.total_price} BHD</th>
                            </tr>
                          </tfoot>
                        )}
                      </table>
                    </div>
                  </div>
                )}
             
              <div className="col-lg-6">
                <label className="form-label">
                  Attachments ({attachments.length})
                </label>
                {console.log("Current attachments state:", attachments)}
                {attachments.length > 0 ? (
                  <div className="table-responsive noBorder">
                    <table className="table">
                      <thead>
                        <tr>
                          <th>Attachment Name</th>
                          <th>File</th>
                          {hasReportStatus && <th>Status</th>}
                          <th>Uploaded At</th>
                        </tr>
                      </thead>
                      <tbody>
                        {attachments.map((attachment, index) => (
                          <tr key={attachment.attachment_id || index}>
                            <td>{attachment.attachment_name}</td>
                            <td>
                              {attachment.filename ? (
                                <a
                                  href={`${baseurImage}${attachment.filename}`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                >
                                  {attachment.filename}
                                </a>
                              ) : (
                                "No file"
                              )}
                              {console.log(
                                "File URL:",
                                `${baseurImage}${attachment.filename}`
                              )}
                            </td>
                            {hasReportStatus && (
                              <td>{attachment.report_status || "-"}</td>
                            )}
                            <td>{formatDate(attachment.uploaded_at)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="alert alert-info">
                    No attachments found for this lab request.
                  </div>
                )}
              </div>
               </div>
              {/* Attachments section */}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
