import { useNavigate } from "react-router-dom";
import axios from "axios";
import { useEffect, useState } from "react";
import Swal from "sweetalert2";
import Autocomplete from "@mui/material/Autocomplete";
import TextField from "@mui/material/TextField";
import Chip from "@mui/material/Chip";
import { baseurl, baseurImage } from "../../Baseurl"
import { fetchModuleMappings, hasSubModulePermission, isAdmin } from "../../utils/permissions";

export default function ManageLabs() {
  const navigate = useNavigate();
  const [labRequests, setLabRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedTab, setSelectedTab] = useState("Not Sent");
  const [labs, setLabs] = useState([]);
  const [labServices, setLabServices] = useState([]);
  const [refreshFlag, setRefreshFlag] = useState(0);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportLabId, setReportLabId] = useState(null);
  const [reportFile, setReportFile] = useState(null);
  const [reportName, setReportName] = useState("");
  const [reportStatus, setReportStatus] = useState("");
  const [showEditModal, setShowEditModal] = useState(false);
  const [editData, setEditData] = useState({
    request_id: null,
    lab_id: "",
    title: "",
    description: "",
    serviceIds: [],
  });
  const [editAttachments, setEditAttachments] = useState([]);
  const [showViewAttachmentsModal, setShowViewAttachmentsModal] = useState(false);
  const [viewAttachments, setViewAttachments] = useState([]);
  const [selectedLabRequest, setSelectedLabRequest] = useState(null);
  const [editLabName, setEditLabName] = useState("");

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [searchLab, setSearchLab] = useState("");

  const [permissions, setPermissions] = useState({
    newRequest: false,
    labs: false,
    labServices: false
  });

  useEffect(() => {
    const checkPermissions = async () => {
      if (isAdmin()) {
        setPermissions({ newRequest: true, labs: true, labServices: true });
        return;
      }

      try {
        const allModules = await fetchModuleMappings();
        const labModule = allModules.find(m => m.module_name.toLowerCase() === 'labs');

        if (labModule && labModule.sub_modules) {
          // Find exact submodule names from database
          const labSub = labModule.sub_modules.find(sm => sm.sub_module_name === 'lab');
          const labServicesSub = labModule.sub_modules.find(sm => sm.sub_module_name === 'lab_services');
          const labNewRequestSub = labModule.sub_modules.find(sm => sm.sub_module_name === 'lab_new_request');

          console.log('Lab submodules found:', { labSub, labServicesSub, labNewRequestSub });

          setPermissions({
            labs: labSub ? hasSubModulePermission(labSub.id) : false,
            labServices: labServicesSub ? hasSubModulePermission(labServicesSub.id) : false,
            newRequest: labNewRequestSub ? hasSubModulePermission(labNewRequestSub.id) : false
          });
        }
      } catch (err) {
        console.error("Error checking permissions", err);
      }
    };

    checkPermissions();
  }, []);

  useEffect(() => {
    setLoading(true);
    setError(null);
    axios
      .post(`${baseurl}getLabRequestsByStatus`, { status: selectedTab })
      .then((res) => {
        if (res.data.success && Array.isArray(res.data.data)) {
          setLabRequests(res.data.data);
        } else {
          setLabRequests([]);
        }
        setLoading(false);
      })
      .catch((err) => {
        setError("Failed to fetch lab requests");
        setLoading(false);
      });
  }, [selectedTab, refreshFlag]);

  useEffect(() => {

    axios.get(`${baseurl}getAllLabs`).then(res => {
      if (res.data.success && Array.isArray(res.data.data)) {
        setLabs(res.data.data);
      }
    });
  }, []);

  const fetchServicesForLab = async (labId, existingServiceIds = []) => {
    if (!labId) {
      setLabServices([]);
      return;
    }

    try {
      const res = await axios.get(`${baseurl}getLabById/${labId}`);
      if (res.data.success && res.data.data && Array.isArray(res.data.data.services)) {
        const services = res.data.data.services;
        setLabServices(services);

        if (Array.isArray(existingServiceIds) && existingServiceIds.length > 0) {
          const validIds = services
            .filter((service) => existingServiceIds.includes(service.id))
            .map((service) => service.id);

          setEditData((prev) => ({
            ...prev,
            serviceIds: validIds,
          }));
        }
      } else {
        setLabServices([]);
      }
    } catch (error) {
      console.error("Failed to fetch lab services", error);
      setLabServices([]);
    }
  };

  const loadLabRequestDetails = async (requestId, labIdFromRow) => {
    try {
      const res = await axios.get(`${baseurl}getLabRequestById/${requestId}`);
      if (res.data.success && res.data.data) {
        const data = res.data.data;

        let serviceIds = [];
        if (Array.isArray(data.serviceIds)) {
          serviceIds = data.serviceIds;
        } else if (typeof data.services_id === "string") {
          try {
            const parsed = JSON.parse(data.services_id);
            if (Array.isArray(parsed)) {
              serviceIds = parsed;
            }
          } catch (e) {
            console.error("Error parsing services_id", e);
          }
        } else if (Array.isArray(data.services_id)) {
          serviceIds = data.services_id;
        }

        const labIdToUse = data.lab_id || labIdFromRow;

        setEditData((prev) => ({
          ...prev,
          lab_id: labIdToUse ? String(labIdToUse) : prev.lab_id,
          serviceIds: serviceIds,
        }));

        if (labIdToUse) {
          fetchServicesForLab(labIdToUse, serviceIds);
        }
      }
    } catch (error) {
      console.error("Failed to load lab request details", error);
    }
  };


  const filteredLabRequests = labRequests.filter((item) => {
    const q = searchLab.toLowerCase();
    return (
      (item.patient_name && item.patient_name.toLowerCase().includes(q)) ||
      (item.lab_name && item.lab_name.toLowerCase().includes(q)) ||
      (item.title && item.title.toLowerCase().includes(q)) ||
      (item.description && item.description.toLowerCase().includes(q)) ||
      (item.patient_civil_id && item.patient_civil_id.toLowerCase().includes(q))
    );
  });

  const totalPages = Math.ceil(filteredLabRequests.length / itemsPerPage);
  const paginatedLabRequests = filteredLabRequests.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );


  useEffect(() => {
    setCurrentPage(1);
  }, [selectedTab, searchLab]);


  const handleDelete = (request_id) => {
    Swal.fire({
      title: 'Are you sure?',
      text: 'You will not be able to recover this request!',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Yes, delete it!',
      cancelButtonText: 'Cancel',
    }).then((result) => {
      if (result.isConfirmed) {
        axios
          .delete(`${baseurl}deleteLabRequest/${request_id}`)
          .then((res) => {
            if (res.data.success) {
              setLabRequests((prev) => prev.filter((item) => item.request_id !== request_id));
              Swal.fire('Deleted!', 'The request has been deleted.', 'success');
            } else {
              Swal.fire('Error', res.data.message || 'Failed to delete request', 'error');
            }
          })
          .catch(() => {
            Swal.fire('Error', 'Server error while deleting request', 'error');
          });
      }
    });
  };

  const handleStatusChange = async (requestId, newStatus) => {
    try {
      const res = await axios.post(`${baseurl}updateLabRequestStatus/${requestId}`, { status: newStatus });
      if (res.data.success) {
        setRefreshFlag(f => f + 1);
        Swal.fire('Success', 'Status updated successfully', 'success');
      } else {
        Swal.fire('Error', res.data.message || 'Failed to update status', 'error');
      }
    } catch {
      Swal.fire('Error', 'Server error while updating status', 'error');
    }
  };

  const handleAddReportClick = (labId) => {
    setReportLabId(labId);
    setShowReportModal(true);
    setReportFile(null);
    setReportName("");
    setReportStatus("");
  };

  const handleEditClick = (lab) => {
    console.log('Lab object for editing:', lab);
    setEditData({
      request_id: lab.request_id,
      lab_id: lab.lab_id ? String(lab.lab_id) : '',
      title: lab.title || '',
      description: lab.description || '',
      serviceIds: [],
    });
    setEditLabName(lab.lab_name || '');
    setShowEditModal(true);


    axios.get(`${baseurl}getLabRequestAttachmentsByLabRequestId/${lab.request_id}`)
      .then((res) => {
        if (res.data.success) {
          setEditAttachments(res.data.data);
        } else {
          setEditAttachments([]);
        }
      })
      .catch((err) => {
        console.error("Error fetching attachments:", err);
        setEditAttachments([]);
      });

    loadLabRequestDetails(lab.request_id, lab.lab_id);
  };

  const handleViewAttachments = (lab) => {
    setSelectedLabRequest(lab);
    setShowViewAttachmentsModal(true);


    axios.get(`${baseurl}getLabRequestAttachmentsByLabRequestId/${lab.request_id}`)
      .then((res) => {
        if (res.data.success) {
          setViewAttachments(res.data.data);
        } else {
          setViewAttachments([]);
        }
      })
      .catch((err) => {
        console.error("Error fetching attachments:", err);
        setViewAttachments([]);
      });
  };

  const handleEditChange = (e) => {
    const { name, value } = e.target;
    setEditData((prev) => ({ ...prev, [name]: value }));

    if (name === "lab_id") {
      setEditData((prev) => ({
        ...prev,
        lab_id: value,
        serviceIds: [],
      }));
      fetchServicesForLab(value, []);
    }
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.put(`${baseurl}updateLabRequest/${editData.request_id}`, {
        lab_id: editData.lab_id,
        title: editData.title,
        description: editData.description,
        serviceIds: editData.serviceIds || [],
      });
      if (res.data.success) {
        setLabRequests((prev) => prev.map((item) =>
          item.request_id === editData.request_id
            ? { ...item, lab_id: editData.lab_id, title: editData.title, description: editData.description }
            : item
        ));
        setShowEditModal(false);
        Swal.fire('Success', 'Lab request updated successfully', 'success');
      } else {
        Swal.fire('Error', res.data.message || 'Failed to update lab request', 'error');
      }
    } catch {
      Swal.fire('Error', 'Server error while updating lab request', 'error');
    }
  };

  const handleDeleteAttachment = async (attachmentId) => {
    Swal.fire({
      title: 'Are you sure?',
      text: 'You will not be able to recover this attachment!',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Yes, delete it!',
      cancelButtonText: 'Cancel',
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          const res = await axios.delete(`${baseurl}deleteLabRequestAttachment/${attachmentId}`);
          if (res.data.success) {
            setEditAttachments((prev) => prev.filter((att) => att.attachment_id !== attachmentId));
            Swal.fire('Deleted!', 'The attachment has been deleted.', 'success');
          } else {
            Swal.fire('Error', res.data.message || 'Failed to delete attachment', 'error');
          }
        } catch {
          Swal.fire('Error', 'Server error while deleting attachment', 'error');
        }
      }
    });
  };

  const handleReportFileChange = (e) => {
    setReportFile(e.target.files[0] || null);
  };

  const handleReportUpload = async () => {
    if (!reportFile || !reportName || !reportStatus) {
      Swal.fire('Error', 'Please select file, enter name and status', 'error');
      return;
    }
    const formData = new FormData();
    formData.append('file', reportFile);
    formData.append('name', reportName);
    formData.append('report_status', reportStatus);
    try {
      const res = await axios.post(`${baseurl}addLabRequestAttachment/${reportLabId}`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      if (res.data.success) {
        setShowReportModal(false);
        Swal.fire('Success', 'Attachment uploaded successfully', 'success');
      } else {
        Swal.fire('Error', res.data.message || 'Failed to upload', 'error');
      }
    } catch (err) {
      Swal.fire('Error', 'Server error while uploading', 'error');
    }
  };
  // download excel
  const handelecli = async () => {
    try {
      const response = await axios.get(
        `${baseurl}dashboard/lab_request_report`,
        {
          responseType: "blob", //  ye important hai
        }
      );
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", "Report.xlsx");
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);

    } catch (error) {
      console.error("Download failed:", error);
    }
  }

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="d-flex gap-2" >
          <div>
            <button className="btn btn-primary  px-4 my-3" onClick={() => navigate("/Admin/newrequest")} disabled={!permissions.newRequest}>
              {" "}
              New Request
            </button>
          </div>
          <div>
            <button
              className="btn btn-primary mx-2 px-4 my-3"
              onClick={() => {
                navigate("/Admin/addlabs");
              }}
              disabled={!permissions.labs}>
              Labs
            </button>
          </div>
          <div>
            <button
              className="btn btn-primary mx-2 px-4 my-3"
              onClick={() => {
                navigate("/Admin/labservices");
              }}
              disabled={!permissions.labServices}>
              Lab Services
            </button>
          </div>
        </div>
        <div class="my-12">
          <div className="w-100 border rounded p-2">
            <ul className="nav nav-pills w-100" id="pills-tab" role="tablist">
              <li className="nav-item" role="presentation">
                <button
                  className={`nav-link${selectedTab === "Not Sent" ? " active" : ""}`}
                  id="pills-home-tab"
                  data-bs-toggle="pill"
                  data-bs-target="#pills-home"
                  type="button"
                  role="tab"
                  onClick={() => setSelectedTab("Not Sent")}
                >
                  New
                </button>
              </li>
              <li className="nav-item" role="presentation">
                <button
                  className={`nav-link${selectedTab === "Pending" ? " active" : ""}`}
                  id="pills-profile-tab"

                  data-bs-toggle="pill"
                  data-bs-target="#pills-profile"
                  type="button"
                  role="tab"
                  onClick={() => setSelectedTab("Pending")}
                >
                  Pending
                </button>
              </li>
              <li className="nav-item" role="presentation">
                <button
                  className={`nav-link${selectedTab === "Received" ? " active" : ""}`}
                  id="pills-contact-tab"
                  data-bs-toggle="pill"
                  data-bs-target="#pills-contact"
                  type="button"
                  role="tab"
                  onClick={() => setSelectedTab("Received")}
                >
                  Received
                </button>
              </li>
            </ul>
          </div>
          <div class="tab-content" id="pills-tabContent">
            <div
              className={`tab-pane fade${selectedTab === "Not Sent" ? " show active" : ""}`}
              id="pills-home"
              role="tabpanel"
              aria-labelledby="pills-home-tab"
            >
              <div className="col-12">
                <div className="card table-card">
                  <div className="card-header">
                    <div className="d-flex ">
                      {/* new tab */}
                      <h5 className="mb-3 mb-sm-0"></h5>
                      <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                        <input
                          type="text"
                          className="form-control"
                          placeholder="Search by patient name..."
                          value={searchLab}
                          onChange={e => {
                            setSearchLab(e.target.value);
                            setCurrentPage(1);
                          }}
                          style={{ paddingLeft: "35px" }}
                        />
                        <span style={{
                          position: "absolute",
                          top: "50%",
                          left: "10px",
                          transform: "translateY(-50%)",
                          pointerEvents: "none",
                          color: "#888"
                        }}>
                          <i className="ti ti-search f-16"></i>
                        </span>


                      </div>
                      <button className="export" onClick={handelecli}>
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="28"
                          height="28"
                          viewBox="0 0 24 24"
                          fill="none"
                          style={{ marginTop: 4, marginRight: 4, marginLeft: 4 }}
                        >
                          <path
                            d="M9 17.75c-.1 0-.19-.02-.29-.06a.74.74 0 0 1-.46-.69v-6c0-.41.34-.75.75-.75s.75.34.75.75v4.19l.72-.72c.29-.29.77-.29 1.06 0 .29.29.29.77 0 1.06l-2 2c-.14.14-.34.22-.53.22Z"
                            fill="currentColor"
                          />
                          <path
                            d="M9 17.751c-.19 0-.38-.07-.53-.22l-2-2a.754.754 0 0 1 0-1.06c.29-.29.77-.29 1.06 0l2 2c.29.29.29.77 0 1.06-.15.15-.34.22-.53.22Z"
                            fill="currentColor"
                          />
                          <path
                            d="M15 22.75H9c-5.43 0-7.75-2.32-7.75-7.75V9c0-5.43 2.32-7.75 7.75-7.75h5c.41 0 .75.34.75.75s-.34.75-.75.75H9C4.39 2.75 2.75 4.39 2.75 9v6c0 4.61 1.64 6.25 6.25 6.25h6c4.61 0 6.25-1.64 6.25-6.25v-5c0-.41.34-.75.75-.75s.75.34.75.75v5c0 5.43-2.32 7.75-7.75 7.75Z"
                            fill="currentColor"
                          />
                          <path
                            d="M22 10.748h-4c-3.42 0-4.75-1.33-4.75-4.75v-4c0-.3.18-.58.46-.69.28-.12.6-.05.82.16l8 8a.751.751 0 0 1-.53 1.28Zm-7.25-6.94v2.19c0 2.58.67 3.25 3.25 3.25h2.19l-5.44-5.44Z"
                            fill="currentColor"
                          />
                        </svg>
                      </button>
                    </div>
                  </div>
                  <div className="card-body pt-3">
                    <div className="table-responsive">
                      <table className="table table-hover" id="pc-dt-simple">
                        <thead>
                          <tr>
                            <th>ID</th>
                            <th>Date</th>
                            <th>Patient</th>
                            <th>Patient ID</th>
                            <th>Lab</th>
                            {/* <th>Service</th> */}
                            {/* <th>Category</th> */}
                            <th>Title</th>
                            <th>Description</th>
                            <th>Days</th>
                            <th>Sent By</th>
                            <th>Status</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {loading ? (
                            <tr><td colSpan="13">Loading...</td></tr>
                          ) : error ? (
                            <tr><td colSpan="13" className="text-danger">{error}</td></tr>
                          ) : paginatedLabRequests.length === 0 ? (
                            <tr><td colSpan="13" className="text-center text-muted">No data found</td></tr>
                          ) : (
                            paginatedLabRequests.map((lab) => (
                              <tr key={lab.request_id}>
                                <td>{lab.request_id}</td>
                                <td>{lab.request_date ? lab.request_date.split('T')[0] : ''}</td>
                                <td>{lab.patient_name}</td>
                                <td>{lab.patient_civil_id}</td>
                                <td>{lab.lab_name}</td>
                                {/* <td>
                                    {lab.service_name ? (
                                      <strong>{lab.service_name}</strong>
                                    ) : (
                                      <span className="text-muted">-</span>
                                    )}
                                  </td>
                                  <td>
                                    {lab.service_category ? (
                                      <span>{lab.service_category}</span>
                                    ) : (
                                      <span className="text-muted">-</span>
                                    )}
                                  </td> */}
                                <td>{lab.title}</td>
                                <td>{lab.description}</td>
                                <td>{lab.days_since_request ?? ''}</td>
                                <td>{lab.sent_by}</td>
                                <td>
                                  <select
                                    id={`status-select-new-${lab.request_id}`}
                                    className="form-select form-select-sm border-primary shadow-sm px-1 py-0"
                                    style={{ minWidth: 90, fontWeight: 500, fontSize: '0.85em', height: '1.8em', backgroundColor: '#f8f9fa' }}
                                    value={lab.status}
                                    title="Change status"
                                    disabled={!permissions.newRequest}
                                    onChange={async e => {
                                      console.log('Original dropdown change:', e.target.value);
                                      const newStatus = e.target.value === 'Cancel' ? 'Cancelled' : e.target.value;
                                      try {
                                        const res = await axios.post(`${baseurl}updateLabRequestStatus/${lab.request_id}`, { status: newStatus });
                                        if (res.data.success) {
                                          setRefreshFlag(f => f + 1);
                                          Swal.fire('Success', 'Status updated successfully', 'success');
                                        } else {
                                          Swal.fire('Error', res.data.message || 'Failed to update status', 'error');
                                        }
                                      } catch {
                                        Swal.fire('Error', 'Server error while updating status', 'error');
                                      }
                                    }}
                                  >
                                    <option value={lab.status} disabled>
                                      {lab.status === "Pending" ? "Sent" : lab.status}
                                    </option>
                                    {lab.status !== "Not Sent" && <option value="Not Sent">Not Sent</option>}
                                    {lab.status !== "Pending" && <option value="Pending">Sent</option>}
                                    {lab.status !== "Cancel" && <option value="Cancel">Cancel</option>}
                                  </select>
                                </td>
                                <td>
                                  <div
                                    onClick={() => navigate(`/Admin/ViewLab/${lab.request_id}`)}
                                    style={{ cursor: "pointer" }}
                                    className="avtar avtar-xs btn-link-secondary viewIcon"
                                  >
                                    <i className="ti ti-eye f-20" />
                                    <span>View</span>
                                  </div>
                                  {permissions.newRequest && (
                                    <>
                                      <div
                                        onClick={() => handleEditClick(lab)}
                                        style={{ cursor: "pointer" }}
                                        className="avtar avtar-xs btn-link-secondary editIcon"
                                      >
                                        <i className="ti ti-edit f-20" />
                                        <span>Edit</span>
                                      </div>
                                      <div
                                        onClick={() => handleDelete(lab.request_id)}
                                        style={{ cursor: "pointer" }}
                                        className="avtar avtar-xs btn-link-secondary deleteIcon"
                                      >
                                        <i className="ti ti-trash f-20" />
                                        <span>Delete</span>
                                      </div>
                                    </>
                                  )}
                                </td>
                              </tr>
                            ))
                          )}
                        </tbody>
                      </table>
                      <div className="d-flex justify-content-end mt-3 mb-2">
                        <TablePagination currentPage={currentPage} totalPages={totalPages} setCurrentPage={setCurrentPage} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div
              className={`tab-pane fade${selectedTab === "Pending" ? " show active" : ""}`}
              id="pills-profile"
              role="tabpanel"
              aria-labelledby="pills-profile-tab"
            >
              <div className="col-12">
                <div className="card table-card">
                  <div className="card-header">
                    <div className="d-sm-flex align-items-center justify-content-between flex-row-reverse">
                      {/* pending tab */}
                      <h5 className="mb-3 mb-sm-0"></h5>
                      <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                        <input
                          type="text"
                          className="form-control"
                          placeholder="Search by patient, lab, title, description..."
                          value={searchLab}
                          onChange={e => {
                            setSearchLab(e.target.value);
                            setCurrentPage(1);
                          }}
                          style={{ paddingLeft: "35px" }}
                        />
                        <span style={{
                          position: "absolute",
                          top: "50%",
                          left: "10px",
                          transform: "translateY(-50%)",
                          pointerEvents: "none",
                          color: "#888"
                        }}>
                          <i className="ti ti-search f-16"></i>
                        </span>
                      </div>
                      {/* <div><a href="../admins/course-teacher-apply.html" className="btn btn-outline-secondary">Apply Teacher List</a> <a href="../admins/course-teacher-add.html" className="btn btn-primary">Add Teacher</a></div> */}
                    </div>
                  </div>
                  <div className="card-body pt-3">
                    <div className="table-responsive">
                      <table className="table table-hover" id="pc-dt-simple">
                        <thead>
                          <tr>
                            <th>ID</th>
                            <th>Date</th>
                            <th>Patient</th>
                            <th>Patient ID</th>
                            <th>Lab</th>
                            {/* <th>Service</th> */}
                            {/* <th>Category</th> */}
                            <th>Title</th>
                            <th>Description</th>
                            <th>Days</th>
                            <th>Sent By</th>
                            <th>Status</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {loading ? (
                            <tr><td colSpan="13">Loading...</td></tr>
                          ) : error ? (
                            <tr><td colSpan="13" className="text-danger">{error}</td></tr>
                          ) : paginatedLabRequests.length === 0 ? (
                            <tr><td colSpan="13" className="text-center text-muted">No data found</td></tr>
                          ) : (
                            paginatedLabRequests.map((lab) => (
                              <tr key={lab.request_id}>
                                <td>{lab.request_id}</td>
                                <td>{lab.pending_at ? lab.pending_at.split('T')[0] : ''}</td>
                                <td>{lab.patient_name}</td>
                                <td>{lab.patient_civil_id}</td>
                                <td>{lab.lab_name}</td>
                                {/* <td>
                                  {lab.service_name ? (
                                    <strong>{lab.service_name}</strong>
                                  ) : (
                                    <span className="text-muted">-</span>
                                  )}
                                </td> */}
                                {/* <td>
                                  {lab.service_category ? (
                                    <span>{lab.service_category}</span>
                                  ) : (
                                    <span className="text-muted">-</span>
                                  )}
                                </td> */}
                                <td>{lab.title}</td>
                                <td>{lab.description}</td>
                                <td>{lab.days_since_request ?? ''}</td>
                                <td>{lab.sent_by}</td>
                                <td>
                                  <select
                                    id={`status-select-pending-${lab.request_id}`}
                                    className="form-select form-select-sm border-primary shadow-sm px-1 py-0"
                                    style={{ minWidth: 90, fontWeight: 500, fontSize: '0.85em', height: '1.8em', backgroundColor: '#f8f9fa' }}
                                    value={lab.status}
                                    title="Change status"
                                    disabled={!permissions.newRequest}
                                    onChange={async e => {
                                      console.log('Pending dropdown change:', e.target.value);
                                      const newStatus = e.target.value === 'Cancel' ? 'Cancelled' : e.target.value;
                                      try {
                                        const res = await axios.post(`${baseurl}updateLabRequestStatus/${lab.request_id}`, { status: newStatus });
                                        if (res.data.success) {
                                          setRefreshFlag(f => f + 1);
                                          Swal.fire('Success', 'Status updated successfully', 'success');
                                        } else {
                                          Swal.fire('Error', res.data.message || 'Failed to update status', 'error');
                                        }
                                      } catch {
                                        Swal.fire('Error', 'Server error while updating status', 'error');
                                      }
                                    }}
                                  >
                                    <option value={lab.status} disabled>
                                      {lab.status === "Pending" ? "Sent" : lab.status === "Received" ? "Completed" : lab.status}
                                    </option>
                                    {lab.status !== "Pending" && <option value="Pending">Sent</option>}
                                    {lab.status !== "Received" && <option value="Received">Completed</option>}
                                    {lab.status !== "Cancel" && <option value="Cancel">Cancel</option>}
                                  </select>
                                </td>
                                <td>
                                  <div
                                    onClick={() => navigate(`/Admin/ViewLab/${lab.request_id}`)}
                                    style={{ cursor: "pointer" }}
                                    className="avtar avtar-xs btn-link-secondary viewIcon"
                                  >
                                    <i className="ti ti-eye f-20" />
                                    <span>View</span>
                                  </div>
                                  {permissions.newRequest && (
                                    <>
                                      <div
                                        onClick={() => handleEditClick(lab)}
                                        style={{ cursor: "pointer" }}
                                        className="avtar avtar-xs btn-link-secondary editIcon"
                                      >
                                        <i className="ti ti-edit f-20" />
                                        <span>Edit</span>
                                      </div>
                                      <div
                                        onClick={() => handleDelete(lab.request_id)}
                                        style={{ cursor: "pointer" }}
                                        className="avtar avtar-xs btn-link-secondary deleteIcon"
                                      >
                                        <i className="ti ti-trash f-20" />
                                        <span>Delete</span>
                                      </div>
                                    </>
                                  )}
                                </td>
                              </tr>
                            ))
                          )}
                        </tbody>
                      </table>
                      <div className="d-flex justify-content-end mt-3 mb-2">
                        <TablePagination currentPage={currentPage} totalPages={totalPages} setCurrentPage={setCurrentPage} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div
              className={`tab-pane fade${selectedTab === "Received" ? " show active" : ""}`}
              id="pills-contact"
              role="tabpanel"
              aria-labelledby="pills-contact-tab"
            >
              <div className="col-12">
                <div className="card table-card">
                  <div className="card-header">
                    <div className="d-sm-flex align-items-center justify-content-between flex-row-reverse">
                      {/* received tab */}
                      <h5 className="mb-3 mb-sm-0"></h5>
                      <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                        <input
                          type="text"
                          className="form-control"
                          placeholder="Search by patient, lab, title, description..."
                          value={searchLab}
                          onChange={e => {
                            setSearchLab(e.target.value);
                            setCurrentPage(1);
                          }}
                          style={{ paddingLeft: "35px" }}
                        />
                        <span style={{
                          position: "absolute",
                          top: "50%",
                          left: "10px",
                          transform: "translateY(-50%)",
                          pointerEvents: "none",
                          color: "#888"
                        }}>
                          <i className="ti ti-search f-16"></i>
                        </span>
                      </div>
                      {/* <div><a href="../admins/course-teacher-apply.html" className="btn btn-outline-secondary">Apply Teacher List</a> <a href="../admins/course-teacher-add.html" className="btn btn-primary">Add Teacher</a></div> */}
                    </div>
                  </div>
                  <div className="card-body pt-3">
                    <div className="table-responsive">
                      <table className="table table-hover" id="pc-dt-simple">
                        <thead>
                          <tr>
                            <th>ID</th>
                            <th>Date</th>
                            <th>Patient</th>
                            <th>Patient ID</th>
                            <th>Lab</th>
                            {/* <th>Service</th> */}
                            {/* <th>Category</th> */}
                            <th>Title</th>
                            <th>Description</th>
                            <th>Days</th>
                            <th>Sent By</th>
                            <th>Attachments</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {loading ? (
                            <tr><td colSpan="13">Loading...</td></tr>
                          ) : error ? (
                            <tr><td colSpan="13" className="text-danger">{error}</td></tr>
                          ) : paginatedLabRequests.length === 0 ? (
                            <tr><td colSpan="13" className="text-center text-muted">No data found</td></tr>
                          ) : (
                            paginatedLabRequests.map((lab) => (
                              <tr key={lab.request_id}>
                                <td>{lab.request_id}</td>
                                <td>{lab.received_at ? lab.received_at.split('T')[0] : ''}</td>
                                <td>{lab.patient_name}</td>
                                <td>{lab.patient_civil_id}</td>
                                <td>{lab.lab_name}</td>
                                {/* <td>
                                  {lab.service_name ? (
                                    <strong>{lab.service_name}</strong>
                                  ) : (
                                    <span className="text-muted">-</span>
                                  )}
                                </td> */}
                                {/* <td>
                                  {lab.service_category ? (
                                    <span>{lab.service_category}</span>
                                  ) : (
                                    <span className="text-muted">-</span>
                                  )}
                                </td> */}
                                <td>{lab.title}</td>
                                <td>{lab.description}</td>
                                <td>{lab.days_since_request ?? ''}</td>
                                <td>{lab.sent_by}</td>
                                <td>
                                  <button
                                    className="btn btn-sm btn-outline-primary"
                                    style={{ minWidth: 90, fontSize: '0.85em', padding: '2px 8px', height: '1.8em' }}
                                    onClick={() => handleAddReportClick(lab.request_id)}
                                  >
                                    Add Report
                                  </button>
                                </td>
                                <td>
                                  <div
                                    onClick={() => navigate(`/Admin/ViewLab/${lab.request_id}`)}
                                    style={{ cursor: "pointer" }}
                                    className="avtar avtar-xs btn-link-secondary viewIcon"
                                  >
                                    <i className="ti ti-eye f-20" />
                                    <span>View</span>
                                  </div>
                                  {permissions.newRequest && (
                                    <>
                                      <div
                                        onClick={() => handleEditClick(lab)}
                                        style={{ cursor: "pointer" }}
                                        className="avtar avtar-xs btn-link-secondary editIcon"
                                      >
                                        <i className="ti ti-edit f-20" />
                                        <span>Edit</span>
                                      </div>
                                      <div
                                        onClick={() => handleDelete(lab.request_id)}
                                        style={{ cursor: "pointer" }}
                                        className="avtar avtar-xs btn-link-secondary deleteIcon"
                                      >
                                        <i className="ti ti-trash f-20" />
                                        <span>Delete</span>
                                      </div>
                                    </>
                                  )}
                                </td>
                              </tr>
                            ))
                          )}
                        </tbody>
                      </table>
                      <div className="d-flex justify-content-end mt-3 mb-2">
                        <TablePagination currentPage={currentPage} totalPages={totalPages} setCurrentPage={setCurrentPage} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>


      {showReportModal && (
        <div
          className="modal fade show"
          style={{ backgroundColor: "rgba(0,0,0,0.5)", display: "block" }}
        >
          <div className="modal-dialog modal-md">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add Report Attachment</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowReportModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label className="form-label">Select File</label>
                  <input
                    type="file"
                    className="form-control form-control-sm"
                    onChange={handleReportFileChange}
                    accept="image/*,application/pdf"
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Name</label>
                  <input
                    type="text"
                    className="form-control form-control-sm"
                    value={reportName}
                    onChange={e => setReportName(e.target.value)}
                    placeholder="Report Name"
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Status</label>
                  <select
                    className="form-select form-select-sm"
                    value={reportStatus}
                    onChange={e => setReportStatus(e.target.value)}
                  >
                    <option value="">Select Status</option>
                    <option value="Positive">Positive</option>
                    <option value="Negative">Negative</option>
                  </select>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowReportModal(false)}>
                  Cancel
                </button>
                <button type="button" className="btn btn-primary" onClick={handleReportUpload}>
                  Upload
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
      {showEditModal && (
        <div
          className="modal fade show"
          style={{
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "block",
          }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Edit Lab Request</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowEditModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <form onSubmit={handleEditSubmit}>
                  <div className="mb-3">
                    <label className="form-label">Lab</label>
                    <select
                      className="form-select"
                      name="lab_id"
                      value={editData.lab_id}
                      onChange={handleEditChange}
                      required
                    >
                      <option value="">Select Lab</option>
                      {editData.lab_id && !labs.some(l => String(l.id) === String(editData.lab_id)) && (
                        <option value={editData.lab_id}>{editLabName || `Selected Lab (${editData.lab_id})`}</option>
                      )}
                      {labs.map(lab => (
                        <option key={lab.id} value={String(lab.id)}>{lab.lab_name}</option>
                      ))}
                    </select>
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Title</label>
                    <input
                      type="text"
                      className="form-control"
                      name="title"
                      value={editData.title}
                      onChange={handleEditChange}
                      placeholder="Enter title"
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Description</label>
                    <textarea
                      className="form-control"
                      name="description"
                      value={editData.description}
                      onChange={handleEditChange}
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Lab Services</label>
                    <Autocomplete
                      multiple
                      id="edit-lab-services"
                      options={labServices || []}
                      getOptionLabel={(option) => {
                        const serviceName = option.serviceName || option.service || option.service_name || option.name || "Unknown Service";
                        const category = option.category || "";
                        const price = option.price ? `${option.price} BHD` : "";
                        let label = serviceName;
                        if (category) label += ` (${category})`;
                        if (price) label += ` - ${price}`;
                        return label;
                      }}
                      value={(editData.serviceIds || [])
                        .map((id) => labServices.find((service) => service.id === id))
                        .filter(Boolean)}
                      onChange={(e, newValue) => {
                        const hasSelectAll = newValue.some(
                          (option) => option && option.isSelectAll
                        );

                        if (hasSelectAll) {
                          const isAllSelected =
                            editData.serviceIds &&
                            labServices.length > 0 &&
                            editData.serviceIds.length === labServices.length;

                          const nextIds = isAllSelected
                            ? []
                            : labServices.map((service) => service.id);

                          setEditData((prev) => ({
                            ...prev,
                            serviceIds: nextIds,
                          }));
                        } else {
                          const filtered = newValue.filter(
                            (option) => !option.isSelectAll
                          );
                          setEditData((prev) => ({
                            ...prev,
                            serviceIds: filtered.map((service) => service.id),
                          }));
                        }
                      }}
                      disabled={!editData.lab_id || labServices.length === 0}
                      renderInput={(params) => (
                        <TextField
                          {...params}
                          placeholder={editData.lab_id ? "Search and select services..." : "Please select a lab first"}
                        />
                      )}
                      renderTags={(value, getTagProps) =>
                        value.map((option, index) => {
                          const serviceName = option.serviceName || option.service || option.service_name || option.name || "Unknown Service";
                          const category = option.category || "";
                          const price = option.price ? `${option.price} BHD` : "";
                          let label = serviceName;
                          if (category) label += ` (${category})`;
                          if (price) label += ` - ${price}`;
                          return (
                            <Chip
                              key={option.id}
                              label={label}
                              {...getTagProps({ index })}
                              color="primary"
                              variant="outlined"
                            />
                          );
                        })
                      }
                      filterOptions={(options, { inputValue }) => {
                        const searchLower = inputValue.toLowerCase();
                        const filtered = options.filter((option) => {
                          const serviceName =
                            option.serviceName ||
                            option.service ||
                            option.service_name ||
                            option.name ||
                            "";
                          const category = option.category || "";
                          return (
                            serviceName.toLowerCase().includes(searchLower) ||
                            category.toLowerCase().includes(searchLower)
                          );
                        });

                        if (!inputValue) {
                          return [
                            {
                              id: "__all__",
                              serviceName: "Select All Services",
                              isSelectAll: true,
                            },
                            ...filtered,
                          ];
                        }

                        return filtered;
                      }}
                      renderOption={(props, option) => {
                        if (option.isSelectAll) {
                          return (
                            <li {...props}>
                              <strong>Select All Services</strong>
                            </li>
                          );
                        }

                        const serviceName =
                          option.serviceName ||
                          option.service ||
                          option.service_name ||
                          option.name ||
                          "Unknown Service";
                        const category = option.category || "";
                        const price = option.price || 0;

                        return (
                          <li {...props}>
                            <div>
                              <strong>{serviceName}</strong>
                              {category && (
                                <small className="text-muted d-block">
                                  Category: {category}
                                </small>
                              )}
                              {price > 0 && (
                                <small className="text-success d-block">
                                  Price: {price} BHD
                                </small>
                              )}
                            </div>
                          </li>
                        );
                      }}
                    />
                  </div>

                  {editAttachments.length > 0 && (
                    <div className="mb-3">
                      <label className="form-label">Attachments ({editAttachments.length})</label>
                      <div className="table-responsive">
                        <table className="table table-sm table-bordered">
                          <thead>
                            <tr>
                              <th>Name</th>
                              <th>File</th>
                              <th>Status</th>
                              <th>Uploaded At</th>
                              <th>Action</th>
                            </tr>
                          </thead>
                          <tbody>
                            {editAttachments.map((attachment) => (
                              <tr key={attachment.attachment_id}>
                                <td>{attachment.attachment_name}</td>
                                <td>
                                  {attachment.filename ? (
                                    <a
                                      href={`${baseurImage}${attachment.filename}`}
                                      target="_blank"
                                      rel="noopener noreferrer"
                                      className="btn btn-sm btn-outline-primary"
                                    >
                                      View File
                                    </a>
                                  ) : 'No file'}
                                </td>
                                <td>{attachment.report_status}</td>
                                <td>{new Date(attachment.uploaded_at).toLocaleDateString()}</td>
                                <td>
                                  <button
                                    type="button"
                                    className="btn btn-sm btn-outline-danger"
                                    onClick={() => handleDeleteAttachment(attachment.attachment_id)}
                                  >
                                    <i className="ti ti-trash"></i>
                                  </button>
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )}

                  <div className="d-flex justify-content-end">
                    <button
                      type="button"
                      className="btn btn-secondary me-2"
                      onClick={() => setShowEditModal(false)}
                    >
                      Cancel
                    </button>
                    <button type="submit" className="btn btn-primary">
                      Save Changes
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      )}
      {showViewAttachmentsModal && (
        <div
          className="modal fade show"
          style={{
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "block",
          }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">View Attachments - {selectedLabRequest?.title}</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowViewAttachmentsModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                {viewAttachments.length > 0 ? (
                  <div className="table-responsive">
                    <table className="table table-bordered">
                      <thead>
                        <tr>
                          <th>Attachment Name</th>
                          <th>File</th>
                          <th>Status</th>
                          <th>Uploaded At</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {viewAttachments.map((attachment) => (
                          <tr key={attachment.attachment_id}>
                            <td>{attachment.attachment_name}</td>
                            <td>
                              {attachment.filename ? (
                                <a
                                  href={`${baseurImage}${attachment.filename}`}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="btn btn-sm btn-outline-primary"
                                >
                                  View File
                                </a>
                              ) : 'No file'}
                            </td>
                            <td>{attachment.report_status}</td>
                            <td>{new Date(attachment.uploaded_at).toLocaleDateString()}</td>
                            <td>
                              <button
                                type="button"
                                className="btn btn-sm btn-outline-danger"
                                onClick={() => {
                                  handleDeleteAttachment(attachment.attachment_id);
                                  // Also remove from viewAttachments
                                  setViewAttachments(prev => prev.filter(att => att.attachment_id !== attachment.attachment_id));
                                }}
                              >
                                <i className="ti ti-trash"></i>
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="alert alert-info">
                    No attachments found for this lab request.
                  </div>
                )}
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowViewAttachmentsModal(false)}
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function TablePagination({ currentPage, totalPages, setCurrentPage }) {
  if (!totalPages || totalPages < 2) return null;
  return (
    <nav className="tablepagination d-flex justify-content-end">
      <ul className="pagination mb-0">
        <li className={`page-item ${currentPage === 1 ? "disabled" : ""}`}>
          <button
            className="page-link"
            onClick={() => currentPage > 1 && setCurrentPage(currentPage - 1)}
          >
            &laquo;
          </button>
        </li>
        <li className="pageNmbr">{`${currentPage} of ${totalPages}`}</li>
        <li className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}>
          <button
            className="page-link"
            onClick={() => currentPage < totalPages && setCurrentPage(currentPage + 1)}
          >
            &raquo;
          </button>
        </li>
      </ul>
    </nav>
  );
}

