import React, { useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import { baseurl } from "../../Baseurl";

export default function ViewInvoice() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { state } = useLocation();
// hihihih
  const initialInvoice = useMemo(() => state?.invoice || null, [state]);

  const [loading, setLoading] = useState(false);
  const [invoice, setInvoice] = useState(initialInvoice);
  // For claim-style simple view we keep only header-level fields

  useEffect(() => {
    let cancelled = false;

    const tryFetch = async (endpoints, pick) => {
      for (const endpoint of endpoints) {
        try {
          const res = await axios.get(endpoint);
          const data = res?.data;
          const picked = pick(data);
          if (picked) return picked;
        } catch (_) {
          // continue to next endpoint
        }
      }
      return null;
    };

    const normalizeInvoice = (raw) => {
      if (!raw) return null;
      const i = Array.isArray(raw) ? raw[0] : raw;
      return {
        id: i.id || i.invoice_id || i.invoiceId || i.invoiceid || id,
        invoice_no: i.invoice_no || i.invoiceNo || i.id || i.invoiceid || id,
        patient_name:
          i.patient_name || `${i.firstName || ""} ${i.lastName || ""}`.trim(),
        total_amount: Number(i.total_amount ?? i.totalAmount ?? i.total ?? 0),
        paid_amount: Number(i.paid_amount ?? i.paidAmount ?? 0),
        remaining_amount: Number(
          i.remaining_amount ?? i.remainingAmount ?? i.remaining ?? 0
        ),
        invoice_date: i.invoice_date || i.updated_at || i.updatedAt || i.date,
        phone: i.MobileNumber || i.MobileNumber,
        total_services: i.total_services,
        services: i.services || [],
        pharmacy: i.pharmacy || [],
      };
    };

    const normalizeItems = (raw) => {
      const data = raw?.data || raw?.items || raw;
      const list = Array.isArray(data) ? data : Array.isArray(raw) ? raw : [];
      const services = [];
      const pharmacy = [];
      list.forEach((x) => {
        const common = {
          id: x.id || x.itemId || x.serviceId || x.pharmacyId,
          name: x.name || x.service_name || x.serviceName || x.item_name,
          qty: Number(x.quantity ?? x.qty ?? 1),
          price: Number(
            x.price ?? x.unit_price ?? x.unitPrice ?? x.amount ?? x.totalPrice ?? 0
          ),
          total: Number(
            x.total ?? x.total_price ?? x.totalPrice ?? (Number(x.quantity ?? x.qty ?? 1) * Number(x.price ?? x.unit_price ?? x.unitPrice ?? x.amount ?? 0))
          ),
        };
        const type = (x.type || x.item_type || x.category || "").toString().toLowerCase();
        if (type.includes("service") || x.serviceId || x.service_name) services.push(common);
        else if (type.includes("pharmacy") || x.pharmacyId || x.item_name) pharmacy.push(common);
        else {
          // fallback: bucket by presence of fields
          (x.serviceId ? services : pharmacy).push(common);
        }
      });
      return { services, pharmacy };
    };

    const load = async () => {
      setLoading(true);
      try {
        // Load invoice header if missing or incomplete
        if (!invoice) {
          const inv = await tryFetch(
            [
              `${baseurl}getInvoiceById/${id}`,
              `${baseurl}getInvoiceDetails/${id}`,
              `${baseurl}invoice/${id}`,
            ],
            (d) => normalizeInvoice(d?.data || d?.invoice || d)
          );
          if (!cancelled) setInvoice(inv);
        }

        // We intentionally skip items/payments here to keep the view minimal
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    load();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const fmt = (n) => Number(n || 0).toFixed(2);
  const fmtDate = (d) => (d ? new Date(d).toLocaleDateString("en-GB") : "-");
  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="col-12">
          <div className="card table-card">
            <div className="tableHeader">
              <h5 style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span
                  style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                  onClick={() => navigate(-1)}
                  title="Back"
                >
                  &larr;
                </span>
                Invoice Details
              </h5>
            </div>
            <div className="card-body" style={{ margin: "15px" }}>
              {loading && <div className="text-center text-muted mb-3">Loading...</div>}

              <div className="row">
                {[ 
                  ["Invoice No", invoice?.invoice_no || id],
                  ["Date", fmtDate(invoice?.invoice_date)],
                  ["Patient", invoice?.patient_name || "-"],
                  ["Phone", invoice?.MobileNumber || "-"],
                  ["Total Amount", `${fmt(invoice?.total_amount)} BHD`],
                  ["Paid Amount", `${fmt(invoice?.paid_amount)} BHD`],
                  ["Remaining", `${fmt(invoice?.remaining_amount ?? ((invoice?.total_amount || 0) - (invoice?.paid_amount || 0)))} BHD`],
                  typeof invoice?.total_services !== 'undefined' ? ["Total Services", String(invoice.total_services)] : null,
                ].filter(Boolean).map(([label, value], idx) => (
                  <div className="col-md-6 mb-3" key={idx}>
                    <label className="form-label">{label}</label>
                    <input type="text" className="form-control" value={value ?? ""} disabled />
                  </div>
                ))}
              </div>

              {/* Services Section */}
              {invoice?.services && invoice.services.length > 0 && (
                <div className="row mt-4">
                  <div className="col-12">
                    <h6 className="mb-3">Services</h6>
                    <div className="table-responsive">
                      <table className="table table-bordered">
                        <thead>
                          <tr>
                            <th>#</th>
                            <th>Service Name</th>
                            <th>Service ID</th>
                          </tr>
                        </thead>
                        <tbody>
                          {invoice.services.map((service, idx) => (
                            <tr key={idx}>
                              <td>{idx + 1}</td>
                              <td>{service.serviceName || service.name || "-"}</td>
                              <td>{service.id || "-"}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}

              {/* Pharmacy Section */}
              {invoice?.pharmacy && invoice.pharmacy.length > 0 && (
                <div className="row mt-4">
                  <div className="col-12">
                    <h6 className="mb-3">Pharmacy Items</h6>
                    <div className="table-responsive">
                      <table className="table table-bordered">
                        <thead>
                          <tr>
                            <th>#</th>
                            <th>Item Name</th>
                            <th>Item ID</th>
                          </tr>
                        </thead>
                        <tbody>
                          {invoice.pharmacy.map((item, idx) => (
                            <tr key={idx}>
                              <td>{idx + 1}</td>
                              <td>{item.name || item.drug_name || "-"}</td>
                              <td>{item.id || "-"}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}



