import React, { useEffect, useState } from "react";
import BarChart from "./Firestchart";
import SecondBar from "./SecondBar";
import ThirdBar from "./ThirdBar";
import FourthBar from "./FourthBar";
import axios from "axios";
import CountUp from "react-countup";
import { baseurl } from "../Baseurl";
import { useNavigate } from "react-router-dom";
import BArchart from "./BArchart";
import Agechart from "../Component/service/Agechart";
import Patientbarchart from "../Pages/Patientbarchart";
import Appointmnetgraph from "./Appointmentgrph";
import Imcoechart from "./Imcoechart";
import { hasPermission } from "../utils/permissions";
