  const [data, setData] = useState([]);
  const [ICD, setICD] = useState([]);
  const [services, setServices] = useState([]);
  const [services1, setServices1] = useState([]);
  const [services2, setServices2] = useState([]);
  const navigate = useNavigate();

  // Track permissions for dashboard cards
  const [permissions, setPermissions] = useState({
    patients: true,
    appointments: true,
    billing: true,
  });

  // Check permissions on mount
  useEffect(() => {
    const checkPermissions = async () => {
      const patientsAccess = await hasPermission("/Admin/patient");
      const appointmentsAccess = await hasPermission("/Admin/appointment2");
      const billingAccess = await hasPermission("/Admin/Billing");

      setPermissions({
        patients: patientsAccess,
        appointments: appointmentsAccess,
        billing: billingAccess,
      });
    };
    checkPermissions();
  }, []);

  // Handle navigation with permission check
  const handleNavigate = async (path) => {
    const hasAccess = await hasPermission(path);
    if (hasAccess) {
      navigate(path);
    } else {
      alert("You don't have permission to access this module.");
    }
  };
  useEffect(() => {
    getDatasetAtEv();
  }, []);
  const getDatasetAtEv = async () => {
    try {
      const response = await axios.get(`${baseurl}dashboard`);
      if (response.status === 200) {
        console.log("API Success:", response.data.data);
        setData(response.data.data);
      } else {
        console.error("Unexpected status:", response.status);
      }
    } catch (err) {
      console.error("API Error:", err);
    }
  };
  useEffect(() => {
    getdata1();
  }, []);
  const getdata1 = async () => {
    const response = await axios.get(`${baseurl}getAllPatientsPaymentSummary`);
    if (response.data) {
      console.log(response.data.data);
      setServices1(response.data.data);
    } else {
      console.log(response.data);
    }
  };
  useEffect(() => {
    getdata();
  }, []);
  const getdata = async () => {
    const response = await axios.get(`${baseurl}dashboard/top_services`);
    if (response.data) {
      console.log(response.data.services);
      setServices(response.data.services);
    } else {
      console.log(response.data);
    }
  };
  useEffect(() => {
    getdata2();
  }, []);
  const getdata2 = async () => {
    const response = await axios.get(
      `${baseurl}dashboard/top_doctors_byAppointments`
    );
    if (response.data) {
      console.log(response.data.data);
      setServices2(response.data.data);
    } else {
      console.log(response.data);
    }
  };
  useEffect(() => {
    ICD1();
  }, []);
  const ICD1 = async () => {
    const response = await axios.get(
      `${baseurl}dashboard/getTop_ICD_Diagnoses`
    );
    if (response.data) {
      console.log(response.data);
      setICD(response.data.diagnoses);
    } else {
      console.log(response.data);
    }
  };
  const formatter = new Intl.NumberFormat("en-US", {
    minimumFractionDigits: 3,
    maximumFractionDigits: 3,
  });
  const sortedServices = [...services1].sort(
    (a, b) => b.pending_balance - a.pending_balance
  );

