import { NavLink, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import { baseurl } from "../../Baseurl";

export default function Service() {
  const navigate = useNavigate();
  const [patients, setPatients] = useState([]);
  const [patients1, setPatients1] = useState([]);
  const [openVital121, setOpenVital121] = useState(false);
  const [editabledata, setEditabledata] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [isEditMode, setIsEditMode] = useState(false);
  const [editId, setEditId] = useState(null);
  const [inpval, setInpval] = useState({
    serviceName: "",
    description: "",
    category: "",
    durationMinutes: "",
    standardCost: "",
    secondaryCost: "",
    insuranceCost: "",
    serviceCode: "",
    vat: "No",
    isDental: false, // "Yes" | "No"
    dentalMode: "single", // "Single" | "Multiple"
  });
  const [vatValue, setVatValue] = useState(0);
  const [fieldErrors, setFieldErrors] = useState({
    standardCost: '',
    secondaryCost: '',
    insuranceCost: ''
  });

  useEffect(() => {
    getdata();
  }, []);

  const getdata = async () => {
    try {
      const response = await axios.get(`${baseurl}getServices`);
      if (response.data.success === true) {
        setPatients(response.data.data);
      } else {
        console.error("Failed to fetch patient data:", response.data.message);
      }
    } catch (error) {
      console.error("Error fetching patient data:", error.message);
    }
  };

  const handledelete = async (id) => {
    const confirm = await Swal.fire({
      title: "Are you sure?",
     
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Yes, delete it!",
    });
    if (confirm.isConfirmed) {
      try {
        await axios.delete(`${baseurl}deleteService/${id}`);
        Swal.fire("Deleted!", "Service has been deleted.", "success");
        getdata();
      } catch (error) {
        Swal.fire("Error!", "Something went wrong while deleting.", "error");
      }
    }
  };

  const handlechange = (e) => {
    const { name, value } = e.target;
    setInpval({ ...inpval, [name]: value });
    // Inline numeric validation for cost fields
    if (["standardCost", "secondaryCost", "insuranceCost"].includes(name)) {
      const hasValue = String(value).trim() !== ''
      const isValid = Number.isFinite(Number(value))
      setFieldErrors(prev => ({
        ...prev,
        [name]: hasValue && !isValid ? 'Must be a valid number' : ''
      }))
    }
    if(name ==="vat" && value === "Yes"){
      fetchVatValue();
    }
    if(name === "vat" && value ==="No"){
      setVatValue(0);
    }
  };

  const viewmoal = (item) => {
    console.log(item);
    setEditabledata(true);
    setInpval({
      serviceName: item.name,
      description: item.description,
      // Ensure the select binds to the actual category id
      category: item.categoryId ?? item.category_id ?? item.category ?? "",
      // API uses `duration`; fall back to `durationMinutes` just in case
      durationMinutes: item.duration ?? item.durationMinutes ?? "",
      standardCost: item.standard_price,
      secondaryCost: item.secondary_price,
      insuranceCost: item.insurance_price,
      serviceCode: item.code,
      // VAT and Dental fields for view
      vat: item.vat || "No",
      isDental:
        item.isDental === true ||
        item.is_dental === true ||
        item.is_dental === 1 ||
        item.is_dental === "1" ||
        item.is_dental === "Yes" ||
        item.is_dental === "true" ||
        item.isDental === "Yes" ||
        item.isDental === "true",
      dentalMode:
        String(
          item.dentalMode ?? item.dental_mode ?? item.DentalMode ?? "single"
        ).toLowerCase() === "multiple"
          ? "multiple"
          : "single",
    });
    // Set VAT value for view context
    if (item.vat === "Yes") {
      setVatValue(Number(item.vat_value) || 0);
    } else {
      setVatValue(0);
    }
    setEditId(item.id);
  };

  const handleclickoffmodal = () => {
    setEditabledata(false);
  };

  const handleEdit = (item) => {
    setInpval({
      serviceName: item.name,
      description: item.description,
      category: item.categoryId,
      durationMinutes: item.duration,
      standardCost: item.standard_price,
      secondaryCost: item.secondary_price,
      insuranceCost: item.insurance_price,
      serviceCode: item.code,
        vat: item.vat || "No",
        // Normalize to boolean for state usage (checkbox expects boolean)
        isDental:
          item.isDental === true ||
          item.is_dental === true ||
          item.is_dental === 1 ||
          item.is_dental === "1" ||
          item.is_dental === "Yes" ||
          item.is_dental === "true" ||
          item.isDental === "Yes" ||
          item.isDental === "true",
        // Normalize to lowercase values 'single' | 'multiple' for API
        dentalMode:
          String(
            item.dentalMode ?? item.dental_mode ?? item.DentalMode ?? "single"
          ).toLowerCase() === "multiple"
            ? "multiple"
            : "single",
    });
    if(item.vat === "Yes"){
      setVatValue(item.vat_value);
    }else{
      setVatValue(0);
    }

    setEditId(item.id);
    setIsEditMode(true);
    setOpenVital121(true);
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1);
  };

  const filteredPatients = patients.filter(
    (item) =>
      item.code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.insurance_price?.toString().includes(searchTerm) ||
      item.duration?.toString().includes(searchTerm) ||
      item.insurance_price?.toString().includes(searchTerm) ||
      item.secondary_price?.toString().includes(searchTerm) ||
      item.type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.primaryDoctor?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalPages = Math.ceil(filteredPatients.length / itemsPerPage);
  const indexOfLast = currentPage * itemsPerPage;
  const indexOfFirst = indexOfLast - itemsPerPage;
  const currentPatients = filteredPatients.slice(indexOfFirst, indexOfLast);

  const handleclickopenvital11 = () => {
    setOpenVital121(true);
    fetchVatValue();
  };

  const hndleclosemodalservice = () => {
    setOpenVital121(false);
    setIsEditMode(false);
    setEditId(null);
    setInpval({
      serviceName: "",
      description: "",
      category: "",
      durationMinutes: "",
      standardCost: "",
      secondaryCost: "",
      insuranceCost: "",
      serviceCode: "",
      vat: "No",
      isDental: false,
      dentalMode: "single",
    });
  };

  const handlesavevital123 = async () => {
    try {
      // Validate required fields first so empty form shows a clear message
      const required = [
        { key: 'serviceName', label: 'Service Name' },
        { key: 'category', label: 'Category' },
        { key: 'durationMinutes', label: 'Duration' },
        { key: 'standardCost', label: 'Standard Cost' },
        { key: 'secondaryCost', label: 'Secondary Cost' },
        { key: 'insuranceCost', label: 'Insurance Cost' }
      ]
      const missing = required.filter(f => String(inpval[f.key] ?? '').trim() === '')
      if (missing.length > 0) {
        const list = missing.map(m => m.label).join(', ')
        Swal.fire("Validation Error", `Please fill required fields: ${list}.`, "warning")
        return
      }

      // Numeric validations
      if(!Number.isFinite(Number(inpval.standardCost))){
        Swal.fire("Validation Error", "Standard Cost must be a valid number.", "warning");
        return;
      }
      if(!Number.isFinite(Number(inpval.secondaryCost))){
        Swal.fire("Validation Error","Secondary Cost must be a valid number.","warning");
        return;
      }
      if(!Number.isFinite(Number(inpval.insuranceCost))){
        Swal.fire("Validation Error","Insurance Cost must be a valid number.","warning");
        return;
      }
      if(!Number.isFinite(Number(inpval.durationMinutes))){
        Swal.fire("Validation Error","Duration must be a valid number (minutes).","warning");
        return;
      }

      const dataPost = {
        serviceName: inpval.serviceName,
        description: inpval.description,
        category: parseInt(inpval.category),
        durationMinutes: parseInt(inpval.durationMinutes),
        standardCost: parseInt(inpval.standardCost),
        secondaryCost: parseInt(inpval.secondaryCost),
        insuranceCost: parseInt(inpval.insuranceCost),
        serviceCode: inpval.serviceCode,
        vat: inpval.vat,
        vat_value: inpval.vat === "Yes" ? Number(vatValue) : 0,
       
        isDental: inpval.isDental === true,
        dentalMode:
          String(inpval.dentalMode || "single").toLowerCase() === "multiple"
            ? "multiple"
            : "single",
      };

      let response;
      if (isEditMode) {
        response = await axios.put(
          `${baseurl}updateService/${editId}`,
          dataPost
        );
      } else {
        response = await axios.post(`${baseurl}addServices`, dataPost);
      }

      if (response.status === 200 || response.status === 201) {
        hndleclosemodalservice();
        getdata();
        Swal.fire(
          "Success",
          `Service ${isEditMode ? "updated" : "added"} successfully.`,
          "success"
        );
      } else {
        Swal.fire("Error", "Unexpected server response.", "error");
      }
    } catch (error) {
      console.error("Error saving service:", error);
      // Swal.fire("Error", "Something went wrong. Please try again.", "error");
      Swal.fire(
        "Error",
        error.response?.data?.message || error.message || "Something went wrong. Please try again.",
        "error"
      )
    }
  };

  useEffect(() => {
    getdata1();
  }, []);

  const getdata1 = async () => {
    try {
      const response = await axios.get(`${baseurl}getAllServiceCategories`);
      if (response.data.success === true) {
        console.log(response.data);
        setPatients1(response.data.data);
      } else {
        console.error("Failed to fetch patient data:", response.data.message);
      }
    } catch (error) {
      console.error("Error fetching patient data:", error.message);
    }
  };

  const fetchVatValue = async () => {
    try {
      const res = await axios.get(`${baseurl}getAllVat`);
      const value = Array.isArray(res?.data?.data) && res.data.data.length > 0
        ? Number(res.data.data[0].vat_value)
        : Number(res?.data?.vat_value ?? 0);
      setVatValue(Number.isFinite(value) ? value : 0);
    } catch (e) {
      setVatValue(0);
    }
  };

  return (
    <div className="pc-container ">
      <div className="pc-content">
        <div className="row">
          <div className="col-12 searchParent">
            <h5>Service list</h5>
          </div>
          <div className="col-md-12">
            <div className="card table-card patientCardHeader">
              <div className="tableHeader">
                <div className="d-sm-flex align-items-center justify-content-between">
                  <div className="tableSearch">
                    <input
                      type="text"
                      placeholder="Search by name, or mobile"
                      className="form-control"
                      value={searchTerm}
                      onChange={handleSearchChange}
                    />
                    <span className="searchIcon">
                      <svg
                        xmlns="http:www.w3.org/2000/svg"
                        width="18"
                        height="18"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="gray"
                        style={{
                          position: "absolute",
                          top: "50%",
                          left: "10px",
                          transform: "translateY(-50%)",
                          pointerEvents: "none",
                        }}
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M21 21l-4.35-4.35M17 10a7 7 0 11-14 0 7 7 0 0114 0z"
                        />
                      </svg>
                    </span>
                  </div>
                  <div className="tableHeaderBtn">
                    <button className="bgBtn" onClick={handleclickopenvital11}>
                      <i className="fas fa-plus me-2"></i> Add service
                    </button>
                  </div>
                </div>
              </div>
              <div className="pb-0">
                <div className="table-responsive">
                  <table className="table">
                    <thead>
                      <tr>
                        <th>SN</th>
                        <th>Code</th>
                        <th>Service Name</th>
                        <th>Duration</th>
                        <th>Insurance Price</th>
                        <th>Category</th>
                        <th>Standard Cost</th>
                        <th>Secondary Cost</th>
                        <th>VAT</th>
                        <th>Dental</th>
                        <th>Description</th>
                        <th className="text-center">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {currentPatients.length > 0 ? (
                        currentPatients.map((item, index) => (
                          <tr key={index}>
                            <td>{indexOfFirst + index + 1}</td>
                            <td>{item.code}</td>
                            <td>{item.name}</td>
                            <td>{item.duration}</td>
                            <td>{item.insurance_price}</td>
                            <td>{item.categoryName}</td>
                            <td>{item.standard_price}</td>
                            <td>{item.secondary_price}</td>
                            <td>{item.vat === "Yes" ? `${item.vat_value}%` : "0%"}</td>
                            <td>{(() => {
                              // API sends isDental as 1 or 0 (may also appear as string/boolean in some cases)
                              const isDentalRaw = item.isDental ?? item.is_dental ?? item.is_Dental;
                              const isDentalFlag =
                                isDentalRaw === 1 ||
                                isDentalRaw === "1" ||
                                isDentalRaw === true ||
                                isDentalRaw === "true" ||
                                isDentalRaw === "Yes";
                              if (!isDentalFlag) return "-";
                              const modeRaw = item.dentalMode ?? item.dental_mode ?? item.DentalMode ?? "single";
                              const mode = String(modeRaw).toLowerCase() === "multiple" ? "multiple" : "single";
                              return mode;
                            })()}</td>
                            <td>{item.description}</td>
                            <td>
                              <div
                                onClick={() => viewmoal(item)}
                                className="avtar avtar-xs btn-link-secondary viewIcon"
                              >
                                <i className="ti ti-eye f-20" />
                                <span>View</span>
                              </div>
                              <a
                                href="#"
                                className="avtar avtar-xs btn-link-secondary editIcon"
                                onClick={() => handleEdit(item)}
                              >
                                <i className="ti ti-edit f-20" />
                                <span>Edit</span>
                              </a>
                              <div
                                style={{ cursor: "pointer" }}
                                className="avtar avtar-xs btn-link-secondary deleteIcon"
                                onClick={() => handledelete(item.id)}
                              >
                                <i className="ti ti-trash f-20" />
                                <span>Delete</span>
                              </div>
                            </td>
                          </tr>
                        ))
                      ) : (
                        <tr>
                          <td colSpan="12" className="text-center">
                            No Service found.
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
                {totalPages > 1 && (
                  <div className="d-flex justify-content-end mt-3">
                    <Pagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      setCurrentPage={setCurrentPage}
                    />
                  </div>
                )}
              </div>
              {editabledata && (
                <div
                  className="modal fade show"
                  style={{
                    backgroundColor: "rgba(81, 81, 81, 0.5)",
                    display: "block",
                  }}
                >
                  <div className="modal-dialog modal-lg">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h5 className="modal-title">
                          {isEditMode ? "Edit Service" : "View Service"}
                        </h5>
                        <button
                          type="button"
                          className="btn-close"
                          onClick={handleclickoffmodal}
                        ></button>
                      </div>
                      <div className="modal-body">
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Service Name</label>
                            <input
                              type="text"
                              name="serviceName"
                              value={inpval.serviceName}
                              placeholder="Enter Service Name"
                              className="form-control"
                              readOnly
                            />
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">description</label>
                            <input
                              type="text"
                              name="description"
                              value={inpval.description}
                              placeholder="Enter description"
                              className="form-control"
                              readOnly
                            />
                          </div>
                        </div>
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Category</label>
                            <select
                              className="form-control py-2"
                              name="category"
                              value={inpval.category}
                              disabled
                            >
                              <option>Select</option>
                              {patients1 &&
                                patients1.length > 0 &&
                                patients1.map((item, index) => {
                                  return (
                                    <>
                                      <option value={item.id}>
                                        {item.category_name}
                                      </option>
                                    </>
                                  );
                                })}
                            </select>
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">Duration</label>
                            <input
                              type="text"
                              name="durationMinutes"
                              value={inpval.durationMinutes}
                              placeholder="Enter Duration in Minutes"
                              className="form-control"
                              readOnly
                            />
                          </div>
                        </div>
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Standard Cost</label>
                            <input
                              type="number"
                              name="standardCost"
                              value={inpval.standardCost}
                              placeholder="Enter Standard Cost"
                              className="form-control"
                              readOnly
                            />
                            {fieldErrors.standardCost && (
                              <div className="text-danger small mt-1">Standard Cost {fieldErrors.standardCost}.</div>
                            )}
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">Secondary Cost</label>
                            <input
                              type="number"
                              name="secondaryCost"
                              value={inpval.secondaryCost}
                              placeholder="Enter Secondary Cost"
                              className="form-control"
                              readOnly
                            />
                            {fieldErrors.secondaryCost && (
                              <div className="text-danger small mt-1">Secondary Cost {fieldErrors.secondaryCost}.</div>
                            )}
                          </div>
                        </div>
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Service Code</label>
                            <input
                              type="text"
                              name="serviceCode"
                              value={inpval.serviceCode}
                              placeholder="Enter Service Code"
                              className="form-control"
                              readOnly
                            />
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">Insurance Cost</label>
                            <input
                              type="number"
                              name="insuranceCost"
                              value={inpval.insuranceCost}
                              placeholder="Enter Insurance Cost"
                              className="form-control"
                              readOnly
                            />
                            {fieldErrors.insuranceCost && (
                              <div className="text-danger small mt-1">Insurance Cost {fieldErrors.insuranceCost}.</div>
                            )}
                          </div>
                        </div>
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">VAT</label>
                            <select
                              name="vat"
                              value={inpval.vat}
                              className="form-select"
                              disabled
                            >
                              <option value="No">No</option>
                              <option value="Yes">Yes</option>
                            </select>
                            {inpval.vat === "Yes" && (
                              <div className="form-text">Applied VAT: {vatValue}%</div>
                            )}
                          </div>
                          <div className="col-md-6 d-flex align-items-center">
                            <div className="form-check">
                              <input
                                className="form-check-input"
                                type="checkbox"
                                id="isDentalView"
                                checked={inpval.isDental === true}
                                readOnly
                                disabled
                              />
                              <label className="form-check-label" htmlFor="isDentalView">
                                Dental?
                              </label>
                            </div>
                          </div>
                        </div>
                        {inpval.isDental === true && (
                          <div className="row mt-2">
                            <div className="col-md-6">
                              <label className="form-label">Dental Mode</label>
                              <select
                                className="form-select"
                                value={inpval.dentalMode}
                                disabled
                              >
                                <option value="single">Single Teeth (price per tooth)</option>
                                <option value="multiple">Multiple Teeth (single price)</option>
                              </select>
                            </div>
                          </div>
                        )}
                        <div className="modal-footer my-3">
                          <button
                            type="button"
                            className="btn btn-light"
                            onClick={handleclickoffmodal}
                          >
                            Cancel
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
              {openVital121 && (
                <div
                  className="modal fade show"
                  style={{
                    backgroundColor: "rgba(81, 81, 81, 0.5)",
                    display: "block",
                  }}
                >
                  <div className="modal-dialog modal-lg">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h5 className="modal-title">
                          {isEditMode ? "Edit Service" : "Add Service"}
                        </h5>
                        <button
                          type="button"
                          className="btn-close"
                          onClick={hndleclosemodalservice}
                        ></button>
                      </div>
                      <div className="modal-body">
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Service Name</label>
                            <input
                              type="text"
                              name="serviceName"
                              value={inpval.serviceName}
                              onChange={handlechange}
                              placeholder="Enter Service Name"
                              className="form-control"
                            />
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">Description</label>
                            <input
                              type="text"
                              name="description"
                              value={inpval.description}
                              onChange={handlechange}
                              placeholder="Enter description"
                              className="form-control"
                            />
                          </div>
                        </div>
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Category</label>
                            <select
                              className="form-select py-2"
                              name="category"
                              onChange={handlechange}
                              value={inpval.category}
                            >
                              <option>Select</option>
                              {patients1 &&
                                patients1.length > 0 &&
                                patients1.map((item, index) => {
                                  return (
                                    <>
                                      <option key={index} value={item.id}>
                                        {item.category_name}
                                      </option>
                                    </>
                                  );
                                })}
                            </select>
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">Duration</label>
                            <select
                              name="durationMinutes"
                              value={inpval.durationMinutes}
                              onChange={handlechange}
                              className="form-control"
                            >
                              <option value="">
                                Select Duration (in minutes)
                              </option>
                              {[5, 10, 15, 20, 30, 45, 60].map((min) => (
                                <option key={min} value={min}>
                                  {min}
                                </option>
                              ))}
                            </select>
                          </div>
                        </div>
                        <div className="row">
                          <div className="col-md-6">
                            <label className="form-label">Standard Cost</label>
                            <input
                              type="text"
                              name="standardCost"
                              value={inpval.standardCost}
                              onChange={handlechange}
                              placeholder="Enter Standard Cost"
                              className="form-control"
                            />
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">Secondary Cost</label>
                            <input
                              type="text"
                              name="secondaryCost"
                              value={inpval.secondaryCost}
                              onChange={handlechange}
                              placeholder="Enter Secondary Cost"
                              className="form-control"
                            />
                          </div>
                        </div>
                        <div className="row">
                          {/* <div className="col-md-6">
                            <label className="form-label">Service Code</label>
                            <input
                              type="text"
                              name="serviceCode"
                              value={inpval.serviceCode}
                              onChange={handlechange}
                              placeholder="Enter Service Code"
                              className="form-control"
                            />
                          </div> */}
                          <div className="col-md-6">
                            <label className="form-label">Insurance Cost</label>
                            <input
                              type="text"
                              name="insuranceCost"
                              value={inpval.insuranceCost}
                              onChange={handlechange}
                              placeholder="Enter Insurance Cost"
                              className="form-control"
                            />
                          </div>
                          <div className="col-md-6">
                            <label className="form-label">VAT</label>
                            <select
                              name="vat"
                              value={inpval.vat}
                              onChange={handlechange}
                              className="form-select"
                            >
                              <option value="No">No</option>
                              <option value="Yes">Yes</option>
                            </select>
                            {inpval.vat === "Yes" && (
                              <div className="form-text">Applied VAT: {vatValue}%</div>
                            )}
                          </div>
                        </div>
                        <div className="row mt-2">
                          <div className="col-md-6 d-flex align-items-center">
                            <div className="form-check">
                              <input
                                className="form-check-input"
                                type="checkbox"
                                id="isDental"
                                checked={inpval.isDental === true}
                                onChange={(e) =>
                                  setInpval({
                                    ...inpval,
                                    isDental: e.target.checked ? true : false,
                                    dentalMode: e.target.checked ? inpval.dentalMode : "single",
                                  })
                                }
                              />
                              <label className="form-check-label" htmlFor="isDental">
                                Dental?
                              </label>
                            </div>
                          </div>
                          {inpval.isDental === true && (
                            <div className="col-md-6">
                              <label className="form-label">Dental Mode</label>
                              <select
                                className="form-select"
                                value={inpval.dentalMode}
                                onChange={(e) => setInpval({ ...inpval, dentalMode: e.target.value })}
                              >
                                <option value="single">Single Teeth (price per tooth)</option>
                                <option value="multiple">Multiple Teeth (single price)</option>
                              </select>
                            </div>
                          )}
                        </div>
                        <div className="modal-footer my-3">
                          <button
                            type="button"
                            className="btn btn-primary"
                            onClick={handlesavevital123}
                          >
                            {isEditMode ? "Update Service" : "Add Service"}
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function Pagination({ currentPage, totalPages, setCurrentPage }) {
  return (
    <div className="d-flex align-items-center gap-3">
      <button
        className="btn btn-sm btn-outline-primary"
        onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
        disabled={currentPage === 1}
      >
        &lt;&lt;
      </button>
      <span>{currentPage} / {totalPages}</span>
      <button
        className="btn btn-sm btn-outline-primary"
        onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
        disabled={currentPage === totalPages}
      >
        &gt;&gt;
      </button>
    </div>
  );
}
