import React, { useEffect, useState } from "react";
import axios from "axios";
import { baseurl } from "../../Baseurl";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";

export default function LabServices() {
  const [labServicesData, setLabServicesData] = useState([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [viewModalOpen, setViewModalOpen] = useState(false);
  const [viewItem, setViewItem] = useState(null);
  const [editItem, setEditItem] = useState(null);
  const [formData, setFormData] = useState({ category: "", serviceName: "", price: "" });
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);

  const navigate = useNavigate();

  const getLabServices = async () => {
    try {
      const res = await axios.get(`${baseurl}getAllLabServices`);
      console.log("API Response:", res.data);
      console.log("Lab Services Data:", res.data.data);
      setLabServicesData(res.data.data || []);
    } catch (error) {
      console.error("Error fetching lab services:", error);
      Swal.fire("Error", "Failed to load lab services", "error");
    }
  };

  const handleEdit = (item) => {
    const serviceName = item.serviceName || item.service || item.service_name || item.name || "";
    setFormData({ category: item.category || "", serviceName, price: item.price || "" });
    setEditItem(item);
    setModalOpen(true);
  };

  const handleDelete = async (id) => {
    const confirm = await Swal.fire({
      title: "Are you sure?",
      text: "This lab service will be deleted permanently!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Yes, delete it!",
    });

    if (confirm.isConfirmed) {
      try {
        await axios.delete(`${baseurl}deleteLabService/${id}`);
        Swal.fire("Deleted!", "Lab service has been deleted.", "success");
        getLabServices();
      } catch (error) {
        console.error("Delete failed", error);
        Swal.fire("Error", "Something went wrong!", "error");
      }
    }
  };

  const handleAddEdit = async (e) => {
    e.preventDefault();
    try {
      if (editItem?.id) {
        await axios.put(`${baseurl}editLabServices/${editItem.id}`, formData);
        Swal.fire("Success", "Lab service updated successfully", "success");
      } else {
        await axios.post(`${baseurl}addLabService`, formData);
        Swal.fire("Success", "Lab service added successfully", "success");
      }
      resetForm();
      getLabServices();
    } catch (error) {
      console.error("Submit failed", error);
      Swal.fire("Error", "Something went wrong!", "error");
    }
  };



  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const resetForm = () => {
    setFormData({ category: "", serviceName: "", price: "" });
    setEditItem(null);
    setModalOpen(false);
  };

  useEffect(() => {
    getLabServices();
  }, []);

  const filteredLabServices = labServicesData.filter((service) => {
    const serviceName = service.serviceName || service.service || service.service_name || service.name;
    return (
      (serviceName && serviceName.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (service.category && service.category.toLowerCase().includes(searchQuery.toLowerCase()))
    );
  });


  const totalPages = Math.ceil(filteredLabServices.length / itemsPerPage);
  const paginatedLabServices = filteredLabServices.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );


  const Pagination = ({ currentPage, totalPages, setCurrentPage }) => {
    return (
      <div className="d-flex align-items-center gap-3">
        <button
          className="btn btn-sm btn-outline-primary"
          onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
          disabled={currentPage === 1}
        >
          &lt;&lt;
        </button>
        <span>{currentPage} / {totalPages}</span>
        <button
          className="btn btn-sm btn-outline-primary"
          onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
          disabled={currentPage === totalPages}
        >
          &gt;&gt;
        </button>
      </div>
    );
  };

  return (
    <>
      <div className="pc-container">
        <div className="pc-content">
          <div className="row">
            <div className="col-12">
              <div className="col-12 searchParent">
                <h5 className="" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span
                    style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                    onClick={() => navigate(-1)}
                    title="Back"
                  >
                    &larr;
                  </span>
                  Lab Services List
                </h5>
              </div>

              <div className="table-card patientCardHeader">
                <div className="d-flex justify-content-between align-items-center mb-3">


                  <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                    <input
                      type="text"
                      placeholder="Search by category or service..."
                      value={searchQuery}
                      onChange={(e) => {
                        setSearchQuery(e.target.value);
                        setCurrentPage(1);
                      }}
                      className="form-control"
                      style={{ paddingLeft: "35px" }}
                    />
                    <span style={{
                      position: "absolute",
                      top: "50%",
                      left: "10px",
                      transform: "translateY(-50%)",
                      pointerEvents: "none",
                      color: "#888"
                    }}>
                      <i className="ti ti-search f-16"></i>
                    </span>
                  </div>

                  {/* Action Buttons */}
                  
                    <button className="btn btn-primary mx-2 px-4 my-3" onClick={() => { setEditItem(null); setModalOpen(true); }}>
                      Add Lab Service
                    </button>
                  

                </div>
                <table className="table">
                  <thead>
                    <tr className="text-center">
                      <th>Sr No.</th>
                      <th>Category</th>
                      <th>Service</th>
                      <th>Price</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {paginatedLabServices.length > 0 ? (
                      paginatedLabServices.map((item, index) => {
                        console.log("Service item:", item);
                        return (
                          <tr key={item.id} className="text-center">
                            <td>{(currentPage - 1) * itemsPerPage + index + 1}</td>
                            <td>{item.category}</td>
                            <td>{item.serviceName || item.service || item.service_name || item.name || 'N/A'}</td>
                            <td>{(item.price ? `${item.price} BHD` : 'N/A')}</td>
                            <td>
                              <div
                                onClick={() => {
                                  setViewItem(item);
                                  setViewModalOpen(true);
                                }}
                                style={{ cursor: "pointer" }}
                                className="avtar avtar-xs btn-link-secondary viewIcon"
                              >
                                <i className="ti ti-eye f-20" />
                                <span>View</span>
                              </div>
                              <div
                                onClick={() => handleEdit(item)}
                                style={{ cursor: "pointer" }}
                                className="avtar avtar-xs btn-link-secondary editIcon"
                              >
                                <i className="ti ti-edit f-20" />
                                <span>Edit</span>
                              </div>
                              <div
                                onClick={() => handleDelete(item.id)}
                                style={{ cursor: "pointer" }}
                                className="avtar avtar-xs btn-link-secondary deleteIcon"
                              >
                                <i className="ti ti-trash f-20" />
                                <span>Delete</span>
                              </div>
                            </td>
                          </tr>
                        );
                      })
                    ) : (
                      <tr>
                        <td colSpan={5} className="text-center">
                          No lab services found.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>


                {totalPages > 1 && (
                  <div className="d-flex justify-content-end mt-3">
                    <Pagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      setCurrentPage={setCurrentPage}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>


      {modalOpen && (
        <div
          className="modal fade show"
          style={{
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "block",
          }}
        >
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">
                  {editItem ? "Edit Lab Service" : "Add Lab Service"}
                </h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={resetForm}
                ></button>
              </div>
              <form onSubmit={handleAddEdit}>
                <div className="modal-body">
                  <div className="mb-3">
                    <label className="form-label">Category</label>
                    <input
                      type="text"
                      className="form-control"
                      name="category"
                      value={formData.category}
                      onChange={handleInputChange}
                      placeholder="Enter category"
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Service</label>
                    <input
                      type="text"
                      className="form-control"
                      name="serviceName"
                      value={formData.serviceName}
                      onChange={handleInputChange}
                      placeholder="Enter service"
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Price</label>
                    <input
                      type="number"
                      className="form-control"
                      name="price"
                      value={formData.price}
                      onChange={handleInputChange}
                      placeholder="Enter price"
                      min="0"
                      step="0.01"
                    />
                  </div>
                </div>
                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn borderBtn"
                    onClick={resetForm}
                  >
                    Cancel
                  </button>
                  <button type="submit" className="btn bgBtn">
                    {editItem ? "Update" : "Add"}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}


      {viewModalOpen && (
        <div
          className="modal fade show"
          style={{
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "block",
          }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Lab Service Details</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setViewModalOpen(false)}
                ></button>
              </div>
              <div className="modal-body">
                <div className="container">
                  <form>
                    <div className="row">
                      <div className="col-md-6">
                        <div className="">
                          {/* <label className="form-label">Service ID</label> */}
                          {/* <input
                            type="text"
                            className="form-control"
                            value={viewItem?.id || ''}
                            readOnly
                          /> */}
                        </div>
                        <div className="mb-3">
                          <label className="form-label">Category</label>
                          <input
                            type="text"
                            className="form-control"
                            value={viewItem?.category || ''}
                            readOnly
                          />
                        </div>
                        {/* <div className="mb-3">
                               <label className="form-label">Created Date</label>
                               <input
                                 type="text"
                                 className="form-control"
                                 value={viewItem?.created_at ? new Date(viewItem.created_at).toLocaleDateString() : ''}
                                 readOnly
                               />
                             </div> */}
                      </div>
                      <div className="col-md-6">
                        <div className="mb-3">
                          <label className="form-label">Service Name</label>
                          <input
                            type="text"
                            className="form-control"
                            value={viewItem?.serviceName || viewItem?.service || viewItem?.service_name || viewItem?.name || ''}
                            readOnly
                          />
                        </div>
                        <div className="mb-3">
                          <label className="form-label">Price</label>
                          <input
                            type="text"
                            className="form-control"
                            value={viewItem?.price || 'N/A'}
                            readOnly
                          />
                        </div>
                        {/* <div className="mb-3">
                               <label className="form-label">Status</label>
                               <input
                                 type="text"
                                 className="form-control"
                                 value="Active"
                                 readOnly
                               />
                             </div> */}
                        {/* <div className="mb-3">
                               <label className="form-label">Type</label>
                               <input
                                 type="text"
                                 className="form-control"
                                 value="Lab Service"
                                 readOnly
                               />
                             </div> */}
                      </div>
                    </div>
                  </form>
                </div>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn borderBtn"
                  onClick={() => setViewModalOpen(false)}
                >
                  Close
                </button>

              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

