import { useEffect, useState } from "react";
import image1 from "../assests/appointment.jpg";
import image2 from "../assests/patients_files.jpg";
import image3 from "../assests/medicals.jpg";
import image4 from "../assests/pharmacy.jpg";
import image5 from "../assests/dashboard.jpg";
import image6 from "../assests/lab.jpg";
import image7 from "../assests/insurance.jpg";
import image8 from "../assests/payments.jpg";
import image9 from "../assests/reports_new.jpg";
import { baseurl } from "../Baseurl";
import axios from "axios";


import { NavLink, useNavigate } from "react-router-dom";
import dash from "../../src/assests/sideImg/HOME-DASH.png";
import appoint from "../../src/assests/sideImg/appointments.png";
import bill from "../../src/assests/sideImg/billing.png";
import lab from "../../src/assests/sideImg/labs.png";
import pharmacy from "../../src/assests/sideImg/pharmacy.png";
import medical from "../../src/assests/sideImg/medicals.png";
import file from "../../src/assests/sideImg/files.png";
import insurance from "../../src/assests/sideImg/insurance.png";
import repIcon from "../../src/assests/sideImg/reports.png";
import { addDisabledStateToMenu } from "../utils/permissions";


const Homepage = () => {
  const navigate = useNavigate();
  const [appointments, setAppointments] = useState([]);
  const [appointments1, setAppointments1] = useState({});
  const [cardsWithPermissions, setCardsWithPermissions] = useState([]);

  const cards = [
    {
      title: `${appointments1.totalAppointments}` + " " + "Appointments",
      subtitle: "New",
      image: image1,
      url: "/Admin/appointment2",
      iconClass: appoint,
    },
    {
      title: `${appointments1.totalPatients}` + " " + "Patients",
      subtitle: " file",
      image: image2,
      url: "/Admin/patient",
      iconClass: file,
    },
    {
      title: "Medical",
      image: image3,
      url: "/Admin/Medicals",
      iconClass: medical,
    },
    {
      title: "Pharmacy",
      image: image4,
      url: "/Admin/Pharmacy",
      iconClass: pharmacy,
    },
    {
      title: "Dashboard",
      image: image5,
      url: "/Admin/dashboard",
      iconClass: dash,
    },
    {
      title: "Laboratory",
      image: image6,
      url: "/Admin/ManageLabs",
      iconClass: lab,
    },
    {
      title: "Insurance",
      image: image7,
      url: "/Admin/Insurance",
      iconClass: insurance,
    },
    {
      title: "Billing",
      image: image8,
      url: "/Admin/Billing",
      iconClass: bill,
    },
    {
      title: "Reports",
      image: image9,
      url: "/Admin/ReportsInc",
      iconClass: repIcon,
    },
    {
      title: "Barcode Scanner",
      image: image4,
      url: "/Admin/BarcodeScanner",
      iconClass: pharmacy,
    },
  ];

  const getUpComingAppointments1 = async () => {
    try {
      const response = await axios.get(`${baseurl}Homepage/total_counts`);
      if (response.data.success === true) {
        setAppointments1(response.data.data);
      }
    } catch (error) {
      console.log("API Error:", error.response?.data || error.message);
    }
  };

  useEffect(() => {
    getUpComingAppointments1();
  }, []);

  const getUpComingAppointments = async () => {
    try {
      const response = await axios.get(`${baseurl}getUpcomingAppointment`);
      if (response.data.success === true) {
        setAppointments(response.data.data);
      }
    } catch (error) {
      console.log("API Error:", error.response?.data || error.message);
    }
  };

  useEffect(() => {
    getUpComingAppointments();
  }, []);



  // ADD THIS ENTIRE useEffect
  useEffect(() => {
    const loadCardPermissions = async () => {
      const cardsWithState = await addDisabledStateToMenu(cards);
      setCardsWithPermissions(cardsWithState);
      console.log("Cards with permissions loaded:", cardsWithState);
    };

    if (cards.length > 0) {
      loadCardPermissions();
    }
  }, [appointments1]);

  useEffect(() => {
    getUpComingAppointments();
  }, []);

  const renderCard = (card) => {
    const isDisabled = card.disabled;

    const handleClick = (e) => {
      if (isDisabled) {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }
    };

    const content = (
      <div
        className={`border-0 shadow-lg rounded-4 overflow-hidden hover-shadow cardDesign ${isDisabled ? 'disabled-card' : ''}`}
        style={{
          opacity: isDisabled ? 0.5 : 1,
          cursor: isDisabled ? 'not-allowed' : 'pointer'
        }}
      >
        {card.image && (
          <div className="homeImg">
            <img src={card.image} className="card-img-top" alt={card.title} />
          </div>
        )}
        <div className="card-body">
          {card.iconClass && (
            <div>
              <span className="hmIcon">
                <img src={card.iconClass} alt="" />
              </span>
            </div>
          )}
          <div>
            <h5 className="card-title fw-bold">
              {card.title.replace(/\d+/g, "").trim()}
            </h5>

            {card.title.match(/\d+/) && (
              <div className="homeNum">
                ({card.title.match(/\d+/)[0]}) {card.subtitle}
              </div>
            )}
          </div>
        </div>
      </div>
    );

    return card.url ? (
      <NavLink
        to={card.url}
        onClick={handleClick}
        className="text-decoration-none text-dark cardDesign"
        style={{
          pointerEvents: isDisabled ? 'none' : 'auto',
          cursor: isDisabled ? 'not-allowed' : 'pointer'
        }}
      >
        {content}
      </NavLink>
    ) : (
      content
    );
  };




  return (
    <section className="homeVideo">
      <video autoPlay muted loop playsInline>
        <source src="/homeVideo.mp4" type="video/mp4" />
      </video>

      <div className="videoSet">
        <div className="container">
          <div className="homeCenter">
            <div>
              <div className="row  homeRow">
                <div className="col-lg-8">
                  <div className="row ">
                    {cardsWithPermissions.slice(0, 2).map((card, index) => (
                      <div
                        className="col-md-6 col-sm-6 bottomHomeSpace pt-lg-0"
                        key={index}
                      >
                        {renderCard(card)}
                      </div>
                    ))}
                  </div>
                  <div className="row medicalHome">
                    {cardsWithPermissions.slice(2, 5).map((card, index) => (
                      <div
                        className="col-md-4 col-sm-4 bottomHomeSpace"
                        key={index + 2}
                      >
                        {renderCard(card)}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="col-lg-4 bottomHomeSpace pt-lg-0">
                  <div className="row h-100">
                    <div className="col-lg-12">
                      <div className="card upcomingAppointments shadow-lg rounded-4 p-3">
                        <h5
                          className="fw-bold mb-3 rounded"
                          style={{ background: "#e85c09" }}
                        >
                          Today's Appointments
                        </h5>
                        <div
                          style={{ maxHeight: "420px", overflowY: "auto" }}
                          className="scrollable-appointments"
                        >
                          {appointments && appointments.length > 0 ? (
                            appointments.map((item, index) => {
                              return (
                                <div
                                  key={index}
                                  className="mb-3 border-bottom pb-2 px-3"
                                  style={{ backgroundColor: "#f8f9fa" }}
                                >
                                  <strong>{item.displayName}</strong>
                                  <br />
                                  <div className="d-flex justify-content-between">
                                    <div>
                                      <span style={{ fontSize: "14px" }}>
                                        {item.patientName}
                                      </span>
                                    </div>
                                    <div>
                                      <span
                                        className="text-muted"
                                        style={{ fontSize: "14px" }}
                                      >
                                        {new Date(
                                          item.appointmentDate
                                        ).toLocaleDateString("en-GB")}{" "}
                                        |{" "}
                                        {new Date(
                                          `1970-01-01T${item.startTime}`
                                        ).toLocaleTimeString("en-US", {
                                          hour: "2-digit",
                                          minute: "2-digit",
                                          hour12: true,
                                        })}{" "}
                                        /{" "}
                                        {new Date(
                                          `1970-01-01T${item.endTime}`
                                        ).toLocaleTimeString("en-US", {
                                          hour: "2-digit",
                                          minute: "2-digit",
                                          hour12: true,
                                        })}
                                      </span>
                                    </div>
                                  </div>
                                </div>
                              );
                            })
                          ) : (
                            <div className="text-center text-muted py-3">
                              No Appointment Today
                            </div>
                          )}
                        </div>
                        <div className="text-end mt-2">
                          <button
                            className="btn commonBtn"
                            onClick={() => navigate("/Admin/appointment2")}
                          >
                            View All
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
              <div className="row ">
                {cardsWithPermissions.slice(5, 9).map((card, index) => (
                  <div
                    className=" col-sm-6 col-md-4 col-lg-3 bottomHomeSpace pb-lg-0 mb-lg-0"
                    key={index + 5}
                  >
                    {renderCard(card)}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Homepage;
