import React, { useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import Swal from "sweetalert2";
import { baseurl } from "../../Baseurl";
export default function CompanyClaims() {
  const navigate = useNavigate();
  const { companyId } = useParams();
  const { state } = useLocation();
  const companyFromState = state?.company;
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const [claims, setClaims] = useState([]);
  const [search, setSearch] = useState("");
  const [companyName, setCompanyName] = useState(companyFromState?.companyName || "");
  const fetchClaimsForCompany = async () => {
    try {
      setLoading(true);
      setError(false);
      console.log('Fetching claims for company ID:', companyId);
      console.log('Company from state:', companyFromState);
      let rows = [];
      try {
        const resp = await fetch(`${baseurl}getClaimsByCompanyId/${companyId}`);
        if (!resp.ok) {
          console.warn(`API call failed with status ${resp.status}: ${resp.statusText}`);
          throw new Error(`API call failed: ${resp.status}`);
        }
        const data = await resp.json();
        console.log('API Response from getClaimsByCompanyId:', data); 
        if (data && (Array.isArray(data.data) || Array.isArray(data))) {
          rows = Array.isArray(data.data) ? data.data : data;
          console.log('Extracted rows:', rows); 
        }
      } catch (error) {
        console.warn('Primary API call failed, trying fallback:', error.message);
      }
      if (!rows || rows.length === 0) {
        console.log('No claims found from primary API, trying fallback...');
        try {
          const r = await fetch(`${baseurl}getAllInsuranceClaims`);
          const d = await r.json();
          const all = Array.isArray(d?.data) ? d.data : Array.isArray(d) ? d : [];
          console.log('All claims from fallback:', all.length);
          rows = all.filter(c => {
            const companyMatch = String(c.company_id) === String(companyId) || 
                               String(c.company) === String(companyId) ||
                               (companyFromState?.companyName && String(c.company_name) === String(companyFromState.companyName));
            console.log('Checking claim:', c, 'companyMatch:', companyMatch);
            return companyMatch;
          });
          console.log('Filtered claims for company:', rows.length);
          if (!companyName && rows.length > 0) {
            setCompanyName(rows[0].company_name || rows[0].company || companyFromState?.companyName || "");
          }
        } catch (fallbackError) {
          console.error('Fallback API call also failed:', fallbackError);
        }
      }
      const normalized = (rows || []).map(c => {
        console.log('Raw claim data:', c); // Debug log
        return {
          id: c.id, // Use the main id field for API calls (should be 6)
          claim_id: c.claim_id, // Keep claim_id for reference (should be 28)
          claim_no: c.claim_number || c.claim_no || c.claimId,
          date: c.created_at || c.date,
          patient_name: c.patient_name || c.patientName,
          policy_number: c.policy_number || c.policyId,
          amount: Number(c.insurance_amount ?? c.amount ?? 0),
          status: (c.status || 'pending').toLowerCase()
        };
      });
      setClaims(normalized);
    } catch (e) {
      console.error('Error loading company claims:', e);
      setError(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchClaimsForCompany();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [companyId]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return claims;
    return claims.filter(c =>
      (c.claim_no && String(c.claim_no).toLowerCase().includes(q)) ||
      (c.patient_name && c.patient_name.toLowerCase().includes(q)) ||
      (c.policy_number && String(c.policy_number).toLowerCase().includes(q))
    );
  }, [search, claims]);

  const updateClaimStatus = async (claimId, newStatus) => {
    console.log('Updating status for claimId:', claimId, 'newStatus:', newStatus); // Debug log
    try {
      const url = `${baseurl}updateInsuranceClaimStatus/${claimId}`;
      console.log('API URL:', url); // Debug log
      const resp = await fetch(url, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus })
      });
      const data = await resp.json();
      console.log('API Response:', data); // Debug log
      if (data && data.success) {
        setClaims(prev => prev.map(c => c.id === claimId ? { ...c, status: newStatus.toLowerCase() } : c));
        Swal.fire('Success', 'Status updated successfully', 'success');
      } else {
        Swal.fire('Error', data.message || 'Failed to update status', 'error');
      }
    } catch (e) {
      console.error('Update claim status error:', e);
      Swal.fire('Error', 'Server error while updating status', 'error');
    }
  };

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="col-12">
          <div className="col-12 searchParent">
            <h5 className="" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span
                style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                onClick={() => navigate(-1)}
                title="Back"
              >
                &larr;
              </span>
              Company Claims: {companyName || companyFromState?.companyName || `#${companyId}`}
            </h5>
          </div>

          <div className="card table-card">
            <div className="card-header">
              <div className="d-sm-flex align-items-center justify-content-between">
                <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                  <i
                    className="ti ti-search"
                    style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", zIndex: 2, color: "#6c757d", fontSize: "16px" }}
                  ></i>
                  <input
                    type="text"
                    className="form-control"
                    placeholder="Search by claim, patient, policy"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    style={{ paddingLeft: "40px" }}
                  />
                </div>
              </div>
            </div>

            <div className="card-body pt-3">
              {loading && <div className="text-center my-4">Loading...</div>}
              {error && !loading && <div className="text-center text-danger my-4">Failed to load data</div>}
              {!loading && !error && (
                <div className="table-responsive">
                  <table className="table" id="pc-dt-simple">
                    <thead>
                      <tr>
                        <th>Claim ID</th>
                        <th>Date</th>
                        <th>Patient</th>
                        <th>Policy #</th>
                        <th>Ins Amount</th>
                        <th>Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filtered.length === 0 ? (
                        <tr>
                          <td colSpan="6" className="text-center text-muted">No claims found</td>
                        </tr>
                      ) : (
                        filtered.map((row) => (
                          <tr key={row.id}>
                            <td>{row.claim_no || `C${String(row.claim_id || row.id).padStart(5, '0')}`}</td>
                            <td>{row.date ? new Date(row.date).toLocaleDateString("en-GB") : "-"}</td>
                            <td>{row.patient_name || "-"}</td>
                            <td>{row.policy_number || "-"}</td>
                            <td>{row.amount != null ? `${row.amount} BHD` : "-"}</td>
                            <td>
                              <select
                                id={`status-select-${row.id}`}
                                className="form-select form-select-sm border-primary shadow-sm px-1 py-0"
                                style={{ minWidth: 90, fontWeight: 500, fontSize: '0.85em', height: '1.8em', backgroundColor: '#f8f9fa' }}
                                value={row.status || 'pending'}
                                title="Change status"
                                disabled={row.status === 'accepted'}
                                onChange={async (e) => {
                                  const newStatus = e.target.value;
                                  console.log('Dropdown change - row.id:', row.id, 'row.claim_id:', row.claim_id); // Debug log
                                  await updateClaimStatus(row.id, newStatus);
                                }}
                              >
                                <option value="pending" disabled={row.status === 'pending'}>
                                  Pending
                                </option>
                                <option value="accepted" disabled={row.status === 'accepted'}>
                                  Accepted
                                </option>
                                <option value="rejected" disabled={row.status === 'rejected'}>
                                  Rejected
                                </option>
                              </select>
                            </td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}


