import { useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import { fetchModuleMappings, hasSubModulePermission, isAdmin } from "../../utils/permissions";

const Medical = () => {
  const navigate = useNavigate();

  const [permissions, setPermissions] = useState({
    icd10List: false,
    diagnosisList: false,
    serviceCategory: false,
    allergy: false,
    chronicIllness: false,
    chiefComplaint: false,
    historyOfPastIllness: false,
    historyOfPresentIllness: false,
    examinationGeneral: false,
    examinationLocal: false,
    examinationSystemic: false,
    advises: false,
    extraNotes: false,
    treatmentPlan: false,
    familyHistory: false,
    psychosocial: false
  });

  useEffect(() => {
    const checkPermissions = async () => {
      if (isAdmin()) {
        setPermissions({
          icd10List: true,
          diagnosisList: true,
          serviceCategory: true,
          allergy: true,
          chronicIllness: true,
          chiefComplaint: true,
          historyOfPastIllness: true,
          historyOfPresentIllness: true,
          examinationGeneral: true,
          examinationLocal: true,
          examinationSystemic: true,
          advises: true,
          extraNotes: true,
          treatmentPlan: true,
          familyHistory: true,
          psychosocial: true
        });
        return;
      }

      try {
        const allModules = await fetchModuleMappings();
        const medicalModule = allModules.find(m => m.module_name.toLowerCase() === 'medicals');

        if (medicalModule && medicalModule.sub_modules) {
          const subModules = medicalModule.sub_modules;

          console.log('Medical submodules found:', subModules);

          setPermissions({
            icd10List: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'icd_10_list')?.id),
            diagnosisList: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'diagnosis_list')?.id),
            serviceCategory: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'service_category')?.id),
            allergy: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'allergy')?.id),
            chronicIllness: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'chronic_illness')?.id),
            chiefComplaint: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'chief_complaint')?.id),
            historyOfPastIllness: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'history_of_past_illness')?.id),
            historyOfPresentIllness: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'history_of_present_illness')?.id),
            examinationGeneral: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'examination_general')?.id),
            examinationLocal: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'examination_local')?.id),
            examinationSystemic: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'examination_systematic')?.id),
            advises: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'advises')?.id),
            extraNotes: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'extra_notes')?.id),
            treatmentPlan: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'treatment_plan')?.id),
            familyHistory: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'family_history')?.id),
            psychosocial: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'psychosocial')?.id)
          });
        }
      } catch (err) {
        console.error("Error checking permissions", err);
      }
    };

    checkPermissions();
  }, []);

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="pt-4">
          <div className="row g-5">
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.icd10List) navigate("/Admin/ICDlist");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.icd10List}>
                <div className="settingIocn">
                  <i className="fas fa-business-time"></i>
                </div>
                <h5>ICD 10 List</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.diagnosisList) navigate("/Admin/ICDstandardlist");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.diagnosisList}>
                <div className="settingIocn">
                  <i className="fas fa-business-time"></i>
                </div>
                <h5>Diagnosis List</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.serviceCategory) navigate("/Admin/ServiceCategory");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.serviceCategory}>
                <div className="settingIocn">
                  <i className="fas fa-wallet"></i>
                </div>
                <h5>Service Category</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.allergy) navigate("/Admin/Allergy");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.allergy}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Allergy</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.chronicIllness) navigate("/Admin/Chronicillness");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.chronicIllness}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Chronic Illness</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.chiefComplaint) navigate("/Admin/chiefComplaint");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.chiefComplaint}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Chief Complaint</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.historyOfPastIllness) navigate("/Admin/historyodpastillenss");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.historyOfPastIllness}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>History of Past Illness</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.historyOfPresentIllness) navigate("/Admin/historyodpresentillness");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.historyOfPresentIllness}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>History of Present Illness</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.examinationGeneral) navigate("/Admin/examinationgeneral");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.examinationGeneral}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Examination General</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.examinationLocal) navigate("/Admin/examinationlocal");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.examinationLocal}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Examination Local</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.examinationSystemic) navigate("/Admin/examinationsymetic");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.examinationSystemic}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Examination Systemic</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.advises) navigate("/Admin/Advice");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.advises}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Advises </h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.extraNotes) navigate("/Admin/Extranotes");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.extraNotes}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Extra Notes</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.treatmentPlan) navigate("/Admin/treatmentplan");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.treatmentPlan}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Treatment Plan</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.familyHistory) navigate("/Admin/FamilyHistory");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.familyHistory}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Family History</h5>
              </button>
            </div>
            <div
              className="col-lg-3"
              onClick={() => {
                if (permissions.psychosocial) navigate("/Admin/Physocial");
              }}
            >
              <button className="settingCard w-100" disabled={!permissions.psychosocial}>
                <div className="settingIocn">
                  <i className="fas fa-bell"></i>
                </div>
                <h5>Psychosocial </h5>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
export default Medical;
