import React, { useState, useEffect, useMemo } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import { baseurl } from "../../Baseurl";
import EventBus from "../../Context/EventBus";
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";

import Select from "react-select";
import { fetchModuleMappings, hasSubModulePermission, isAdmin } from "../../utils/permissions";

export default function Billing() {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const user = useSelector((state) => state.user.user);
  const [openmodal, setOpenmodal] = useState(false);
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);

  // New-invoice modal state
  const [patients, setPatients] = useState([]);
  const [selectedPatientId, setSelectedPatientId] = useState("");
  const [services, setServices] = useState([]);
  const [inventory, setInventory] = useState([]);
  const [selected, setSelected] = useState({ services: {}, inventory: {} });
  const [servicesLoading, setServicesLoading] = useState(false);
  const [inventoryLoading, setInventoryLoading] = useState(false);
  const [invoicePage, setInvoicePage] = useState(1);
  const itemsPerPage = 10;
  // Payments tab + state
  const [activeTab, setActiveTab] = useState("invoices");
  const [payments, setPayments] = useState([]);
  const [paymentsLoading, setPaymentsLoading] = useState(false);
  const [paymentPage, setPaymentPage] = useState(1);
  const [paySearch, setPaySearch] = useState("");

  const [permissions, setPermissions] = useState({
    invoices: false,
    paymentInvoices: false
  });

  useEffect(() => {
    const checkPermissions = async () => {
      if (isAdmin()) {
        setPermissions({ invoices: true, paymentInvoices: true });
        return;
      }

      try {
        const allModules = await fetchModuleMappings();
        const billingModule = allModules.find(m => m.module_name.toLowerCase() === 'billing');

        if (billingModule && billingModule.sub_modules) {
          const invoicesSub = billingModule.sub_modules.find(sm => sm.sub_module_name === 'Invoices');
          const paymentInvoicesSub = billingModule.sub_modules.find(sm => sm.sub_module_name === 'Payment_Invoices');

          console.log('Billing submodules found:', { invoicesSub, paymentInvoicesSub });

          setPermissions({
            invoices: invoicesSub ? hasSubModulePermission(invoicesSub.id) : false,
            paymentInvoices: paymentInvoicesSub ? hasSubModulePermission(paymentInvoicesSub.id) : false
          });
        }
      } catch (err) {
        console.error("Error checking permissions", err);
      }
    };

    checkPermissions();
  }, []);

  // Insurance company modal state
  const [insOpen, setInsOpen] = useState(false);
  const [insLoading, setInsLoading] = useState(false);
  const [insForm, setInsForm] = useState({
    company_name: "",
    address: "",
    phone_number: "",
    email: "",
    website: "",
    company_logo: null,
  });
  const [insListOpen, setInsListOpen] = useState(false);
  const [insListLoading, setInsListLoading] = useState(false);
  const [insuranceCompanies, setInsuranceCompanies] = useState([]);

  // Payment modal state (for Payments tab)
  const [payOpen, setPayOpen] = useState(false);
  const [payLoading, setPayLoading] = useState(false);
  const [payPatientId, setPayPatientId] = useState("");
  const [remainingInvoices, setRemainingInvoices] = useState([]);
  const [paymentMethods, setPaymentMethods] = useState([]);
  const [payForm, setPayForm] = useState({
    invoice_id: "",
    amount: "",
    payment_method: "",
    transaction_id: "",
  });

  // Searchable Patient dropdown helpers 
  const patientOptions = patients.map((p) => ({
    value: String(p.id),
    label: `${(p.firstName || "").trim()} ${(p.lastName || "").trim()}`.trim(),
    mobileNumber: p.phone || p.mobileNumber || "",
    civilIdNumber: p.civilIdNumber || p.patient_civil_id || "",
    email: p.email || "",
    age: p.age || "",
  }));

  const customFilterOption = (option, inputValue) => {
    const searchValue = (inputValue || "").toLowerCase();
    const data = option.data || {};
    return (
      (data.label || "").toLowerCase().includes(searchValue) ||
      (data.mobileNumber || "").toLowerCase().includes(searchValue) ||
      (data.civilIdNumber || "").toLowerCase().includes(searchValue) ||
      (data.email || "").toLowerCase().includes(searchValue) ||
      String(data.age || "").toLowerCase().includes(searchValue)
    );
  };

  // Load invoices from API
  useEffect(() => {
    loadInvoices();
    loadPayments();
    loadPaymentMethods();
  }, []);

  const loadInvoices = async () => {
    try {
      setLoading(true);
      const res = await axios.get(`${baseurl}getAllInvoices`);
      const list = Array.isArray(res.data?.data)
        ? res.data.data
        : Array.isArray(res.data)
          ? res.data
          : [];
      setInvoices(list);
    } catch (error) {
      console.error("Error loading invoices:", error);

      setInvoices([
        {
          id: "INV32",
          patient_name: "JoyBay",
          phone: "123123",
          services: "S32-S44-555",
          total_amount: 300,
          discount: 50,
          vat: 35,
          paid_amount: 0,
          remaining_amount: 385,
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const loadPayments = async () => {
    try {
      setPaymentsLoading(true);
      const res = await axios.get(`${baseurl}getAllPayments`);
      const list = Array.isArray(res.data?.data)
        ? res.data.data
        : Array.isArray(res.data)
          ? res.data
          : [];
      setPayments(list);
    } catch (error) {
      console.error("Error loading payments:", error);
      setPayments([]);
    } finally {
      setPaymentsLoading(false);
    }
  };

  const loadPaymentMethods = async () => {
    try {
      const res = await axios.get(`${baseurl}getAllPaymentMethods`);
      const list = Array.isArray(res.data?.data)
        ? res.data.data
        : Array.isArray(res.data)
          ? res.data
          : [];
      setPaymentMethods(list);
      // Set default payment method to first one if available
      if (list.length > 0) {
        setPayForm(prev => ({ ...prev, payment_method: list[0].name }));
      }
    } catch (error) {
      console.error("Error loading payment methods:", error);
      // Fallback to default methods
      setPaymentMethods([
        { id: 1, name: "Cash" },
        { id: 2, name: "Card" },
        { id: 3, name: "Transfer" },
        { id: 4, name: "Cheque" }
      ]);
      setPayForm(prev => ({ ...prev, payment_method: "Cash" }));
    }
  };

  // Get logged-in user name from Redux
  const getLoggedInUserName = () => {
    return user?.fullName || user?.shortName || user?.name || user?.username || 'User';
  };

  // Open/close payment modal
  const openPaymentModal = async () => {
    setPayOpen(true);
    if (!patients.length) {
      await loadPatients();
    }
    setPayPatientId("");
    setRemainingInvoices([]);
    setPayForm({
      invoice_id: "",
      amount: "",
      payment_method: paymentMethods.length > 0 ? paymentMethods[0].name : "Cash",
      transaction_id: "",
    });
  };

  const closePaymentModal = () => {
    setPayOpen(false);
  };


  const loadRemainingInvoicesByPatient = async (patientId) => {
    if (!patientId) {
      setRemainingInvoices([]);
      return;
    }
    try {
      const res = await axios.get(
        `${baseurl}getRemainingInvoices/${patientId}`
      );
      const list = Array.isArray(res.data?.invoices)
        ? res.data.invoices
        : Array.isArray(res.data?.data)
          ? res.data.data
          : Array.isArray(res.data)
            ? res.data
            : [];
      setRemainingInvoices(list);
    } catch (_) {
      setRemainingInvoices([]);
    }
  };

  const handlePayPatientChange = async (e) => {
    const pid = e.target.value;
    setPayPatientId(pid);
    setPayForm((prev) => ({ ...prev, invoice_id: "", amount: "" }));
    await loadRemainingInvoicesByPatient(pid);
  };

  const handlePayPatientChangeSelect = async (selectedOption) => {
    const pid = selectedOption ? selectedOption.value : "";
    setPayPatientId(pid);
    setPayForm((prev) => ({ ...prev, invoice_id: "", amount: "" }));
    await loadRemainingInvoicesByPatient(pid);
  };

  const handlePayInvoiceSelect = (e) => {
    const idStr = e.target.value;
    const idNum = Number(idStr);
    const inv = remainingInvoices.find(
      (x) =>
        Number(x.invoiceId || x.invoice_id || x.id || x.invoiceid) === idNum ||
        (x.invoice_no || x.invoiceNo) === idStr
    );
    const remaining =
      inv?.remaining_amount ?? inv?.remaining ?? inv?.remainingAmount ?? "";
    setPayForm((prev) => ({
      ...prev,
      invoice_id: idStr,
      amount: remaining !== "" ? String(remaining) : prev.amount,
    }));
  };

  const submitPayment = async () => {
    if (!payPatientId) {
      Swal.fire("Patient required", "Please select a patient", "info");
      return;
    }
    if (!payForm.invoice_id || !payForm.amount) {
      Swal.fire("Missing", "Invoice and amount are required", "info");
      return;
    }
    try {
      setPayLoading(true);
      const payload = {
        invoice_id: Number(payForm.invoice_id),
        amount: Number(payForm.amount),
        payment_method: payForm.payment_method,
        transaction_id: payForm.transaction_id || undefined,
      };
      await axios.post(`${baseurl}addPaymentInvoice`, payload);
      Swal.fire("Success", "Payment recorded successfully", "success");
      setPayOpen(false);
      setPayForm({
        invoice_id: "",
        amount: "",
        payment_method: "Cash",
        transaction_id: "",
      });
      setPayPatientId("");
      setRemainingInvoices([]);
      await Promise.all([loadInvoices(), loadPayments()]);
    } catch (e) {
      const msg = e.response?.data?.message || "Failed to add payment";
      Swal.fire("Error", msg, "error");
    } finally {
      setPayLoading(false);
    }
  };

  const handleclick = async () => {
    setOpenmodal(true);
    if (!patients.length) {
      await loadPatients();
    }
  };

  const handleclose = () => {
    setOpenmodal(false);
    setSelectedPatientId("");
    setServices([]);
    setInventory([]);
    setSelected({ services: {}, inventory: {} });
    setServicesLoading(false);
    setInventoryLoading(false);
  };


  const openInsModal = () => setInsOpen(true);
  const closeInsModal = () => setInsOpen(false);
  const openInsListModal = async () => {
    setInsListOpen(true);
    await loadInsuranceCompanies();
  };
  const closeInsListModal = () => setInsListOpen(false);
  const loadInsuranceCompanies = async () => {
    try {
      setInsListLoading(true);
      const res = await axios.get(`${baseurl}getAllInsuranceCompanies`);
      const list = Array.isArray(res.data?.data)
        ? res.data.data
        : Array.isArray(res.data)
          ? res.data
          : [];
      setInsuranceCompanies(list);
    } catch (_) {
      setInsuranceCompanies([]);
    } finally {
      setInsListLoading(false);
    }
  };
  const handleInsChange = (e) => {
    const { name, value } = e.target;
    setInsForm((prev) => ({ ...prev, [name]: value }));
  };
  const handleInsFile = (e) => {
    const file = e.target.files?.[0] || null;
    setInsForm((prev) => ({ ...prev, company_logo: file }));
  };
  const submitInsurance = async () => {
    if (!insForm.company_name) {
      Swal.fire("Required", "Company name is required", "info");
      return;
    }
    try {
      setInsLoading(true);
      const fd = new FormData();
      fd.append("company_name", insForm.company_name);
      fd.append("address", insForm.address);
      fd.append("phone_number", insForm.phone_number);
      fd.append("email", insForm.email);
      fd.append("website", insForm.website);
      if (insForm.company_logo) fd.append("company_logo", insForm.company_logo);
      console.log("InsuranceCompany payload", Array.from(fd.entries()));
      // Log the form-data entries for debugging
      // Note: logging FormData directly won't show contents in console
      try { console.log("InsuranceCompany payload", Array.from(fd.entries())); } catch (_) { }
      const res = await axios.post(`${baseurl}createInsuranceCompany`, fd);
      const ok = res?.data?.success === true || res?.status < 400;
      Swal.fire(
        ok ? "Success" : "Notice",
        ok ? "Insurance company created successfully" : (res?.data?.message || "Request completed"),
        ok ? "success" : "info"
      );
      setInsOpen(false);
      if (insListOpen) {
        await loadInsuranceCompanies();
      }
      setInsForm({
        company_name: "",
        address: "",
        phone_number: "",
        email: "",
        website: "",
        company_logo: null,
      });
    } catch (e) {
      const msg = e.response?.data?.message || e.message || "Failed to create company";
      console.error("createInsuranceCompany error", e);
      Swal.fire("Error", msg, "error");
    } finally {
      setInsLoading(false);
    }
  };

  const loadPatients = async () => {
    try {
      const res = await axios.get(`${baseurl}getActivePatients`);
      const list = Array.isArray(res.data?.data)
        ? res.data.data
        : Array.isArray(res.data)
          ? res.data
          : [];
      setPatients(list);
    } catch (_) {
      setPatients([]);
    }
  };

  const loadBillables = async (patientId) => {
    if (!patientId) return;
    try {
      setServicesLoading(true);
      setInventoryLoading(true);

      // fetch services
      axios
        .get(`${baseurl}getPatientServicesByPatientId/${patientId}`)
        .then((sRes) => {
          const rawServices = Array.isArray(sRes.data?.data)
            ? sRes.data.data
            : Array.isArray(sRes.data)
              ? sRes.data
              : Array.isArray(sRes.data?.data?.results)
                ? sRes.data.data.results
                : [];

          const eligibleServices = rawServices
            .map((x) => ({
              id: x.id || x.serviceId,
              name: x.name || x.serviceName,
              totalPrice:
                x.totalPrice ??
                x.total_price ??
                x.total ??
                Number(x.price || 0),
              status: (x.status || x.Status || "").toString().toLowerCase(),
              billed:
                x.billed ??
                x.isBilled ??
                x.is_billed ??
                ((x.billing_status || "").toString().toLowerCase() === "billed"
                  ? 1
                  : 0),
            }))
            .filter((x) => x.status === "complete" && String(x.billed) !== "1");

          setServices(eligibleServices);
        })
        .catch(() => setServices([]))
        .finally(() => setServicesLoading(false));


      axios
        .get(`${baseurl}getPatientPharmacyByPatientId/${patientId}`)
        .then((iRes) => {
          const rawInventory = (
            Array.isArray(iRes.data?.data)
              ? iRes.data.data
              : Array.isArray(iRes.data)
                ? iRes.data
                : []
          ).map((x) => ({
            id: x.id || x.itemId || x.pharmacyId,
            name: x.name,
            totalPrice:
              x.totalPrice ??
              x.total_price ??
              x.total ??
              Number(x.price || x.unitPrice || 0) * Number(x.quantity || 1),
            billed:
              x.billed ??
              x.isBilled ??
              x.is_billed ??
              ((x.billing_status || "").toString().toLowerCase() === "billed"
                ? 1
                : 0),
          }));

          const notBilledInventory = rawInventory.filter(
            (x) => String(x.billed) !== "1"
          );

          setInventory(notBilledInventory);
        })
        .catch(() => setInventory([]))
        .finally(() => setInventoryLoading(false));

      setSelected({ services: {}, inventory: {} });
    } catch (_) {
      setServices([]);
      setInventory([]);
      setServicesLoading(false);
      setInventoryLoading(false);
    }
  };

  const handlePatientChange = async (e) => {
    const pid = e.target.value;
    setSelectedPatientId(pid);
    await loadBillables(pid);
  };

  const handlePatientChangeSelect = async (selectedOption) => {
    const pid = selectedOption ? selectedOption.value : "";
    setSelectedPatientId(pid);
    await loadBillables(pid);
  };

  const toggleSelect = (type, id) => {
    setSelected((prev) => ({
      ...prev,
      [type]: { ...prev[type], [id]: !prev[type][id] },
    }));
  };

  const chosenServices = services.filter((x) => selected.services[x.id]);
  const chosenInventory = inventory.filter((x) => selected.inventory[x.id]);
  const totalAmount = [...chosenServices, ...chosenInventory].reduce(
    (sum, x) => sum + Number(x.totalPrice || 0),
    0
  );

  const filterSearch = useMemo(() => {
    const q = search.toLowerCase();
    let rows = invoices || [];

    if (!q) return rows;
    return rows.filter((row) => {
      return (
        (row.invoice_no && row.invoice_no.toLowerCase().includes(q)) ||
        (row.patient_name && row.patient_name.toLowerCase().includes(q))
      );
    });
  }, [search, invoices]);


  // Invoices pagination
  const totalPagesInvoices = Math.max(
    1,
    Math.ceil(filterSearch.length / itemsPerPage)
  );

  const paginatedInvoices = filterSearch.slice(
    (invoicePage - 1) * itemsPerPage,
    invoicePage * itemsPerPage
  );

  // Payments filter + pagination
  const paymentsFiltered = useMemo(() => {
    const q = (paySearch || "").toLowerCase();
    if (!q) return payments;
    return payments.filter((p) => {
      const patient = (p.patient_name || "").toLowerCase();
      const inv = String(p.invoice_no || p.invoice_id || p.invoiceId || "").toLowerCase();
      return patient.includes(q) || inv.includes(q);
    });
  }, [paySearch, payments]);

  const totalPagesPayments = Math.max(
    1,
    Math.ceil(paymentsFiltered.length / itemsPerPage)
  );
  const paginatedPayments = paymentsFiltered.slice(
    (paymentPage - 1) * itemsPerPage,
    paymentPage * itemsPerPage
  );

  const createInvoice = async () => {
    if (!selectedPatientId) {
      Swal.fire("Patient required", "Please select a patient", "info");
      return;
    }
    if (chosenServices.length === 0 && chosenInventory.length === 0) {
      Swal.fire(
        "Select items",
        "Please select at least one service or pharmacy item.",
        "info"
      );
      return;
    }
    try {
      setCreating(true);
      const payload = {
        patientId: Number(selectedPatientId),
        services: chosenServices.map((x) => x.id),
        pharmacy: chosenInventory.map((x) => x.id),
      };
      const res = await axios.post(`${baseurl}createInvoice`, payload);
      const created = res?.data?.data || null;
      Swal.fire(
        "Success",
        `Invoice ${created?.invoice_no || created?.invoiceNo || "created"
        } created successfully`,
        "success"
      );
      handleclose();
      // Notify globally that an invoice was created
      try {
        EventBus.dispatch("invoice:created", { patientId: Number(selectedPatientId), invoice: created });
      } catch (_) { }
      await loadInvoices();
    } catch (e) {
      const msg = e.response?.data?.message || "Failed to create invoice";
      Swal.fire("Error", msg, "error");
    } finally {
      setCreating(false);
    }
  };






  return (
    <div className="pc-container">
      <div className="pc-content ">
        <div className="p-4">
          {/* Header Buttons */}
          <div className="d-flex justify-content-between align-items-center mb-3">
            <div>
              <button
                className={`btn ${activeTab === "invoices"
                  ? "btn-primary"
                  : "btn-outline-primary"
                  } me-2`}
                onClick={() => setActiveTab("invoices")}
                disabled={!permissions.invoices}
              >
                Invoices
              </button>
              <button
                className={`btn ${activeTab === "payments"
                  ? "btn-primary"
                  : "btn-outline-primary"
                  } me-2`}
                onClick={() => setActiveTab("payments")}
                disabled={!permissions.paymentInvoices}
              >
                Payment Invoices
              </button>
              {/* <button className="btn btn-outline-primary" onClick={handleclick}>New Invoice</button> */}
            </div>
            <div>
              {/* <button className="btn btn-outline-primary me-2"> */}
              {/* <i className="bi bi-funnel-fill"></i> */}
              {/* </button> */}
              {/* <button className="btn btn-dark"> */}
              {/* <i className="bi bi-upload"></i> */}
              {/* </button> */}
            </div>
          </div>

          {/* Tabs */}
          {activeTab === "invoices" && (
            <div className="col-12">
              <div className="card table-card">
                <div className="card-header">
                  <div className="d-sm-flex align-items-center justify-content-between">
                    <div>

                      {/* <h5 className="mb-3 mb-sm-0">Invoices</h5> */}
                      <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                        <i
                          className="ti ti-search"
                          style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", zIndex: 2, color: "#6c757d", fontSize: "16px" }}
                        >  </i>

                        <input
                          type="text"
                          className="form-control"
                          placeholder="Search By Patient or Invoice Id"
                          value={search}
                          onChange={(e) => {
                            setSearch(e.target.value);
                            // setCurrentPage(1);
                          }}
                          style={{ paddingLeft: "40px" }}
                        />
                      </div>
                    </div>

                    <div className="d-flex gap-2">
                      {/* <button className="btn btn-outline-secondary" onClick={openInsListModal}>
                        View Insurance Companies
                      </button>
                      <button className="btn btn-outline-secondary" onClick={openInsModal}>
                        Add Insurance Company
                      </button> */}
                      <button className="btn btn-primary" onClick={handleclick}>
                        Create Invoice
                      </button>
                    </div>
                    {/* <div><a href="../admins/course-teacher-apply.html" className="btn btn-outline-secondary">Apply Teacher List</a> <a href="../admins/course-teacher-add.html" className="btn btn-primary">Add Teacher</a></div> */}
                  </div>
                </div>
                <div className="card-body pt-3">
                  <div className="table-responsive">
                    <table className="table table-hover" id="pc-dt-simple">
                      <thead>
                        <tr>
                          <th>Sn</th>
                          <th>ID</th>
                          <th>Date</th>
                          <th>Patient </th>
                          {/* <th>Phone</th> */}
                          <th>Total Services</th>
                          <th>Amount</th>
                          {/* <th>Discount</th> */}
                          {/* <th>VAT</th> */}
                          <th>Paid</th>
                          <th>Remaining Amount</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {loading ? (
                          <tr>
                            <td colSpan="9" className="text-center">
                              <div
                                className="spinner-border text-primary"
                                role="status"
                              >
                                <span className="visually-hidden">
                                  Loading...
                                </span>
                              </div>
                            </td>
                          </tr>
                        ) : invoices.length === 0 ? (
                          <tr>
                            <td colSpan="9" className="text-center text-muted">
                              No invoices found
                            </td>
                          </tr>
                        ) : (
                          paginatedInvoices.map((invoice, index) => (
                            <tr key={invoice.id || index}>
                              <td>
                                {(invoicePage - 1) * itemsPerPage + index + 1}
                              </td>
                              <td>{invoice.invoice_no || invoice.id}</td>
                              <td>
                                {(() => {
                                  const ts =
                                    invoice.invoice_date ||
                                    invoice.updated_at ||
                                    invoice.updatedAt ||
                                    invoice.date;
                                  const d = ts ? new Date(ts) : null;
                                  return d && !isNaN(d.getTime())
                                    ? d.toLocaleDateString("en-GB")
                                    : "-";
                                })()}
                              </td>
                              <td>
                                {invoice.patient_name ||
                                  `${invoice.firstName || ""} ${invoice.lastName || ""
                                    }`.trim()}
                              </td>
                              {/* <td>{invoice.phone || '-'} </td> */}
                              <td>{invoice.total_services || "-"}</td>
                              <td>
                                {Number(invoice.total_amount || 0).toFixed(2)}{" "}
                                BHD
                              </td>
                              {/* <td>{invoice.discount || '0'}</td> */}
                              {/* <td>₹{Number(invoice.vat || 0).toFixed(2)}</td> */}
                              <td>
                                {Number(invoice.paid_amount || 0).toFixed(2)}{" "}
                                BHD
                              </td>
                              <td>
                                {Number(invoice.remaining_amount || 0).toFixed(
                                  2
                                )}{" "}
                                BHD
                              </td>
                              <td>
                                <div
                                  style={{ cursor: "pointer" }}
                                  className="avtar avtar-xs btn-link-secondary viewIcon"
                                  onClick={() =>
                                    navigate(`/Admin/ViewInvoice/${invoice.id || invoice.invoice_id || invoice.invoiceId || invoice.invoice_no}`,
                                      { state: { invoice } }
                                    )
                                  }
                                >
                                  <i className="ti ti-eye f-20" />
                                  {/* <span>View< */}
                                </div>
                                {/* <div className="avtar avtar-xs btn-link-secondary editIcon" style={{ cursor: 'pointer' }}><i className="ti ti-edit f-20" /><span>Edit</span></div>
                              <div className="avtar avtar-xs btn-link-secondary deleteIcon" style={{ cursor: 'pointer' }}><i className="ti ti-trash f-20" /><span>Delete</span></div> */}
                              </td>
                            </tr>
                          ))
                        )}
                      </tbody>
                    </table>
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination
                        currentPage={invoicePage}
                        totalPages={totalPagesInvoices}
                        setCurrentPage={setInvoicePage}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === "payments" && (
            <div className="col-12">
              <div className="card table-card">
                <div className="card-header">
                  <div className="d-sm-flex align-items-center justify-content-between">
                    {/* <h5 className="mb-3 mb-sm-0">Payment Invoices</h5>
                     */}
                    <div>
                      <div style={{ width: "300px", margin: "15px", position: "relative" }}>
                        <i
                          className="ti ti-search"
                          style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", zIndex: 2, color: "#6c757d", fontSize: "16px" }}
                        >
                        </i>

                        <input
                          type="text"
                          className="form-control"
                          placeholder="Search By Patient or Invoice Id"
                          value={paySearch}
                          onChange={(e) => {
                            setPaySearch(e.target.value);
                            setPaymentPage(1);
                          }}
                          style={{ paddingLeft: "40px" }}
                        />
                      </div>
                    </div>

                    <button
                      className="btn btn-primary"
                      onClick={openPaymentModal}
                    >
                      Payment
                    </button>
                  </div>
                </div>
                <div className="card-body pt-3">
                  <div className="table-responsive">
                    <table className="table table-hover">
                      <thead>
                        <tr>
                          <th>Sn</th>
                          <th>Patient</th>
                          <th>Invoice ID</th>
                          <th>Date</th>
                          <th>Amount</th>
                          <th>Method</th>
                          <th>Transaction</th>
                          {/* <th>Status</th> */}
                        </tr>
                      </thead>
                      <tbody>
                        {paymentsLoading ? (
                          <tr>
                            <td colSpan="7" className="text-center">
                              <div
                                className="spinner-border text-primary"
                                role="status"
                              >
                                <span className="visually-hidden">
                                  Loading...
                                </span>
                              </div>
                            </td>
                          </tr>
                        ) : paginatedPayments.length === 0 ? (
                          <tr>
                            <td colSpan="7" className="text-center text-muted">
                              No payments found
                            </td>
                          </tr>
                        ) : (
                          paginatedPayments.map((p, idx) => (
                            <tr key={p.id || idx}>
                              <td>
                                {(paymentPage - 1) * itemsPerPage + idx + 1}
                              </td>
                              <td>{p.patient_name}</td>
                              <td>
                                {p.invoice_no || p.invoice_id || p.invoiceId}
                              </td>
                              <td>
                                {(() => {
                                  const d =
                                    p.payment_date || p.date || p.created_at;
                                  return d
                                    ? new Date(d).toLocaleDateString("en-GB")
                                    : "-";
                                })()}
                              </td>
                              <td>
                                {Number(
                                  p.payment_amount || p.amount || 0
                                ).toFixed(2)}{" "}
                                BHD
                              </td>
                              <td>{p.payment_method || p.method || "-"}</td>
                              <td>
                                {p.transactionId || p.transaction_id || "-"}
                              </td>
                              {/* <td>{p.payment_status || p.status || '-'}</td> */}
                            </tr>
                          ))
                        )}
                      </tbody>
                    </table>
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination
                        currentPage={paymentPage}
                        totalPages={totalPagesPayments}
                        setCurrentPage={setPaymentPage}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
      {openmodal && (
        <div
          className="modal show d-block"
          style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add Invoice</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => handleclose()}
                ></button>
              </div>
              <div className="modal-body">
                {/* Patient selection */}
                <div className="row mb-3">
                  <div className="col-md-6">
                    <label className="form-label">Patient</label>
                    <Select
                      classNamePrefix="react-select"
                      name="patient_id"
                      options={patientOptions}
                      value={
                        patientOptions.find((opt) => opt.value === String(selectedPatientId)) || null
                      }
                      getOptionLabel={(e) => e.label}
                      getOptionValue={(e) => e.value}
                      onChange={handlePatientChangeSelect}
                      placeholder="Search by Name, Email, Mobile, Civil ID or Age"
                      isSearchable={true}
                      filterOption={customFilterOption}
                      menuPortalTarget={document.body}
                      styles={{
                        menuPortal: (base) => ({ ...base, zIndex: 2000 }),
                        menu: (base) => ({ ...base, zIndex: 2000 }),
                      }}
                      noOptionsMessage={() => (patients.length ? "No patients found" : "Loading patients...")}
                    />
                  </div>
                  {/* <div className="col-md-6 d-flex align-items-end"> */}
                  {/* <div className="w-100"> */}
                  {/* <div className="form-control bg-light"> */}
                  {/* <strong>Total:</strong> ₹{Number(totalAmount || 0).toFixed(2)} */}
                  {/* </div> */}
                  {/* </div> */}
                  {/* </div> */}
                </div>

                {/* Billable lists */}
                <div className="row">
                  <div className="col-md-6">
                    <h6>Services</h6>
                    <div
                      className="list-group"
                      style={{ maxHeight: 240, overflowY: "auto" }}
                    >
                      {servicesLoading ? (
                        <div className="list-group-item text-muted">Services loading...</div>
                      ) : services.length === 0 ? (
                        <div className="list-group-item text-muted">No billable services</div>
                      ) : (
                        services.map((s) => (
                          <label
                            key={s.id}
                            className={`list-group-item d-flex align-items-center ${selected.services[s.id] ? '' : ''}`}
                            style={{
                              cursor: 'pointer',
                              transition: 'all 0.2s ease',
                              // border: selected.services[s.id] ? '1px solid #0d6efd' : '1px solid transparent'
                            }}
                          >
                            <input
                              type="checkbox"
                              className="form-check-input me-2"
                              checked={!!selected.services[s.id]}
                              onChange={() => toggleSelect('services', s.id)}
                              style={{
                                accentColor: selected.services[s.id] ? '#0d6efd' : undefined,
                                transform: 'scale(1.1)',
                                cursor: 'pointer'
                              }}
                            />
                            <div className="flex-grow-1">
                              <div>
                                <strong className={selected.services[s.id] ? 'text-primary' : ''}>{s.name || `Service #${s.id}`}</strong>
                              </div>
                              <div className="text-muted small">
                                Total: {Number(s.totalPrice || 0).toFixed(2)} BHD
                              </div>
                            </div>
                          </label>
                        ))
                      )}
                    </div>
                  </div>
                  <div className="col-md-6">
                    <h6>Pharmacy</h6>
                    <div
                      className="list-group"
                      style={{ maxHeight: 240, overflowY: "auto" }}
                    >
                      {inventoryLoading ? (
                        <div className="list-group-item text-muted">Pharmacy loading...</div>
                      ) : inventory.length === 0 ? (
                        <div className="list-group-item text-muted">No billable items</div>
                      ) : (
                        inventory.map((i) => (
                          <label
                            key={i.id}
                            className={`list-group-item d-flex align-items-center ${selected.inventory[i.id] ? '' : ''}`}
                            style={{
                              cursor: 'pointer',
                              transition: 'all 0.2s ease',
                              // border: selected.inventory[i.id] ? '1px solid #0d6efd' : '1px solid transparent'
                            }}
                          >
                            <input
                              type="checkbox"
                              className="form-check-input me-2"
                              checked={!!selected.inventory[i.id]}
                              onChange={() => toggleSelect('inventory', i.id)}
                              style={{
                                accentColor: selected.inventory[i.id] ? '#0d6efd' : undefined,
                                transform: 'scale(1.1)',
                                cursor: 'pointer'
                              }}
                            />
                            <div className="flex-grow-1">
                              <div>
                                <strong className={selected.inventory[i.id] ? 'text-primary' : ''}>{i.name || `Item #${i.id}`}</strong>
                              </div>
                              <div className="text-muted small">
                                Total: {Number(i.totalPrice || 0).toFixed(2)} BHD
                              </div>
                            </div>
                          </label>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleclose}
                >
                  Close
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={createInvoice}
                  disabled={creating}
                >
                  {creating ? "Saving..." : "Create Invoice"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Payment modal */}
      {payOpen && (
        <div
          className="modal show d-block"
          style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add Payment - {getLoggedInUserName()}</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={closePaymentModal}
                ></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label className="form-label">Patient</label>
                  <Select
                    classNamePrefix="react-select"
                    name="pay_patient_id"
                    options={patientOptions}
                    value={
                      patientOptions.find((opt) => opt.value === String(payPatientId)) || null
                    }
                    getOptionLabel={(e) => e.label}
                    getOptionValue={(e) => e.value}
                    onChange={handlePayPatientChangeSelect}
                    placeholder="Search by Name, Email, Mobile, Civil ID or Age"
                    isSearchable={true}
                    filterOption={customFilterOption}
                    menuPortalTarget={document.body}
                    styles={{
                      menuPortal: (base) => ({ ...base, zIndex: 2000 }),
                      menu: (base) => ({ ...base, zIndex: 2000 }),
                    }}
                    noOptionsMessage={() => (patients.length ? "No patients found" : "Loading patients...")}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Invoice ID</label>
                  <select
                    className="form-select"
                    value={payForm.invoice_id}
                    onChange={handlePayInvoiceSelect}
                    disabled={!payPatientId}
                  >
                    <option value="">Select invoice</option>
                    {remainingInvoices.map((inv) => {
                      const id = String(
                        inv.invoiceId ||
                        inv.invoice_id ||
                        inv.id ||
                        inv.invoiceid
                      );
                      const labelNo = inv.invoice_no || inv.invoiceNo || id;
                      const remaining =
                        inv.remaining_amount ??
                        inv.remaining ??
                        inv.remainingAmount ??
                        0;
                      const dateStr =
                        inv.invoice_date ||
                        inv.updated_at ||
                        inv.updatedAt ||
                        inv.date;
                      const dateLabel = dateStr
                        ? new Date(dateStr).toLocaleDateString("en-GB")
                        : "-";
                      return (
                        <option
                          key={id}
                          value={id}
                        >{`${labelNo} - Rem: ${Number(remaining).toFixed(
                          2
                        )} - ${dateLabel}`}</option>
                      );
                    })}
                  </select>
                </div>
                <div className="mb-3">
                  <label className="form-label">Amount</label>
                  <input
                    type="number"
                    className="form-control"
                    value={payForm.amount}
                    onChange={(e) =>
                      setPayForm({ ...payForm, amount: e.target.value })
                    }
                    min="0"
                    step="0.01"
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Payment Method</label>
                  <select
                    className="form-select"
                    value={payForm.payment_method}
                    onChange={(e) =>
                      setPayForm({ ...payForm, payment_method: e.target.value })
                    }
                  >
                    <option value="">Select payment method</option>
                    {paymentMethods.map((method) => (
                      <option key={method.id} value={method.name}>
                        {method.name}
                      </option>
                    ))}
                  </select>
                </div>
                {/* Optional transaction id input can be enabled if needed */}
              </div>
              <div className="modal-footer">
                <button
                  className="btn btn-secondary"
                  onClick={closePaymentModal}
                >
                  Cancel
                </button>
                <button
                  className="btn btn-primary"
                  disabled={payLoading}
                  onClick={submitPayment}
                >
                  {payLoading ? "Saving..." : "Save"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Add Insurance Company modal */}
      {insOpen && (
        <div
          className="modal show d-block"
          style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Add Insurance Company</h5>
                <button type="button" className="btn-close" onClick={closeInsModal}></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label className="form-label">Company Name</label>
                  <input
                    type="text"
                    className="form-control"
                    name="company_name"
                    value={insForm.company_name}
                    onChange={handleInsChange}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Address</label>
                  <input
                    type="text"
                    className="form-control"
                    name="address"
                    value={insForm.address}
                    onChange={handleInsChange}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Phone Number</label>
                  <input
                    type="text"
                    className="form-control"
                    name="phone_number"
                    value={insForm.phone_number}
                    onChange={handleInsChange}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Email</label>
                  <input
                    type="email"
                    className="form-control"
                    name="email"
                    value={insForm.email}
                    onChange={handleInsChange}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Website</label>
                  <input
                    type="text"
                    className="form-control"
                    name="website"
                    value={insForm.website}
                    onChange={handleInsChange}
                  />
                </div>
                <div className="mb-3">
                  <label className="form-label">Company Logo</label>
                  <input type="file" className="form-control" onChange={handleInsFile} />
                </div>
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={closeInsModal}>Cancel</button>
                <button className="btn btn-primary" disabled={insLoading} onClick={submitInsurance}>
                  {insLoading ? "Saving..." : "Save"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Insurance Companies list modal */}
      {insListOpen && (
        <div
          className="modal show d-block"
          style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Insurance Companies</h5>
                <button type="button" className="btn-close" onClick={closeInsListModal}></button>
              </div>
              <div className="modal-body">
                {insListLoading ? (
                  <div className="text-center text-muted">Loading...</div>
                ) : insuranceCompanies.length === 0 ? (
                  <div className="text-center text-muted">No companies found</div>
                ) : (
                  <div className="table-responsive">
                    <table className="table table-hover">
                      <thead>
                        <tr>
                          <th>Sn</th>
                          <th>Name</th>
                          <th>Phone</th>
                          <th>Email</th>
                          <th>Website</th>
                        </tr>
                      </thead>
                      <tbody>
                        {insuranceCompanies.map((c, idx) => (
                          <tr key={c.id || idx}>
                            <td>{idx + 1}</td>
                            <td>{c.company_name || c.name}</td>
                            <td>{c.phone_number || c.phone || '-'}</td>
                            <td>{c.email || '-'}</td>
                            <td>{c.website || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={closeInsListModal}>Close</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Pagination({ currentPage, totalPages, setCurrentPage }) {
  return (
    <div className="d-flex align-items-center gap-3">
      <button
        className="btn btn-sm btn-outline-primary"
        onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
        disabled={currentPage === 1}
      >
        {"<<"}
      </button>
      <span>
        {currentPage}/{totalPages}
      </span>
      <button
        className="btn btn-sm btn-outline-primary"
        onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
        disabled={currentPage === totalPages}
      >
        {">>"}
      </button>
    </div>
  );
}
