import axios from "axios";
import React, { useMemo, useState, useEffect } from "react";
import { baseurl } from "../../Baseurl";
import { fetchModuleMappings, hasSubModulePermission, isAdmin } from "../../utils/permissions";

export default function Reports() {
  const [showModal, setShowModal] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [permissions, setPermissions] = useState({
    generalReports: false,
    laboratoryReports: false,
    medicalReports: false,
    financialReports: false,
    dailyReports: false
  });

  useEffect(() => {
    const checkPermissions = async () => {
      if (isAdmin()) {
        setPermissions({
          generalReports: true,
          laboratoryReports: true,
          medicalReports: true,
          financialReports: true,
          dailyReports: true
        });
        return;
      }

      try {
        const allModules = await fetchModuleMappings();
        const reportsModule = allModules.find(m => m.module_name.toLowerCase() === 'reports');

        if (reportsModule && reportsModule.sub_modules) {
          const subModules = reportsModule.sub_modules;

          console.log('Reports submodules found:', subModules);

          setPermissions({
            generalReports: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'general_reports')?.id),
            laboratoryReports: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'laboratory_reports')?.id),
            medicalReports: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'medical_reports')?.id),
            financialReports: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'financial_reports')?.id),
            dailyReports: hasSubModulePermission(subModules.find(sm => sm.sub_module_name === 'daily_reports')?.id)
          });
        }
      } catch (err) {
        console.error("Error checking permissions", err);
      }
    };

    checkPermissions();
  }, []);

  const downloadReport = async (endpoint, filename) => {
    try {
      const params = {};

      // ✅ Include date range only for financial reports
      if (selectedCategory?.key === "financial") {
        if (startDate) params.startDate = startDate;
        if (endDate) params.endDate = endDate;
      }

      const response = await axios.get(`${baseurl}${endpoint}`, {
        params, // 👈 send params here
        responseType: "blob",
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
      console.log(`${filename} downloaded successfully`);
    } catch (error) {
      console.error("Download failed:", error);
    }
  };

  const reportConfig = {
    appointments: {
      endpoint: "dashboard/appointment_report",
      filename: "appointment_report.xlsx",
    },
    patientList: {
      endpoint: "dashboard/patients_list_report",
      filename: "patient_list_report.xlsx",
    },
    pharmacyDaily: {
      endpoint: "dashboard/rx_list_report",
      filename: "pharmacy_report.xlsx",
    },
    testsReport: {
      endpoint: "dashboard/lab_request_report",
      filename: "lab_report.xlsx",
    },
    visitByGender: {
      endpoint: "dashboard/patients_report_by_gender",
      filename: "Gender_report.xlsx",
    },
    visitByAge: {
      endpoint: "dashboard/patients_report_by_age",
      filename: "Patient_age_report.xlsx",
    },
    testsByLab1: {
      endpoint: "dashboard/patients_report_test_bylabs",
      filename: "Reports_test_by_labs_report.xlsx",
    },
    mostUsedServices: {
      endpoint: "dashboard/services_mostused_report",
      filename: "Services_Most_Used_report.xlsx",
    },
    chiefComplaint: {
      endpoint: "dashboard/chief_complaints_report",
      filename: "chief_complaint_report.xlsx",
    },
    allergiesReport: {
      endpoint: "dashboard/allergies_report",
      filename: "Allergy_Report.xlsx",
    },
    diagnosisByPatient: {
      endpoint: "dashboard/patients_diagnosis_report",
      filename: "Patient_diagnosis_report.xlsx",
    },
    xrayReport: {
      endpoint: "dashboard/patients_xray_reports",
      filename: "xrayReport.xlsx",
    },
    doctorsDaily: {
      endpoint: "dashboard/doctors_report",
      filename: "Doctor_report.xlsx",
    },
    invoices: {
      endpoint: "dashboard/patient_invoices_report",
      filename: "patient_invoices_report.xlsx",
    },
    cash: {
      endpoint: "dashboard/cash_payments_report",
      filename: "cash_payments_report.xlsx",
    },
    creditCard: {
      endpoint: "dashboard/creditCard_payments_report",
      filename: "creditCard_payments_report.xlsx",
    },
    invoicesDaily: {
      endpoint: "dashboard/daily_invoices_report",
      filename: "Daily_invoices_report.xlsx",
    },
    paymentsDaily: {
      endpoint: "dashboard/daily_payments_report",
      filename: "daily_payments_report.xlsx",
    },
  };

  const categories = useMemo(
    () => [
      {
        key: "general",
        title: "General Reports",
        icon: "fas fa-clipboard-list",
        items: [
          { key: "appointments", label: "Appointment" },
          { key: "patientList", label: "Patient List Report" },
          { key: "patientWithBalance", label: "Patient with Balance" },
          { key: "visitByGender", label: "Visit by Gender" },
          { key: "visitByAge", label: "Visits by Age" },
        ],
      },
      {
        key: "laboratory",
        title: "Laboratory Reports",
        icon: "fas fa-vials",
        items: [
          { key: "testsReport", label: "Tests Report" },
          { key: "testsByLab1", label: "Tests by Lab" },
        ],
      },
      {
        key: "medical",
        title: "Medical Reports",
        icon: "fas fa-stethoscope",
        items: [
          { key: "mostUsedServices", label: "Most Used Services" },
          { key: "chiefComplaint", label: "Chief Complaint Report" },
          { key: "diagnosisByPatient", label: "Diagnosis By Patient" },
          { key: "allergiesReport", label: "Allergies Report" },
          { key: "xrayReport", label: "X-Ray Report" },
        ],
      },
      {
        key: "financial",
        title: "Financial Reports",
        icon: "fas fa-file-invoice-dollar",
        items: [
          { key: "invoices", label: "Invoices Report" },
          { key: "invoicesVat", label: "Invoices + VAT" },
          { key: "income", label: "Income Report" },
          { key: "cash", label: "Cash Report" },
          { key: "creditCard", label: "Credit Card Report" },
          { key: "paymentsVsInvoices", label: "Payments VS Invoices Report" },
        ],
      },
      {
        key: "daily",
        title: "Daily Reports",
        icon: "fas fa-calendar-day",
        items: [
          { key: "paymentsDaily", label: "Payments +" },
          { key: "invoicesDaily", label: "Invoices +" },
          { key: "pharmacyDaily", label: "Pharmacy +" },
          { key: "doctorsDaily", label: "Doctors +" },
        ],
      },
    ],
    []
  );

  const handleCardClick = (category) => {
    setSelectedCategory(category);
    setShowModal(true);
    setStartDate("");
    setEndDate("");
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedCategory(null);
  };

  const handleComponentClick = (componentKey) => {
    console.log("Clicked on:", componentKey);
    const config = reportConfig[componentKey];
    if (config) {
      downloadReport(config.endpoint, config.filename);
    } else {
      console.log("No matching report found for:", componentKey);
    }
  };

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="pt-4">
          <div className="row g-5">
            {categories.map((cat) => {
              const permissionKey = cat.key === "general" ? "generalReports"
                : cat.key === "laboratory" ? "laboratoryReports"
                  : cat.key === "medical" ? "medicalReports"
                    : cat.key === "financial" ? "financialReports"
                      : cat.key === "daily" ? "dailyReports"
                        : null;

              const hasPermission = permissionKey ? permissions[permissionKey] : false;

              return (
                <div key={cat.key} className="col-lg-3">
                  <button
                    className="settingCard w-100"
                    onClick={() => hasPermission && handleCardClick(cat)}
                    disabled={!hasPermission}
                  >
                    <div className="settingIocn">
                      <i className={cat.icon}></i>
                    </div>
                    <h5>{cat.title}</h5>
                  </button>
                </div>
              );
            })}
          </div>
        </div>

        {showModal && selectedCategory && (
          <div
            className="modal show d-block"
            style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
          >
            <div className="modal-dialog modal-lg">
              <div className="modal-content">
                <div className="modal-header">
                  <h5 className="modal-title">
                    <i
                      className={selectedCategory.icon}
                      style={{ marginRight: "10px" }}
                    ></i>
                    {selectedCategory.title}
                  </h5>
                  <button
                    type="button"
                    className="btn-close"
                    onClick={closeModal}
                  ></button>
                </div>

                <div className="modal-body">
                  {/* ✅ Show date range only for Financial Reports */}
                  {selectedCategory.key === "financial" && (
                    <div className="row mb-3">
                      <div className="col-md-6">
                        <label>Start Date</label>
                        <input
                          type="date"
                          className="form-control"
                          value={startDate}
                          onChange={(e) => setStartDate(e.target.value)}
                        />
                      </div>
                      <div className="col-md-6">
                        <label>End Date</label>
                        <input
                          type="date"
                          className="form-control"
                          value={endDate}
                          onChange={(e) => setEndDate(e.target.value)}
                        />
                      </div>
                    </div>
                  )}

                  <div className="d-flex flex-column gap-3">
                    {selectedCategory.items.map((item) => (
                      <button
                        key={item.key}
                        className="btn btn-light report-option w-100 py-3 rounded-3 text-center fw-medium"
                        onClick={() => handleComponentClick(item.key)}
                      >
                        {item.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={closeModal}
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
