import React from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { baseurImage } from "../../Baseurl";

export default function ViewCompany() {
  const navigate = useNavigate();
  const { id } = useParams();
  const { state } = useLocation();
  const company = state?.company;

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="col-12">
          <div className="card table-card">
            <div className="tableHeader">
              <h5 style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span
                  style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                  onClick={() => navigate(-1)}
                  title="Back"
                >
                  &larr;
                </span>
                Insurance Company Details
              </h5>
            </div>
            <div className="card-body" style={{ margin: "15px" }}>
              {!company && (
                <div className="alert alert-warning">No company data provided for ID {id}. Open from Insurance → Companies tab.</div>
              )}
              {company && (
                <div className="row">
                  <div className="col-12 mb-3">
                    {company.logo && (
                      <img
                        src={`${baseurImage}${company.logo}`}
                        alt="Company Logo"
                        style={{ width: '80px', height: '80px', objectFit: 'cover', borderRadius: '6px' }}
                      />
                    )}
                  </div>
                  {[
                    ["Company Name", company.companyName],
                    ["Phone Number", company.telephone],
                    ["Address", company.address],
                    ["Website", company.website],
                    ["Email", company.email],
                    ["Status", (company.status || 'active')],
                    ["Created Date", company.created_at ? new Date(company.created_at).toLocaleDateString('en-GB') : '-'],
                    ["Updated Date", company.updated_at ? new Date(company.updated_at).toLocaleDateString('en-GB') : '-'],
                  ].map(([label, value], idx) => (
                    <div className="col-md-6 mb-3" key={idx}>
                      <label className="form-label">{label}</label>
                      <input type="text" className="form-control" value={value || ''} disabled />
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

