import { useState, useEffect } from "react";
import {
  NavLink,
  useNavigate,
  useLocation,
  matchPath,
} from "react-router-dom";
import logo from "../../assests/logo.png";
import home from "../../../src/assests/sideImg/home.png";
import dash from "../../../src/assests/sideImg/HOME-DASH.png";
import appoint from "../../../src/assests/sideImg/appointments.png";
import bill from "../../../src/assests/sideImg/billing.png";
import lab from "../../../src/assests/sideImg/labs.png";
import pharmacy from "../../../src/assests/sideImg/pharmacy.png";
import medical from "../../../src/assests/sideImg/medicals.png";
import doctor from "../../../src/assests/sideImg/doctors.png";
import insurance from "../../../src/assests/sideImg/insurance.png";
import treatment from "../../../src/assests/sideImg/treatment.png";
import vital from "../../../src/assests/sideImg/vitals.png";
import file from "../../../src/assests/sideImg/files.png";
import stats from "../../../src/assests/sideImg/stats.png";
import setting from "../../../src/assests/sideImg/settings.png";
import report from "../../../src/assests/sideImg/reports.png";
import { addDisabledStateToMenu, isAdmin as checkIsAdmin } from "../../utils/permissions";

export default function Header({ isOpen }) {
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [menuWithPermissions, setMenuWithPermissions] = useState([]);
  const navigate = useNavigate();
  const location = useLocation();

  const toggleUserMenu = () => {
    setUserMenuOpen(!userMenuOpen);
  };

  const isAdmin = checkIsAdmin();

  const baseSidebarMenu = [
    {
      path: "/Homepage",
      text: "Home",
      icon: dash,
    },
    {
      path: "/Admin/dashboard",
      text: "Dashboard",
      icon: stats,
    },
    {
      path: "/Admin/patient",
      text: "Patients",
      icon: file,
      matchPaths: ["addPatient", "Manageappointment", "EditPatient"]
    },
    {
      path: "/Admin/appointment2",
      text: "Appointments",
      icon: appoint,
      matchPaths: ["Addappointment"]
    },
    {
      path: "/Admin/ManageLabs",
      text: "Labs",
      icon: lab,
    },
    {
      path: "/Admin/Billing",
      text: "Billing",
      icon: bill,
    },
    {
      path: "/Admin/Pharmacy",
      text: "Pharmacy",
      icon: pharmacy,
    },
    {
      path: "/Admin/Medicals",
      text: "Medicals",
      icon: medical,
    },
    {
      path: "/Admin/Insurance",
      text: "Insurance",
      icon: insurance,
    },
    {
      path: "/Admin/Service",
      text: "Services",
      icon: treatment,
    },
    {
      path: "/Admin/ReportsInc",
      text: "Reports",
      icon: report,
    },
  ];

  // Add Settings menu only for admin user (ID 12)
  if (isAdmin) {
    baseSidebarMenu.push({
      path: "/Admin/setting",
      text: "Setting",
      icon: setting,
      matchPaths: ["/Admin/business_setting", "/Admin/finance"],
    });
  }

  // Load menu with permission states
  useEffect(() => {
    const loadMenuPermissions = async () => {
      const menuWithState = await addDisabledStateToMenu(baseSidebarMenu);
      setMenuWithPermissions(menuWithState);
      console.log("Menu with permissions loaded:", menuWithState);
    };

    loadMenuPermissions();
  }, []); // Run once on mount

  const handleclicklogout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <nav className="pc-sidebar">
      <div className="navbar-wrapper">
        <div className="navbar-content">
          <ul className="pc-navbar">
            {menuWithPermissions.map((item, index) => {
              const isActive =
                location.pathname.includes(item.path) ||
                (item.matchPaths &&
                  item.matchPaths.some((subPath) =>
                    location.pathname.includes(subPath)
                  ));

              const isDisabled = item.disabled;

              return (
                <li className="pc-item" key={index}>
                  <NavLink
                    to={isDisabled ? "#" : item.path}
                    className={`pc-link ${isActive ? "active-link" : ""} ${isDisabled ? "disabled-link" : ""}`}
                    style={{
                      textDecoration: "none",
                      opacity: isDisabled ? 0.5 : 1,
                      pointerEvents: isDisabled ? "none" : "auto",
                      cursor: isDisabled ? "not-allowed" : "pointer"
                    }}
                    onClick={(e) => {
                      if (isDisabled) {
                        e.preventDefault();
                      }
                    }}
                  >
                    <span className="pc-micon">
                      <div className="pc-icon">
                        <img src={item.icon} alt={item.text} />
                      </div>
                    </span>
                    <span className="pc-mtext fw-800">{item.text}</span>
                  </NavLink>
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    </nav>
  );
}
