      doc.rect(checkboxX1, checkboxY1, checkboxSize1, checkboxSize1);

      // Draw checkmark inside the rectangle
      doc.setLineWidth(0.5);
      doc.line(
        checkboxX1 + 0.6,
        checkboxY1 + 1.5,
        checkboxX1 + 1.2,
        checkboxY1 + 2.2
      );
      doc.line(
        checkboxX1 + 1.2,
        checkboxY1 + 2.2,
        checkboxX1 + 3,
        checkboxY1 + 0.3
      );
