import React, { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import image from "../../../src/assests/profile.jpg"
import { useSelector, useDispatch } from "react-redux";
import { fetchBusinessSettings, updateBusinessSettings } from "../../store/businessSlice";
import Swal from "sweetalert2";
import { baseurImage } from "../../Baseurl";

const BusinessSetting = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { businessSettings, loading, error } = useSelector((state) => state.business);

  const [formData, setFormData] = useState({
    official_name: "",
    cr_number: "",
    telephone_1: "",
    telephone_2: "",
    vat_number: "",
    email: "",
    branches: "",
    specialty: ""
  });
  const [logoFile, setLogoFile] = useState(null);
  const logoInputRef = useRef(null);

  console.log('Current businessSettings:', businessSettings);
  console.log('Current formData:', formData);

  // Get doctor ID from localStorage
  const getUserId = () => {
    try {
      const userMedical = localStorage.getItem("userMedical");
      if (userMedical) {
        const userData = JSON.parse(userMedical);
        return userData?.id || userData?.data?.id || null;
      }
      return null;
    } catch (error) {
      console.error("Error parsing userMedical from localStorage:", error);
      return null;
    }
  };

  const doctorId = getUserId();

  console.log("Doctor ID from localStorage:", doctorId);

  // Update form data when business settings change
  useEffect(() => {
    if (businessSettings) {
      setFormData({
        official_name: businessSettings.official_name || "",
        cr_number: businessSettings.cr_number || "",
        telephone_1: businessSettings.telephone_1 || "",
        telephone_2: businessSettings.telephone_2 || "",
        vat_number: businessSettings.vat_number || "",
        email: businessSettings.email || "",
        branches: businessSettings.branches || "",
        specialty: businessSettings.specialty || ""
      });
    }
  }, [businessSettings]);

  // Fetch business settings on component mount
  useEffect(() => {
    if (doctorId && !businessSettings) {
      dispatch(fetchBusinessSettings(doctorId));
    }
  }, [dispatch, doctorId, businessSettings]);

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleLogoChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      // Check if the file is PNG format only
      const isPNG = file.type === 'image/png' || file.name.toLowerCase().endsWith('.png');

      if (!isPNG) {
        Swal.fire({
          icon: 'error',
          title: 'Invalid File Type',
          text: 'Only PNG format is allowed for the business logo. Please upload a PNG image.',
          confirmButtonText: 'OK'
        });
        // Clear the file input
        e.target.value = '';
        return;
      }

      // Additional check for file size (optional - max 5MB)
      const maxSize = 5 * 1024 * 1024; // 5MB
      if (file.size > maxSize) {
        Swal.fire({
          icon: 'error',
          title: 'File Too Large',
          text: 'Image size should not exceed 5MB.',
          confirmButtonText: 'OK'
        });
        e.target.value = '';
        return;
      }

      setLogoFile(file);
    }
  };

  const triggerLogoPick = () => {
    if (logoInputRef.current) {
      logoInputRef.current.click();
    }
  };

  const getLogoPreview = () => {
    if (logoFile) {
      const url = URL.createObjectURL(logoFile);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      return url;
    }

    const logoFromServer = businessSettings?.image || businessSettings?.logo;

    if (logoFromServer) {
      if (typeof logoFromServer === "string") {
        if (logoFromServer.startsWith("http://") || logoFromServer.startsWith("https://")) {
          return logoFromServer;
        }
        return `${baseurImage}${logoFromServer}?v=${new Date().getTime()}`;

      }
    }

    return image;
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      console.log('Submitting form with data:', formData);
      console.log('Doctor ID:', doctorId);
      console.log('Business Setting ID:', businessSettings?.id);

      // Dispatch the update action
      const result = await dispatch(updateBusinessSettings({
        doctorId,
        formData,
        businessSettingId: businessSettings?.id,
        logoFile
      })).unwrap();

      console.log('Update result:', result);

      // Show success message
      await Swal.fire({
        icon: 'success',
        title: 'Success!',
        text: 'Business settings updated successfully!',
        timer: 2000,
        showConfirmButton: false
      });

    } catch (error) {
      console.error("Error saving business settings:", error);

      // Show error message
      await Swal.fire({
        icon: 'error',
        title: 'Error!',
        text: error || 'Failed to save business settings. Please try again.',
        confirmButtonText: 'OK'
      });
    }
  };

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="row">
          <div className="col-md-12">
            <div className="card mb-3" style={{ position: "relative" }}>
              <div className="personaimg text-center" />
              <div className="col-12 searchParent">
                <h5 className="card-title" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span
                    style={{ cursor: 'pointer', color: '#007bff', fontWeight: 'bold', fontSize: '1.5rem' }}
                    onClick={() => navigate(-1)}
                    title="Back"
                  >
                    &larr;
                  </span>
                  Business Setting
                </h5>
                <div className="row">
                  <div>
                    <div className="imgBusinessSet" style={{ position: "relative" }}>
                      <img src={getLogoPreview()} alt="Business Logo" />
                      <div className="profileEditIcon">
                        <i
                          onClick={triggerLogoPick}
                          className="ti ti-edit f-20"
                          style={{ color: "rgb(70, 128, 255)", cursor: "pointer" }}
                        ></i>
                        <input
                          ref={logoInputRef}
                          type="file"
                          onChange={handleLogoChange}
                          className="d-none"
                          accept="image/png"
                        />
                      </div>
                    </div>
                  </div>
                </div>
                <form className="row g-3 p20" onSubmit={handleSubmit}>
                  <div className="col-md-6">
                    <label className="form-label">Official Name</label>
                    <input
                      type="text"
                      className="form-control"
                      name="official_name"
                      value={formData.official_name}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">CR Number</label>
                    <input
                      type="text"
                      className="form-control"
                      name="cr_number"
                      value={formData.cr_number}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">Telephone 1</label>
                    <input
                      type="text"
                      className="form-control"
                      name="telephone_1"
                      value={formData.telephone_1}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">Telephone 2</label>
                    <input
                      type="text"
                      className="form-control"
                      name="telephone_2"
                      value={formData.telephone_2}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">VAT Number</label>
                    <input
                      type="text"
                      className="form-control"
                      name="vat_number"
                      value={formData.vat_number}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">Email</label>
                    <input
                      type="email"
                      className="form-control"
                      name="email"
                      value={formData.email}
                      onChange={handleChange}
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">Branches</label>
                    <select
                      className="form-select"
                      name="branches"
                      value={formData.branches}
                      onChange={handleChange}
                    >
                      <option value="">Select Branches</option>
                      <option value="1">1</option>
                      <option value="2">2</option>
                      <option value="3">3</option>
                      <option value="4">4</option>
                      <option value="5">5</option>
                    </select>
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">Specialty</label>
                    <input
                      type="text"
                      className="form-control"
                      name="specialty"
                      value={formData.specialty}
                      onChange={handleChange}
                    />
                  </div>

                  <div className="col-md-12 text-center">
                    <button type="submit" className="bgBtn" disabled={loading}>
                      {loading ? "Saving..." : "Save"}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BusinessSetting;
