import React, { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import axios from 'axios'
import Swal from 'sweetalert2'
import { baseurl, baseurImage } from '../../Baseurl'

const Security = () => {
  const navigate = useNavigate()
  const [allUsers, setAllUsers] = useState([])
  const [allStaff, setAllStaff] = useState([])
  const [allDoctors, setAllDoctors] = useState([])
  const [allNurses, setAllNurses] = useState([])

  const [searchAll, setSearchAll] = useState('')
  const [searchStaff, setSearchStaff] = useState('')
  const [searchDoctor, setSearchDoctor] = useState('')
  const [searchNurse, setSearchNurse] = useState('')

  const [currentPageAll, setCurrentPageAll] = useState(1)
  const [currentPageStaff, setCurrentPageStaff] = useState(1)
  const [currentPageDoctor, setCurrentPageDoctor] = useState(1)
  const [currentPageNurse, setCurrentPageNurse] = useState(1)
  const itemsPerPage = 10


  const getUserImageUrl = (user) => {
    if (user?.personalPhoto && user.personalPhoto !== 'null' && user.personalPhoto !== 'undefined') {
      return `${baseurImage}${user.personalPhoto}`
    }
    return '../assets/images/user/avatar-1.jpg'
  }

  useEffect(() => {
    const fetchAll = async () => {
      try {
        const [u, s, d, n] = await Promise.all([
          axios.get(`${baseurl}getAllUsers`),
          axios.get(`${baseurl}getAllStaff`),
          axios.get(`${baseurl}getAllDoctors`),
          axios.get(`${baseurl}getAllNurses`)
        ])
        if (u.data?.success) setAllUsers(u.data.data || [])
        if (s.data?.success) setAllStaff(s.data.data || [])
        if (d.data?.success) setAllDoctors(d.data.data || [])
        if (n.data?.success) setAllNurses(n.data.data || [])
      } catch (e) {
        console.error(e)
      }
    }
    fetchAll()
  }, [])

  const filteredAll = (allUsers || []).filter((item) => {
    const q = searchAll.toLowerCase()
    return (
      (item.fullName && item.fullName.toLowerCase().includes(q)) ||
      (item.email && item.email.toLowerCase().includes(q)) ||
      (item.civilId && String(item.civilId).toLowerCase().includes(q)) ||
      (item.phoneNumber && String(item.phoneNumber).toLowerCase().includes(q)) ||
      (item.role && item.role.toLowerCase().includes(q))
    )
  })
  const filteredStaff = (allStaff || []).filter((item) => {
    const q = searchStaff.toLowerCase()
    return (
      (item.fullName && item.fullName.toLowerCase().includes(q)) ||
      (item.email && item.email.toLowerCase().includes(q)) ||
      (item.civilId && String(item.civilId).toLowerCase().includes(q)) ||
      (item.phoneNumber && String(item.phoneNumber).toLowerCase().includes(q))
    )
  })
  const filteredDoctors = (allDoctors || []).filter((item) => {
    const q = searchDoctor.toLowerCase()
    return (
      (item.fullName && item.fullName.toLowerCase().includes(q)) ||
      (item.email && item.email.toLowerCase().includes(q)) ||
      (item.specialty && item.specialty.toLowerCase().includes(q)) ||
      (item.civilId && String(item.civilId).toLowerCase().includes(q)) ||
      (item.phoneNumber && String(item.phoneNumber).toLowerCase().includes(q))
    )
  })
  const filteredNurses = (allNurses || []).filter((item) => {
    const q = searchNurse.toLowerCase()
    return (
      (item.fullName && item.fullName.toLowerCase().includes(q)) ||
      (item.email && item.email.toLowerCase().includes(q)) ||
      (item.civilId && String(item.civilId).toLowerCase().includes(q)) ||
      (item.phoneNumber && String(item.phoneNumber).toLowerCase().includes(q))
    )
  })

  const openPermissions = (user) => {
    navigate('/Admin/staff-permissions', { state: { account: user } })
  }

  return (
    <div className="pc-container">
      <div className="pc-content">
        <div className="border rounded p-3">
          <ul className="nav nav-pills nav-fill mb-3 hr" id="securityTab" role="tablist">
            <li className="nav-item" role="presentation">
              <button className="nav-link active" id="staff-tab" data-bs-toggle="tab" data-bs-target="#staff" type="button" role="tab" aria-controls="staff" aria-selected="true">Staff</button>
            </li>
            <li className="nav-item" role="presentation">
              <button className="nav-link" id="doctor-tab" data-bs-toggle="tab" data-bs-target="#doctor" type="button" role="tab" aria-controls="doctor" aria-selected="false">Doctor</button>
            </li>
            <li className="nav-item" role="presentation">
              <button className="nav-link" id="nurse-tab" data-bs-toggle="tab" data-bs-target="#nurse" type="button" role="tab" aria-controls="nurse" aria-selected="false">Nurse</button>
            </li>
          </ul>

          <div className="tab-content p-3 border-top-0" id="securityTabContent">

            <div className="tab-pane fade show active" id="staff" role="tabpanel" aria-labelledby="staff-tab">
              <div className="card table-card">
                <div className="card-header">
                  <div className="d-sm-flex align-items-center justify-content-start gap-3 flex-wrap">
                    <div style={{ width: '300px', position: 'relative' }}>
                      <input type="text" className="form-control" placeholder="Search staff..." value={searchStaff} onChange={(e) => { setSearchStaff(e.target.value); setCurrentPageStaff(1) }} style={{ paddingLeft: '35px' }} />
                      <span style={{ position: 'absolute', top: '50%', left: '10px', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#888' }}>
                        <i className="ti ti-search f-16"></i>
                      </span>
                    </div>
                  </div>
                </div>
                <div className="card-body pt-3">
                  <div className="table-responsive">
                    <table className="table table-hover">
                      <thead>
                        <tr>
                          <th>Photo</th>
                          <th>Name</th>
                          <th>DOB</th>
                          <th>License Id</th>
                          <th>Gender</th>
                          <th>Civil Id</th>
                          <th>Phone No</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(filteredStaff || []).slice((currentPageStaff - 1) * itemsPerPage, currentPageStaff * itemsPerPage).map((item, index) => (
                          <tr key={index}>
                            <td><img src={getUserImageUrl(item)} alt="user" className="img-radius wid-40" onError={(e) => { e.target.src = '../assets/images/user/avatar-1.jpg' }} /></td>
                            <td><h6 className="mb-0">{item.fullName}</h6></td>
                            <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString('en-GB') : '-'}</td>
                            <td>{item.licenseId}</td>
                            <td>{item.gender}</td>
                            <td>{item.civilId}</td>
                            <td>{item.phoneNumber}</td>
                            <td>
                              <div onClick={() => openPermissions(item)} className="avtar avtar-xs btn-link-secondary" style={{ cursor: 'pointer' }} title="View Permissions">
                                <i className="ti ti-eye f-20" />
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination currentPage={currentPageStaff} totalPages={Math.ceil((filteredStaff || []).length / itemsPerPage)} setCurrentPage={setCurrentPageStaff} />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="tab-pane fade" id="doctor" role="tabpanel" aria-labelledby="doctor-tab">
              <div className="card table-card">
                <div className="card-header">
                  <div className="d-sm-flex align-items-center justify-content-start gap-3 flex-wrap">
                    <div style={{ width: '300px', position: 'relative' }}>
                      <input type="text" className="form-control" placeholder="Search doctors..." value={searchDoctor} onChange={(e) => { setSearchDoctor(e.target.value); setCurrentPageDoctor(1) }} style={{ paddingLeft: '35px' }} />
                      <span style={{ position: 'absolute', top: '50%', left: '10px', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#888' }}>
                        <i className="ti ti-search f-16"></i>
                      </span>
                    </div>
                  </div>
                </div>
                <div className="card-body pt-3">
                  <div className="table-responsive">
                    <table className="table table-hover">
                      <thead>
                        <tr>
                          <th>Photo</th>
                          <th>Name</th>
                          <th>DOB</th>
                          <th>License Id</th>
                          <th>Gender</th>
                          <th>Specialty</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(filteredDoctors || []).slice((currentPageDoctor - 1) * itemsPerPage, currentPageDoctor * itemsPerPage).map((item, index) => (
                          <tr key={index}>
                            <td><img src={getUserImageUrl(item)} alt="user" className="img-radius wid-40" onError={(e) => { e.target.src = '../assets/images/user/avatar-1.jpg' }} /></td>
                            <td><h6 className="mb-0">{item.fullName}</h6></td>
                            <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString('en-GB') : '-'}</td>
                            <td>{item.licenseId}</td>
                            <td>{item.gender}</td>
                            <td>{item.specialty}</td>
                            <td>
                              <div onClick={() => openPermissions(item)} className="avtar avtar-xs btn-link-secondary" style={{ cursor: 'pointer' }} title="View Permissions">
                                <i className="ti ti-eye f-20" />
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination currentPage={currentPageDoctor} totalPages={Math.ceil((filteredDoctors || []).length / itemsPerPage)} setCurrentPage={setCurrentPageDoctor} />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="tab-pane fade" id="nurse" role="tabpanel" aria-labelledby="nurse-tab">
              <div className="card table-card">
                <div className="card-header">
                  <div className="d-sm-flex align-items-center justify-content-start gap-3 flex-wrap">
                    <div style={{ width: '300px', position: 'relative' }}>
                      <input type="text" className="form-control" placeholder="Search nurses..." value={searchNurse} onChange={(e) => { setSearchNurse(e.target.value); setCurrentPageNurse(1) }} style={{ paddingLeft: '35px' }} />
                      <span style={{ position: 'absolute', top: '50%', left: '10px', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#888' }}>
                        <i className="ti ti-search f-16"></i>
                      </span>
                    </div>
                  </div>
                </div>
                <div className="card-body pt-3">
                  <div className="table-responsive">
                    <table className="table table-hover">
                      <thead>
                        <tr>
                          <th>Photo</th>
                          <th>Name</th>
                          <th>Email</th>
                          <th>Civil Id</th>
                          <th>Gender</th>
                          <th>DOB</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {(filteredNurses || []).slice((currentPageNurse - 1) * itemsPerPage, currentPageNurse * itemsPerPage).map((item, index) => (
                          <tr key={index}>
                            <td><img src={getUserImageUrl(item)} alt="user" className="img-radius wid-40" onError={(e) => { e.target.src = '../assets/images/user/avatar-1.jpg' }} /></td>
                            <td><h6 className="mb-0">{item.fullName}</h6></td>
                            <td>{item.email}</td>
                            <td>{item.civilId}</td>
                            <td>{item.gender}</td>
                            <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString('en-GB') : '-'}</td>
                            <td>
                              <div onClick={() => openPermissions(item)} className="avtar avtar-xs btn-link-secondary" style={{ cursor: 'pointer' }} title="View Permissions">
                                <i className="ti ti-eye f-20" />
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    <div className="d-flex justify-content-end mt-3">
                      <Pagination currentPage={currentPageNurse} totalPages={Math.ceil((filteredNurses || []).length / itemsPerPage)} setCurrentPage={setCurrentPageNurse} />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

    </div>
  )
}

export default Security

function Pagination({ currentPage, totalPages, setCurrentPage }) {
  return (
    <div className="d-flex align-items-center gap-3">
      <button className="btn btn-sm btn-outline-primary" onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))} disabled={currentPage === 1}>
        &lt;&lt;
      </button>
      <span>{currentPage} / {totalPages || 1}</span>
      <button className="btn btn-sm btn-outline-primary" onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages || 1))} disabled={currentPage === (totalPages || 1)}>
        &gt;&gt;
      </button>
    </div>
  )
}


