import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';
import { baseurl } from '../Baseurl';

// Load initial business settings from localStorage
const loadInitialBusinessSettings = () => {
  try {
    const stored = localStorage.getItem('businessSetting');
    if (!stored) return null;
    return JSON.parse(stored);
  } catch {
    return null;
  }
};

// Async thunk to fetch business settings
export const fetchBusinessSettings = createAsyncThunk(
  'business/fetchBusinessSettings',
  async (doctorId, { rejectWithValue }) => {
    try {
      const response = await axios.get(`${baseurl}getBusinessSettingByDoctorId/${doctorId}`);
      const data = response.data?.data || response.data;
      
      // Store in localStorage for persistence including image
      if (data) {
        const dataToStore = {
          ...data,
          // Ensure image/logo field is included
          image: data.image || data.logo || null
        };
        localStorage.setItem('businessSetting', JSON.stringify(dataToStore));
        // Also store the image filename separately for easier access
        if (data.image || data.logo) {
          localStorage.setItem('businessSettingImage', data.image || data.logo);
        }
        console.log('Stored businessSetting in localStorage:', dataToStore);
        
        // Dispatch custom event to notify other components
        window.dispatchEvent(new CustomEvent('businessSettingUpdated', {
          detail: { businessSetting: dataToStore }
        }));
      }
      
      return data;
    } catch (error) {
      return rejectWithValue(error.response?.data?.message || 'Failed to fetch business settings');
    }
  }
);

// Async thunk to update business settings
export const updateBusinessSettings = createAsyncThunk(
  'business/updateBusinessSettings',
  async ({ doctorId, formData, businessSettingId, logoFile }, { rejectWithValue, dispatch }) => {
    try {
      const payload = {
        official_name: formData.official_name,
        cr_number: formData.cr_number,
        telephone_1: formData.telephone_1,
        telephone_2: formData.telephone_2,
        vat_number: formData.vat_number,
        email: formData.email,
        branches: parseInt(formData.branches) || 0,
        specialty: formData.specialty
      };

      // Use businessSettingId if available, otherwise use doctorId
      const endpoint = businessSettingId 
        ? `${baseurl}updateBusinessSetting/${businessSettingId}`
        : `${baseurl}updateBusinessSetting/${doctorId}`;

      let requestData = payload;
      let config = {};

      if (logoFile) {
        const formDataToSend = new FormData();
        formDataToSend.append('official_name', payload.official_name || '');
        formDataToSend.append('cr_number', payload.cr_number || '');
        formDataToSend.append('telephone_1', payload.telephone_1 || '');
        formDataToSend.append('telephone_2', payload.telephone_2 || '');
        formDataToSend.append('vat_number', payload.vat_number || '');
        formDataToSend.append('email', payload.email || '');
        formDataToSend.append('branches', String(payload.branches || 0));
        formDataToSend.append('specialty', payload.specialty || '');
        formDataToSend.append('image', logoFile);

        requestData = formDataToSend;
        config = { headers: { 'Content-Type': 'multipart/form-data' } };
      }

      const response = await axios.put(endpoint, requestData, config);
      console.log('Update API Response:', response.data);
      
      // After successful update, fetch fresh data
      const freshDataResponse = await axios.get(`${baseurl}getBusinessSettingByDoctorId/${doctorId}`);
      const freshData = freshDataResponse.data?.data || freshDataResponse.data;
      
      console.log('Fresh data after update:', freshData);
      
      // Update localStorage with fresh data including image
      if (freshData) {
        const dataToStore = {
          ...freshData,
          // Ensure image/logo field is included
          image: freshData.image || freshData.logo || null
        };
        localStorage.setItem('businessSetting', JSON.stringify(dataToStore));
        // Also store the image filename separately for easier access
        if (freshData.image || freshData.logo) {
          localStorage.setItem('businessSettingImage', freshData.image || freshData.logo);
        }
        console.log('Updated localStorage with:', dataToStore);
        
        // Dispatch custom event to notify other components
        window.dispatchEvent(new CustomEvent('businessSettingUpdated', {
          detail: { businessSetting: dataToStore }
        }));
      }
      
      return freshData;
    } catch (error) {
      console.error('Update business settings error:', error);
      return rejectWithValue(error.response?.data?.message || 'Failed to update business settings');
    }
  }
);

const businessSlice = createSlice({
  name: 'business',
  initialState: {
    businessSettings: loadInitialBusinessSettings(),
    loading: false,
    error: null
  },
  reducers: {
    setBusinessSettings(state, action) {
      state.businessSettings = action.payload;
      // Also update localStorage
      if (action.payload) {
        localStorage.setItem('businessSetting', JSON.stringify(action.payload));
        // Also store the image filename separately for easier access
        if (action.payload.image || action.payload.logo) {
          localStorage.setItem('businessSettingImage', action.payload.image || action.payload.logo);
        }
        
        // Dispatch custom event to notify other components
        window.dispatchEvent(new CustomEvent('businessSettingUpdated', {
          detail: { businessSetting: action.payload }
        }));
      }
    },
    clearBusinessSettings(state) {
      state.businessSettings = null;
      localStorage.removeItem('businessSetting');
    },
    updateOfficialName(state, action) {
      if (state.businessSettings) {
        state.businessSettings.official_name = action.payload;
        // Update localStorage
        localStorage.setItem('businessSetting', JSON.stringify(state.businessSettings));
        // Also update the image filename separately if it exists
        if (state.businessSettings.image || state.businessSettings.logo) {
          localStorage.setItem('businessSettingImage', state.businessSettings.image || state.businessSettings.logo);
        }
      }
    }
  },
  extraReducers: (builder) => {
    builder
      // Fetch business settings
      .addCase(fetchBusinessSettings.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchBusinessSettings.fulfilled, (state, action) => {
        state.loading = false;
        state.businessSettings = action.payload;
        console.log('Fetch business settings fulfilled with:', action.payload);
      })
      .addCase(fetchBusinessSettings.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      })
      // Update business settings
      .addCase(updateBusinessSettings.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(updateBusinessSettings.fulfilled, (state, action) => {
        state.loading = false;
        state.businessSettings = action.payload;
        console.log('Redux state updated with:', action.payload);
      })
      .addCase(updateBusinessSettings.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });
  }
});

export const { setBusinessSettings, clearBusinessSettings, updateOfficialName } = businessSlice.actions;
export default businessSlice.reducer;
