  import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Tooltip,
  } from 'chart.js';
  import { Bar } from 'react-chartjs-2';
  
  // Register Chart.js components
  ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip);
  
  const ThirdBar = () => {
    // Simulated data (can be dynamic)
    const data = {
      labels: Array.from({ length: 10 }, (_, i) => i + 1),
      datasets: [
        {
          label: 'Activity',
          data: [1, 4, 7, 3, 9, 6, 10, 5, 3, ],
          backgroundColor: '#318965',
          borderRadius: 4,
          barPercentage: 0.7,
          categoryPercentage: 0.7,
        },
      ],
    };
  
    const options = {
      responsive: true,
      plugins: {
        legend: { display: false },
        tooltip: { enabled: false }, 

      },
      scales: {
        x: {
          display: false, // hide labels
        },
        y: {
          display: false,
          beginAtZero: true,
        },
      },
    };
  
    return (
      <div
      className='smallChartDash'
       style={{
        width: "100%", // chart width is responsive
        maxWidth: "90px", // optional max width
        height: "60px", // custom height
        margin: "0 auto", // center if smaller than container
      }}>
        <Bar data={data} options={options} />
      </div>
    );
  };
  
  export default ThirdBar;