import { NavLink, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import { baseurl } from "../Baseurl";
export default function Examinationlocal() {
  const navigate = useNavigate();
  const [patients, setPatients] = useState([]);
  const [openVital121, setOpenVital121] = useState(false);
  const [editabledata, setEditabledata] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const [isEditMode, setIsEditMode] = useState(false);
  const [editId, setEditId] = useState(null);
  const [inpval, setInpval] = useState({
    Name: "",
    description: "",
  });

  useEffect(() => {
    getdata();
  }, []);

  const getdata = async () => {
    try {
      const response = await axios.get(
        `${baseurl}getAllTablesText?table=examination_local`
      );
      if (response.data.success === true) {
        setPatients(response.data.data);
      } else {
        console.error("Failed to fetch patient data:", response.data.message);
      }
    } catch (error) {
      console.error("Error fetching patient data:", error.message);
    }
  };

  const handledelete = async (id) => {
    const confirm = await Swal.fire({
      title: "Are you sure?",
      text: "You won't be able to revert this!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Yes, delete it!",
    });
    if (confirm.isConfirmed) {
      try {
        await axios.delete(
          `${baseurl}deleteAllTablesText/${id}?table=examination_local`
        );
        Swal.fire("Deleted!", "examination_local has been deleted.", "success");
        getdata();
      } catch (error) {
        Swal.fire("Error!", "Something went wrong while deleting.", "error");
      }
    }
  };

  const handlechange = (e) => {
    const { name, value } = e.target;
    setInpval({ ...inpval, [name]: value });
  };

  const viewmoal = (item) => {
    console.log(item);
    setEditabledata(true);
    setInpval({
      description: item.text,
    });
    setEditId(item.id);
  };

  const handleclickoffmodal = () => {
    setEditabledata(false);
  };

  const handleEdit = (item) => {
    setInpval({
      description: item.text,
    });
    setEditId(item.id);
    setIsEditMode(true);
    setOpenVital121(true);
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1);
  };

  const filteredPatients = patients.filter(
    (item) =>
      item.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.text?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalPages = Math.ceil(filteredPatients.length / itemsPerPage);
  const indexOfLast = currentPage * itemsPerPage;
  const indexOfFirst = indexOfLast - itemsPerPage;
  const currentPatients = filteredPatients.slice(indexOfFirst, indexOfLast);

  const handleclickopenvital11 = () => {
    setOpenVital121(true);
  };

  const hndleclosemodalservice = () => {
    setOpenVital121(false);
    setIsEditMode(false);
    setEditId(null);
    setInpval({
      name: "",
      description: "",
    });
  };

const handlesavevital123 = async () => {
  try {
    if (!inpval.description || inpval.description.trim() === "") {
      Swal.fire("Validation Error", "Description is required.", "warning");
      return;
    }

    const dataPost = {
      text: inpval.description,
    };

    let response;
    if (isEditMode) {
      response = await axios.put(
        `${baseurl}editAllTableText/${editId}?table=examination_local`,
        dataPost
      );
    } else {
      response = await axios.post(
        `${baseurl}createAllTableText?table=examination_local`,
        dataPost
      );
    }

    // ✅ Check if response exist
    if (!response) {
      Swal.fire("Error", "No response from server.", "error");
      return;
    }

    // ✅ Success response (200/201)
    if (response.status === 200 || response.status === 201) {
      hndleclosemodalservice();
      getdata();
      Swal.fire(
        "Success",
        `Examination Local ${isEditMode ? "updated" : "added"} successfully.`,
        "success"
      );
    }
    // ✅ Client errors (400–499)
    else if (response.status >= 400 && response.status < 500) {
      Swal.fire(
        "Client Error",
        response.data?.message || "Invalid request. Please check your input.",
        "warning"
      );
    }
    // ✅ Server errors (500–599)
    else if (response.status >= 500) {
      Swal.fire(
        "Server Error",
        response.data?.message || "Server is currently unavailable. Try again later.",
        "error"
      );
    }
    // ✅ Unexpected status
    else {
      Swal.fire("Error", "Unexpected server response.", "error");
    }
  } catch (error) {
    console.error("Error saving service:", error);

    // ✅ Handle axios specific errors
    if (error.response) {
      // Server responded with error status
      Swal.fire(
        "Error",
        error.response.data?.message ||
          `Request failed with status ${error.response.status}`,
        "error"
      );
    } else if (error.request) {
      // Request was sent but no response
      Swal.fire(
        "Network Error",
        "No response received from server. Please check your internet connection.",
        "error"
      );
    } else {
      // Something else happened
      Swal.fire(
        "Error",
        error.message || "Something went wrong. Please try again.",
        "error"
      );
    }
  }
};


  return (
    <div className="pc-container ">
      <div className="pc-content">
        <div className="row">
          <div className="col-12 searchParent">
            <h5>Examination Local list</h5>
          </div>
          <div className="col-md-12">
            <div className="card table-card patientCardHeader">
              <div className="tableHeader">
                <div className="d-sm-flex align-items-center justify-content-between">
                  <div className="tableSearch">
                    <input
                      type="text"
                      placeholder="Search"
                      className="form-control"
                      value={searchTerm}
                      onChange={handleSearchChange}
                    />
                    <span className="searchIcon">
                      <svg
                        xmlns="http:www.w3.org/2000/svg"
                        width="18"
                        height="18"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="gray"
                        style={{
                          position: "absolute",
                          top: "50%",
                          left: "10px",
                          transform: "translateY(-50%)",
                          pointerEvents: "none",
                        }}
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M21 21l-4.35-4.35M17 10a7 7 0 11-14 0 7 7 0 0114 0z"
                        />
                      </svg>
                    </span>
                  </div>
                  <div className="tableHeaderBtn">
                    <button className="bgBtn" onClick={handleclickopenvital11}>
                      <i className="fas fa-plus me-2"></i> Add Examination Local
                    </button>
                  </div>
                </div>
              </div>
              <div className="card-body pb-0">
                <div className="table-responsive table-striped">
                  <table className="table">
                    <thead>
                      <tr>
                        <th>SR NO</th>
                        <th>Examination Local</th>
                        <th className="text-center">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {currentPatients.length > 0 ? (
                        currentPatients.map((item, index) => (
                          <tr key={index}>
                            <td>{indexOfFirst + index + 1}</td>
                            <td>{item.text}</td>
                            <td>
                              <div
                                onClick={() => viewmoal(item)}
                                className="avtar avtar-xs btn-link-secondary viewIcon"
                              >
                                <i className="ti ti-eye f-20" />
                                <span>View</span>
                              </div>
                              <a
                                className="avtar avtar-xs btn-link-secondary editIcon"
                                onClick={() => handleEdit(item)}
                              >
                                <i className="ti ti-edit f-20" />
                                <span>Edit</span>
                              </a>
                              <div
                                style={{ cursor: "pointer" }}
                                className="avtar avtar-xs btn-link-secondary deleteIcon"
                                onClick={() => handledelete(item.id)}
                              >
                                <i className="ti ti-trash f-20" />
                                <span>Delete</span>
                              </div>
                            </td>
                          </tr>
                        ))
                      ) : (
                        <tr>
                          <td colSpan="10" className="text-center">
                            No Service found.
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
                {totalPages > 1 && (
                  <nav className="tablepagination">
                    <ul className="pagination justify-content-end mb-0 me-3">
                      <li
                        className={`page-item ${
                          currentPage === 1 ? "disabled" : ""
                        }`}
                      >
                        <button
                          className="page-link"
                          onClick={() =>
                            currentPage > 1 && setCurrentPage(currentPage - 1)
                          }
                        >
                          &laquo;
                        </button>
                      </li>
                      <li className="pageNmbr">{`${currentPage} of ${totalPages}`}</li>
                      <li
                        className={`page-item ${
                          currentPage === totalPages ? "disabled" : ""
                        }`}
                      >
                        <button
                          className="page-link"
                          onClick={() =>
                            currentPage < totalPages &&
                            setCurrentPage(currentPage + 1)
                          }
                        >
                          &raquo;
                        </button>
                      </li>
                    </ul>
                  </nav>
                )}
              </div>
              {editabledata && (
                <div
                  className="modal fade show"
                  style={{
                    backgroundColor: "rgba(81, 81, 81, 0.5)",
                    display: "block",
                  }}
                >
                  <div className="modal-dialog modal-lg">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h5 className="modal-title">
                          {isEditMode
                            ? "Edit Examination Local"
                            : "View Examination Local"}
                        </h5>
                        <button
                          type="button"
                          className="btn-close"
                          onClick={handleclickoffmodal}
                        ></button>
                      </div>
                      <div className="modal-body">
                        <div className="row">
                          <div className="col-md-12">
                            <label className="form-label">
                              Examination Local
                            </label>
                            <input
                              type="text"
                              name="description"
                              value={inpval.description}
                              disabled={!isEditMode}
                              placeholder="Enter Examination Local"
                              className="form-control"
                            />
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
              {openVital121 && (
                <div
                  className="modal fade show"
                  style={{
                    backgroundColor: "rgba(81, 81, 81, 0.5)",
                    display: "block",
                  }}
                >
                  <div className="modal-dialog modal-lg">
                    <div className="modal-content">
                      <div className="modal-header">
                        <h5 className="modal-title">
                          {isEditMode
                            ? "Edit Examination Local"
                            : "Add Examination Local"}
                        </h5>
                        <button
                          type="button"
                          className="btn-close"
                          onClick={hndleclosemodalservice}
                        ></button>
                      </div>
                      <div className="modal-body">
                        <div className="row">
                          <div className="col-md-12">
                            <label className="form-label">
                              Examination Local
                            </label>
                            <input
                              type="text"
                              name="description"
                              value={inpval.description}
                              onChange={handlechange}
                              placeholder="Enter Examination Local"
                              className="form-control"
                            />
                          </div>
                        </div>
                        <div className="modal-footer my-3 text-center justify-content-center">
                          <button
                            type="button"
                            className="btn btn-primary"
                            onClick={handlesavevital123}
                          >
                            {isEditMode
                              ? "Update Examination Local"
                              : "Add Examination Local"}
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
